  select 'Segons la Llei 19/2020, d''igualtat de tracte i no discriminació, què és l''aporofòbia?', 'Les altres definicions corresponen al capacitisme, l''antisemitisme i la discriminació de segon ordre (art. 4).', 'bombexamen_2025', (select id from public.topics where slug = 'bombexamen-2025'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2021-1663'), 'Rèplica 81/25 (cf. 26) · Art. 4.d Llei 19/2020', 'd) Aporofobia: El rechazo, el desprecio o el odio hacia las personas pobres, sin techo o sin hogar.', null, 'ed2cb0e99586768414db69abf37a0d059e9e9f91dbca4c42181519274d4e68d3', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'ed2cb0e99586768414db69abf37a0d059e9e9f91dbca4c42181519274d4e68d3')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'L''aversió o la discriminació contra les persones amb diversitat funcional.', false), ('B', 'El rebuig, el menyspreu o l''odi cap a les persones pobres, sense sostre o sense llar.', true), ('C', 'L''hostilitat o el prejudici cap als jueus com a grup religiós o ètnic.', false), ('D', 'El maltractament contra persones pel fet de defensar persones discriminades.', false)) as v(label, body, ok)
)
