  select 'Quins són els tres mecanismes principals de transmissió de la calor?', 'Són els tres mecanismes que expliquen la propagació d''un incendi.', 'bombexamen_2025', (select id from public.topics where slug = 'bombexamen-2025'), 1, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-08-MAN.GRAL.008.pdf'), 'Rèplica 81/25 (cf. 5) · MAN.GRAL.008', 'Hi ha tres mecanismes principals de transmissió de la calor: conducció, convecció i radiació.', null, '37e44a4852dbf059c508b2a837f9009da19756db767b94e3fb618095bbb95892', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '37e44a4852dbf059c508b2a837f9009da19756db767b94e3fb618095bbb95892')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Conducció, combustió i radiació.', false), ('B', 'Conducció, convecció i radiació.', true), ('C', 'Convecció, oxidació i radiació.', false), ('D', 'Conducció, convecció i piròlisi.', false)) as v(label, body, ok)
)
