with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Com s''anomena la reignició explosiva d''un incendi que es troba en una fase de ventilació limitada quan hi entra aire de cop?', 'El flashover és la transició ràpida a incendi totalment desenvolupat; el backdraft requereix una entrada sobtada d''aire en un recinte amb ventilació limitada.', 'bombexamen_2025', (select id from public.topics where slug = 'bombexamen-2025'), 1, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-08-MAN.GRAL.008.pdf'), 'Rèplica 81/25 (cf. 50) · MAN.GRAL.008', 'Backdraft El backdraft és una reignició explosiva d''un incendi que es troba en una fase de ventilació limitada.', null, '11d9456afc27d02e3ca10ef710a03bb89e77bc6c2b43a1176eb2cbf0fb0f9562', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '11d9456afc27d02e3ca10ef710a03bb89e77bc6c2b43a1176eb2cbf0fb0f9562')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Flashover.', false), ('B', 'BLEVE.', false), ('C', 'Boilover.', false), ('D', 'Backdraft.', true)) as v(label, body, ok)
)
