with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Quina d''aquestes afirmacions sobre les classes de foc és CORRECTA?', 'L''electricitat és una font d''ignició, no una classe de foc; els olis i greixos de cuina són classe F.', 'bombexamen_2025', (select id from public.topics where slug = 'bombexamen-2025'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-08-MAN.GRAL.008.pdf'), 'Rèplica 81/25 (cf. R1) · MAN.GRAL.008', 'No existeix una Classe E de focs elèctrics.', null, 'd9b1fdd3d4667e7675c6d1c8e0161b4e39597f0a5832ef5b906747d3d8892cbd', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'd9b1fdd3d4667e7675c6d1c8e0161b4e39597f0a5832ef5b906747d3d8892cbd')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Els focs elèctrics són de classe E.', false), ('B', 'Els focs de metalls són de classe A.', false), ('C', 'Els focs d''olis de cuina són de classe B.', false), ('D', 'No existeix una classe E de focs elèctrics.', true)) as v(label, body, ok)
)
