with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Quin és el rang d''inflamabilitat aproximat del metà (gas natural) en aire, en % en volum?', 'El manual dona per al metà un límit inferior del 5% i un superior del 15%; com més ampli és el rang, més risc.', 'bombexamen_2025', (select id from public.topics where slug = 'bombexamen-2025'), 3, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-08-MAN.GRAL.008.pdf'), 'Rèplica 81/25 (cf. 90) · MAN.GRAL.008', 'Metà (gas natural) 5 15 10 […] Com més ampli sigui aquest rang, més gran és el risc que la substància formi una barreja perillosa amb capacitat d’encendre’s.', null, '88edfaac8b35d3ee431a47e6be6244b3ec406e39a1d296b08a2653246a08d60e', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '88edfaac8b35d3ee431a47e6be6244b3ec406e39a1d296b08a2653246a08d60e')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Entre el 5% i el 15%.', true), ('B', 'Entre l''1,8% i el 8,4%.', false), ('C', 'Entre el 12,5% i el 74%.', false), ('D', 'Entre el 2,5% i el 100%.', false)) as v(label, body, ok)
)
