with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'En un incendi, la calor fa que l''aigua interna del formigó s''evapori i que se''n desprengui la capa superficial, deixant el ferro a la vista. Com s''anomena aquest fenomen?', 'El spalling deixa al descobert el ferro intern, que aleshores perd resistència de pressa. El vinclament és una deformació lateral per compressió i el boil-over afecta dipòsits de líquids.', 'bombexamen_2025', (select id from public.topics where slug = 'bombexamen-2025'), 1, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-08-MAN.GRAL.008.pdf'), 'Rèplica 81/25 (cf. 3) · MAN.GRAL.008, § 10.2', 'les altes temperatures poden provocar l''evaporació de l''aigua interna, generant tensions que causen el despreniment de la capa superficial (fenomen conegut com a spalling). Això deixa al descobert el ferro intern, que aleshores perd resistència de forma accelerada.', null, 'ee7f3028fef9d515dfdb3d2c94a6388152a77e3da014df12b27c5b757509795b', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'ee7f3028fef9d515dfdb3d2c94a6388152a77e3da014df12b27c5b757509795b')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Vinclament.', false), ('B', 'Boil-over.', false), ('C', 'Spalling.', true), ('D', 'Carbonització.', false)) as v(label, body, ok)
)
