with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'En un incendi de vegetació (combustible sòlid de classe A), quin és el mecanisme d''extinció principal de l''aigua?', 'L''aigua absorbeix molta calor, sobretot en vaporitzar-se; la sufocació pel vapor és un efecte secundari.', 'bombexamen_2025', (select id from public.topics where slug = 'bombexamen-2025'), 1, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-08-MAN.GRAL.008.pdf'), 'Rèplica 81/25 (cf. 60) · MAN.GRAL.008, § 13.2.1', '1) Refredament (principal): L''aigua té una extraordinària capacitat d''absorbir calor. […] Camp d''aplicació: Principalment eficaç en focs de Classe A (materials sòlids amb brases: fusta, paper, teixits, etc.).', null, '9562ff923b04fc731238a015e830779ab3ad90f8e06c371b8b2066c92c9134af', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '9562ff923b04fc731238a015e830779ab3ad90f8e06c371b8b2066c92c9134af')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La inhibició de la reacció en cadena.', false), ('B', 'La saponificació.', false), ('C', 'El refredament.', true), ('D', 'La sufocació, que és més important que el refredament.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Què indica la sigla AR en la denominació d''un escumogen (per exemple, AR-FFF)?', 'Les escumes convencionals es destrueixen sobre combustibles miscibles amb l''aigua (alcohols, cetones…); les AR hi formen una barrera protectora.', 'bombexamen_2025', (select id from public.topics where slug = 'bombexamen-2025'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-08-MAN.GRAL.008.pdf'), 'Rèplica 81/25 (cf. 65) · MAN.GRAL.008, § 13.2.2', 'Escumes Resistents a Alcohols (AR): Dissenyades per a combustibles polars (com alcohols, cetones, èsters, etc.) que, per la seva miscibilitat amb l''aigua, destruirien les escumes convencionals.', null, 'a2186d14715aaa0fbe05490e332903d6b3fdd32df10849a7be166dca753a4572', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'a2186d14715aaa0fbe05490e332903d6b3fdd32df10849a7be166dca753a4572')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Que és d''alta expansió.', false), ('B', 'Que és d''origen proteínic animal.', false), ('C', 'Que està pensat per a sistemes d''aire comprimit.', false), ('D', 'Que és resistent als alcohols i apte per a combustibles polars.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'De què depèn principalment la velocitat amb què es transmet la calor per conducció a través d''un sòlid?', 'Els metalls són bons conductors; la fusta i l''aire són bons aïllants. La convecció depèn del moviment de fluids i la radiació, de les ones electromagnètiques.', 'bombexamen_2025', (select id from public.topics where slug = 'bombexamen-2025'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-08-MAN.GRAL.008.pdf'), 'Rèplica 81/25 (cf. 75) · MAN.GRAL.008, § 9.1.1', 'És el principal mecanisme de transmissió de calor en sòlids. La velocitat de conducció depèn de la conductivitat tèrmica del material: els metalls són bons conductors, la fusta o l''aire són bons aïllants.', null, 'be6469d5e007877ac7e8c23197a84327fbd51ddaf7e2b06d7c0660a90e73abed', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'be6469d5e007877ac7e8c23197a84327fbd51ddaf7e2b06d7c0660a90e73abed')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'De la conductivitat tèrmica del material.', true), ('B', 'Del moviment dels gasos calents al voltant del sòlid.', false), ('C', 'De les ones electromagnètiques que emet la flama.', false), ('D', 'De la densitat de vapor relativa del material.', false)) as v(label, body, ok)
)
