with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'En la inspecció posterior a un incendi trobes que una peça d''un material s''ha fos completament. Què en pots deduir sobre la temperatura que s''hi va assolir?', 'Cada canvi d''estat es produeix a una temperatura concreta que depèn del material; si s''ha fos, s''ha arribat almenys a la seva temperatura de fusió.', 'bombexamen_2025', (select id from public.topics where slug = 'bombexamen-2025'), 1, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-10-MAN.GRAL.004.pdf'), 'Rèplica 81/25 (cf. 34) · MAN.GRAL.004, § 6.2', 'Fusió: sòlid → líquid […] Si aquests canvis es realitzen a pressió atmosfèrica, cada canvi es produirà només a una temperatura concreta que dependrà del material.', null, 'bdca3ebe4bac13779a7e99e7df4ebb355dc94743bf5eef58aa2edc55c3aaf08b', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'bdca3ebe4bac13779a7e99e7df4ebb355dc94743bf5eef58aa2edc55c3aaf08b')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
