with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Un extintor de CO₂ ha quedat exposat al sol i el seu contingut ha superat els 31 °C. Segons la taula de temperatures crítiques del manual de química, en quin estat es troba ara el CO₂ de l''interior?', 'El CO₂ dels extintors es guarda liquat, però per sobre de la temperatura crítica (30,1 °C) ja no pot existir com a líquid.', 'bombexamen_2025', (select id from public.topics where slug = 'bombexamen-2025'), 3, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-10-MAN.GRAL.004.pdf'), 'Rèplica 81/25 (cf. 47) · MAN.GRAL.004, § 6.2 (punt crític)', 'El punt crític d''una substància és la temperatura per sobre de la qual trobarem aquesta substància en un estat gasós i no el podrem liquar encara que se n''augmenti molt la pressió. […] Diòxid de carboni 30.1 72.9', null, 'cae00333485b1f2d729479efba7f3f7379434ef406727ee9e373a141a043e06c', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'cae00333485b1f2d729479efba7f3f7379434ef406727ee9e373a141a043e06c')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'En estat líquid, perquè l''alta pressió interior el manté liquat a qualsevol temperatura.', false), ('B', 'En estat sòlid (neu carbònica).', false), ('C', 'En equilibri líquid-gas, igual que a temperatura ambient.', false), ('D', 'En estat gasós, perquè ha superat la temperatura crítica (30,1 °C) i no es pot liquar encara que n''augmenti la pressió.', true)) as v(label, body, ok)
)
