with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Un conjunt de plaques fotovoltaiques lliura a l''inversor 400 V en corrent continu amb una intensitat de 12 A. Quina potència subministra?', 'Les plaques generen corrent continu, on P = V × I = 400 V × 12 A = 4.800 W.', 'bombexamen_2025', (select id from public.topics where slug = 'bombexamen-2025'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-11-MAN.GRAL.005.pdf'), 'Rèplica 81/25 (cf. 15) · MAN.GRAL.005, § 4.3 i 7.1', 'La formula (bàsica) per calcular la potència elèctrica és vàlida en corrent continu o per càrregues purament resistives en corrent altern: P = V × I […] Energia fotovoltaica: Les plaques fotovoltaiques generen corrent continu directament de la llum solar.', null, 'a2e469cd15e11d5a6e52102d6ea0d2587f6832a7f6669f84704b9761f094467a', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'a2e469cd15e11d5a6e52102d6ea0d2587f6832a7f6669f84704b9761f094467a')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', '33,3 W.', false), ('B', '412 W.', false), ('C', '4.800 W.', true), ('D', '48.000 W.', false)) as v(label, body, ok)
)
