with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la llei d''Ohm, si en un circuit es manté la resistència i es duplica la tensió aplicada, què passa amb la intensitat?', 'I = V / R: amb R constant, la intensitat és directament proporcional a la tensió.', 'bombexamen_2025', (select id from public.topics where slug = 'bombexamen-2025'), 1, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-11-MAN.GRAL.005.pdf'), 'Rèplica 81/25 (cf. 27) · MAN.GRAL.005, § 4.1', 'La intensitat de corrent que circula per un conductor és directament proporcional a la tensió aplicada en els seus extrems i inversament proporcional a la resistència del conductor.', null, '03e264df330eb66d24a6a76fafecb27578683b908c56188e26236257918e570a', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '03e264df330eb66d24a6a76fafecb27578683b908c56188e26236257918e570a')
  returning id
), o as (
