with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'En un local hi ha 20 punts de llum de 115 W cadascun, connectats en paral·lel a 230 V. Quina intensitat total consumeixen quan estan tots encesos?', 'Cada punt consumeix I = P / V = 115 / 230 = 0,5 A. En paral·lel les intensitats se sumen: 20 × 0,5 = 10 A (o bé 2.300 W / 230 V = 10 A).', 'bombexamen_2025', (select id from public.topics where slug = 'bombexamen-2025'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-11-MAN.GRAL.005.pdf'), 'Rèplica 81/25 (cf. 32) · MAN.GRAL.005, § 4.3 i 5.2.2', 'P = V × I […] La intensitat total del circuit és la suma de les intensitats de cada branca:', null, 'ef35bdb1ee6d0ec5e5d6567c4c5dba3fa091738a40c8736c49a7fab350c5fa89', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'ef35bdb1ee6d0ec5e5d6567c4c5dba3fa091738a40c8736c49a7fab350c5fa89')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
