with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Què explica físicament que es formi un arc elèctric entre dues fases?', 'L''arc genera calor i llum intenses, capaços de fondre metalls i provocar cremades a distància.', 'bombexamen_2025', (select id from public.topics where slug = 'bombexamen-2025'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-11-MAN.GRAL.005.pdf'), 'Rèplica 81/25 (cf. 36) · MAN.GRAL.005, § 9.2', 'Arc elèctric: Es produeix quan el corrent "salta" per l''aire entre dos punts amb diferent tensió, l’aire es ionitza i es converteix en conductor (plasma).', null, 'd9bcf771e79c158af5ea8c719a2064230c78335443d833912cf696e98a321f1a', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'd9bcf771e79c158af5ea8c719a2064230c78335443d833912cf696e98a321f1a')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'L''aire entre dos punts amb diferent tensió s''ionitza i es converteix en conductor (plasma), i el corrent hi salta.', true), ('B', 'L''aire es converteix en un aïllant perfecte i el corrent s''acumula als conductors.', false), ('C', 'El neutre absorbeix la diferència de tensió entre les dues fases.', false), ('D', 'Només és possible en corrent continu, perquè en altern el corrent passa per zero.', false)) as v(label, body, ok)
)
