with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Un dia de pluja intensa salta la protecció del quadre del parc i, en rearmar-la, torna a saltar. Quina protecció detecta les fuites de corrent a terra?', 'La humitat afavoreix les fuites a terra, que són el que detecta el diferencial; els magnetotèrmics protegeixen de sobrecàrregues i curtcircuits.', 'bombexamen_2025', (select id from public.topics where slug = 'bombexamen-2025'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.GRAL.007-Tema-12.-Installacions.pdf'), 'Rèplica 81/25 (cf. 40) · MAN.GRAL.007', 'Diferencials Els diferencials són la protecció més important per a la seguretat de les persones, ja que detecten fuites de corrent a terra.', null, '9cf62fbdf1d9f6db423b169a70c47559d74c078523479f978a31b918cf483b32', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '9cf62fbdf1d9f6db423b169a70c47559d74c078523479f978a31b918cf483b32')
  returning id
), o as (
