  select q.id, v.label, v.body, v.ok from q, (values ('A', 'L''IGA (interruptor general automàtic).', false), ('B', 'L''interruptor diferencial.', true), ('C', 'L''ICP o limitador de potència.', false), ('D', 'El fusible de la CGP.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'En un servei per olor de gas en un habitatge, el comandament et demana que tallis el subministrament de gas de tota la instal·lació de l''habitatge abans d''entrar-hi. Quin element has d''accionar?', 'La clau general de pas talla tota la instal·lació; la clau de connexió d''aparell només n''aïlla un, i la vàlvula incorporada a l''aparell no s''ha de confondre amb la clau de la instal·lació.', 'bombexamen_2025', (select id from public.topics where slug = 'bombexamen-2025'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.GRAL.007-Tema-12.-Installacions.pdf'), 'Rèplica 81/25 (cf. 8) · MAN.GRAL.007, § 4.2.1', 'Abans d’entrar a l’habitatge, i en un punt de fàcil accés, hi ha la clau general de pas, que permet tallar el subministrament a tota la instal·lació.', null, '50b861a2024aff091cf99d913e09c173168cb662ffe72d1e89b2fd747f160a81', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '50b861a2024aff091cf99d913e09c173168cb662ffe72d1e89b2fd747f160a81')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La clau de connexió de l''aparell que sospites que fuita.', false), ('B', 'La vàlvula que porta incorporada la caldera.', false), ('C', 'La clau general de pas, situada abans d''entrar a l''habitatge en un punt de fàcil accés.', true), ('D', 'La reixeta de ventilació de la cuina.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'En una instal·lació domèstica de gas butà amb bombona, quina és la funció del regulador de pressió?', 'Els elements principals són la bombona (que guarda el gas liquat a pressió), el regulador i el tub flexible. El regulador porta incorporada una clau de pas.', 'bombexamen_2025', (select id from public.topics where slug = 'bombexamen-2025'), 1, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.GRAL.007-Tema-12.-Installacions.pdf'), 'Rèplica 81/25 (cf. 16) · MAN.GRAL.007, § 4.1', 'els elements principals de la instal·lació de gas butà són la bombona, el regulador de pressió i el tub flexible. […] El regulador de pressió té la funció de subministrar el combustible a una pressió baixa i constant.', null, '6364474d52b3e24bd9c8b60acf3caacbd62950b1c973c61a8590e885b9e52f82', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '6364474d52b3e24bd9c8b60acf3caacbd62950b1c973c61a8590e885b9e52f82')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Emmagatzemar el gas en estat líquid.', false), ('B', 'Augmentar la pressió del gas fins a la de la xarxa de distribució.', false), ('C', 'Evacuar a l''exterior els gasos de la combustió.', false), ('D', 'Subministrar el combustible a una pressió baixa i constant.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'En un habitatge s''ha cremat la campana extractora de la cuina, connectada al circuit de la vitroceràmica. Si has identificat aquest circuit al quadre, què et permet fer l''estructura de circuits independents que exigeix el REBT?', 'Cada circuit (enllumenat, endolls, cuina i forn…) té el seu interruptor de protecció; així es pot aïllar el circuit afectat sense deixar sense llum, nevera ni aigua calenta la resta de la casa.', 'bombexamen_2025', (select id from public.topics where slug = 'bombexamen-2025'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.GRAL.007-Tema-12.-Installacions.pdf'), 'Rèplica 81/25 (cf. 17) · MAN.GRAL.007, § 2.2.7', 'La normativa (REBT) estableix una estructura de circuits independents (enllumenat, endolls, cuina i forn, rentadora...), amb els seus respectius interruptors de protecció. […] si identifiquem el problema i entenem la instal·lació, podem baixar el magnetotèrmic corresponent i no cal treure la llum de tota la casa', null, '0bc9eeeaccdc068371316538d89742e7bb54124479ab8d8d3db73609b0061fd6', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '0bc9eeeaccdc068371316538d89742e7bb54124479ab8d8d3db73609b0061fd6')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Baixar només el magnetotèrmic d''aquest circuit i mantenir la resta de l''habitatge amb subministrament.', true), ('B', 'Res: cal baixar sempre l''IGA i deixar sense llum tot l''habitatge.', false), ('C', 'Res: només es pot tallar des de la caixa general de protecció de l''edifici.', false), ('D', 'Desconnectar la presa de terra del circuit afectat.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'En la instal·lació de gas natural d''un edifici, què ha de tenir cada regulador de pressió?', 'El regulador redueix la pressió de distribució (fins a 4 bar) a la de servei dels aparells; la seva clau ha de ser accessible amb grau 1 o 2.', 'bombexamen_2025', (select id from public.topics where slug = 'bombexamen-2025'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.GRAL.007-Tema-12.-Installacions.pdf'), 'Rèplica 81/25 (cf. 55) · MAN.GRAL.007, § 4.2.1', 'Cada regulador ha de disposar d’una clau de pas pròpia situada just abans del dispositiu, en el mateix recinte, i ha de ser accessible amb grau 1 o 2 tant per a l’usuari com per a la companyia subministradora.', null, '3fc3499d7af99e81ac47310f92a8cd36d052eabb1afda2689cd612e390b76b0c', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '3fc3499d7af99e81ac47310f92a8cd36d052eabb1afda2689cd612e390b76b0c')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Una clau de pas situada dins de l''habitatge, després del comptador.', false), ('B', 'Un tub flexible de seguretat de més d''1,5 m.', false), ('C', 'Cap clau de pas, perquè el mateix regulador ja talla el gas.', false), ('D', 'Una clau de pas pròpia situada just abans del dispositiu, en el mateix recinte.', true)) as v(label, body, ok)
)
