insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('bombers-generalitat') and t.slug = 'bombexamen-2025' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Una cisalla hidràulica de rescat multiplica la força gràcies a un circuit tancat ple d''oli amb èmbols de seccions diferents. En quin principi físic es basa?', 'La pressió aplicada en un punt del líquid tancat es transmet igual a tot el líquid; amb un èmbol de més superfície s''obté més força (F = P · S).', 'bombexamen_2025', (select id from public.topics where slug = 'bombexamen-2025'), 1, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-13-MAN.GRAL.009.pdf'), 'Rèplica 81/25 (cf. 7) · MAN.GRAL.009, § 3.3', 'Segons el principi de Pascal, "La pressió exercida en un punt qualsevol d’un líquid tancat i en repòs es transmet amb la mateixa intensitat i en totes les direccions a tots els punts del líquid i a les parets del recipient que el conté." […] Un gat hidràulic és una màquina basada en principi de Pascal.', null, 'ff94d4211dbdb8b493152c3c8441d5697dd5f0afeaecb39e2005532659fdacdb', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'ff94d4211dbdb8b493152c3c8441d5697dd5f0afeaecb39e2005532659fdacdb')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'En el principi d''Arquímedes.', false), ('B', 'En l''efecte Venturi.', false), ('C', 'En el teorema de Torricelli.', false), ('D', 'En el principi de Pascal.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'En una instal·lació llarga de mànegues, quina d''aquestes accions redueix més les pèrdues de càrrega i, per tant, en millora més el rendiment hidràulic?', 'Les pèrdues de càrrega són inversament proporcionals a la cinquena potència del diàmetre; en canvi, creixen amb la longitud i amb el quadrat del cabal, i les T en provoquen de singulars.', 'bombexamen_2025', (select id from public.topics where slug = 'bombexamen-2025'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-13-MAN.GRAL.009.pdf'), 'Rèplica 81/25 (cf. 35) · MAN.GRAL.009, § 4.4', 'Són inversament proporcionals a la 5ena potència del diàmetre, és a dir, augmentar una mica el diàmetre pot representar una disminució notable de les pèrdues de càrrega lineals.', null, 'd746e66fcabbcb3acebd38e74c0e72196910114316bd6aa4cbfbea79bcaec0f6', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'd746e66fcabbcb3acebd38e74c0e72196910114316bd6aa4cbfbea79bcaec0f6')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Augmentar el cabal que hi circula.', false), ('B', 'Augmentar el diàmetre de les mànegues.', true), ('C', 'Afegir més trams de mànega a la instal·lació.', false), ('D', 'Intercalar bifurcacions en T.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Sobre la pressió de vapor d''un líquid, indica l''afirmació INCORRECTA:', 'La pressió de vapor augmenta amb la temperatura.', 'bombexamen_2025', (select id from public.topics where slug = 'bombexamen-2025'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-13-MAN.GRAL.009.pdf'), 'Rèplica 81/25 (cf. 83) · MAN.GRAL.009, § 2.3', 'Cada líquid té la seva pròpia pressió de vapor que augmenta a mesura que la temperatura puja. El punt d''ebullició d''un líquid és la temperatura a la qual la seva pressió de vapor s''iguala a la pressió de l''ambient que l''envolta.', null, '7f2bee71a75f3ac7a7270e55b71cb870148f7f7897a8b044d40333fad3bd8f03', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '7f2bee71a75f3ac7a7270e55b71cb870148f7f7897a8b044d40333fad3bd8f03')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Cada líquid té la seva pròpia pressió de vapor.', false), ('B', 'Disminueix a mesura que puja la temperatura.', true), ('C', 'Un líquid bull quan la seva pressió de vapor s''iguala a la pressió de l''ambient.', false), ('D', 'A dalt d''una muntanya l''aigua bull per sota de 100 °C perquè la pressió atmosfèrica és més baixa.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''efecte Venturi, què passa quan un fluid circula per un conducte tancat que s''estreny?', 'Per continuïtat el cabal es manté i la velocitat creix; per Bernoulli, el que es guanya en pressió dinàmica es perd en pressió estàtica. Els premescladors d''escumogen en línia en són una aplicació.', 'bombexamen_2025', (select id from public.topics where slug = 'bombexamen-2025'), 1, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-13-MAN.GRAL.009.pdf'), 'Rèplica 81/25 (cf. 84) · MAN.GRAL.009, § 4.5.1', 'L''efecte Venturi és un fenomen físic que es produeix quan un fluid circula per un conducte tancat que s’estreny, disminueix la seva pressió ja que augmenta la velocitat.', null, 'ee90bbd10adeada2e572818f0e543703434822a8867e9c564b875805332b1618', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'ee90bbd10adeada2e572818f0e543703434822a8867e9c564b875805332b1618')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'A l''estretament disminueix la velocitat i augmenta la pressió.', false), ('B', 'A l''estretament augmenten tant la velocitat com la pressió.', false), ('C', 'A l''estretament augmenta la velocitat i disminueix la pressió.', true), ('D', 'A l''estretament disminueix el cabal.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Quina d''aquestes pressions és la més gran?', '2 bar = 200.000 Pa; 1 atm = 101.325 Pa; 1.000 mmHg × 133,3 Pa = 133.300 Pa.', 'bombexamen_2025', (select id from public.topics where slug = 'bombexamen-2025'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-13-MAN.GRAL.009.pdf'), 'Rèplica 81/25 (cf. 87) · MAN.GRAL.009, § 3.1.1', '1 bar 100.000 Pa 1 atmosfera (atm) 101.325 Pa = 1,013 bar […] 1 mmHg (mil·límetres de mercuri) 133,3 Pa', null, 'c860cb78cb8f5acc1b162e60f08a9b0cbc5b38b8c6c95f5a65a8e01ce2ff882e', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'c860cb78cb8f5acc1b162e60f08a9b0cbc5b38b8c6c95f5a65a8e01ce2ff882e')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', '150.000 Pa.', false), ('B', '1 atm.', false), ('C', '2 bar.', true), ('D', '1.000 mmHg.', false)) as v(label, body, ok)
)
