with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Has de buidar un dipòsit obert que conté 18 m³ d''aigua amb una bomba que extreu un cabal constant de 1.200 l/min. Quant de temps trigaràs?', 'Q = V / t → t = V / Q = 18.000 l / 1.200 l/min = 15 min.', 'bombexamen_2025', (select id from public.topics where slug = 'bombexamen-2025'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-13-MAN.GRAL.009.pdf'), 'Rèplica 81/25 (cf. 92) · MAN.GRAL.009, § 4.2.1', 'Fa referència a la quantitat d’aigua que travessa una secció (S) d’una conducció en un temps determinat.', null, '928cbfbbc6dd57c464827390e3b818297327e74a7efc5356b4bcf4ba61c9b32b', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '928cbfbbc6dd57c464827390e3b818297327e74a7efc5356b4bcf4ba61c9b32b')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', '15 minuts.', true), ('B', '1,5 minuts.', false), ('C', '150 minuts.', false), ('D', '66,7 minuts.', false)) as v(label, body, ok)
)
