with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'En un mapa a escala 1:50.000, el punt B es troba exactament al sud del punt A, a 6 cm de distància sobre el paper. Quin rumb (azimut) has de seguir per anar d''A a B i quina distància real hi ha?', 'L''azimut és l''angle respecte al nord: el sud, sentit oposat al nord, queda a 180°. Distància: 6 cm × 50.000 = 300.000 cm = 3.000 m = 3 km.', 'bombexamen_2025', (select id from public.topics where slug = 'bombexamen-2025'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-14-MAN.GRAL.002.pdf'), 'Rèplica 81/25 (cf. 13) · MAN.GRAL.002, § 2.3.2 i 3.1', 'Escala numèrica: Es presenta en forma de fracció o ràtio (per exemple, 1:25.000). Això vol dir que 1 unitat de mesura al mapa (1 cm, 1 mm, etc.) equival a 25.000 de la mateixa unitat al terreny. […] La direcció es defineix mitjançant l''azimut, que és l''angle respecte al nord.', null, '3351a8565b5e98bdffb346087c09eaf653d52a3e7ae945d9ab7300caa5f8165d', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '3351a8565b5e98bdffb346087c09eaf653d52a3e7ae945d9ab7300caa5f8165d')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', '0° i 3 km.', false), ('B', '180° i 3 km.', true), ('C', '180° i 30 km.', false), ('D', '90° i 300 m.', false)) as v(label, body, ok)
)
