with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Per a una biga que ha de treballar a flexió, quin d''aquests materials és el menys adequat segons el manual de construcció?', 'La flexió combina compressió i tracció; la pedra és un material fràgil que només suporta bé la compressió, mentre que l''acer, la fusta i el formigó armat es comporten bé a flexió.', 'bombexamen_2025', (select id from public.topics where slug = 'bombexamen-2025'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.GRAL.006-Tema-15.-Manual-Op.-basic-construccio.pdf'), 'Rèplica 81/25 (cf. 9) · MAN.GRAL.006, § 2.4', 'La compressió és l’esforç que aixafa un element. Materials fràgils però resistents, com la pedra, la ceràmica, el formigó o la terra, la suporten molt bé. […] La flexió és la combinació de compressió i tracció en una peça que es corba. S’hi comporten bé l’acer, la fusta i el formigó armat.', null, 'fbbc2065b3534d611555c8614cb9a48c0271129225400c81bf91a266b2bbb58a', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'fbbc2065b3534d611555c8614cb9a48c0271129225400c81bf91a266b2bbb58a')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La pedra.', true), ('B', 'L''acer.', false), ('C', 'La fusta.', false), ('D', 'El formigó armat.', false)) as v(label, body, ok)
)
