select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Una biga amb un perfil en forma d''H (com un perfil HEB) és un element estructural de quin material?', 'Els perfils I, H o U són bigues metàl·liques (perfils laminats d''acer).', 'bombexamen_2025', (select id from public.topics where slug = 'bombexamen-2025'), 1, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.GRAL.006-Tema-15.-Manual-Op.-basic-construccio.pdf'), 'Rèplica 81/25 (cf. 54) · MAN.GRAL.006, § 4.3.2', 'Bigues metàl·liques (perfil I, H o U): molt comunes en edificis preindustrials i industrials.', null, '511db686354c620756d3cceef8efe92d715d17e8b18237bf83377753651fef33', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '511db686354c620756d3cceef8efe92d715d17e8b18237bf83377753651fef33')
  returning id
), o as (
