with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Has de tallar una barra metàl·lica massissa amb una cisalla. A quin tipus d''esforç sotmets la barra en el punt de tall?', 'L''esforç tallant fa lliscar una part de l''element respecte de l''altra; la tracció estira, la torsió retorça i el vinclament és una deformació lateral per compressió.', 'bombexamen_2025', (select id from public.topics where slug = 'bombexamen-2025'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.GRAL.006-Tema-15.-Manual-Op.-basic-construccio.pdf'), 'Rèplica 81/25 (cf. 78) · MAN.GRAL.006, § 2.4.5', 'Tallant o cisallament […] L’esforç tallant vol “lliscar” una part de l’element respecte l’altra.', null, '3268d11064fac07b37fcb07115bd8c6c1fdd2e485e5afbfd9fe8ad7a1109bb32', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '3268d11064fac07b37fcb07115bd8c6c1fdd2e485e5afbfd9fe8ad7a1109bb32')
  returning id
), o as (
