with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Sobre els tipus de fonaments, indica l''afirmació INCORRECTA:', 'Els pilots (pilons) són fonaments profunds: transmeten les càrregues a capes més profundes i resistents del subsòl.', 'bombexamen_2025', (select id from public.topics where slug = 'bombexamen-2025'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.GRAL.006-Tema-15.-Manual-Op.-basic-construccio.pdf'), 'Rèplica 81/25 (cf. 81) · MAN.GRAL.006, § 4 i 4.1.5', 'Fonaments: transmeten les càrregues de l’estructura al terreny. Poden ser superficials (sabates corregudes o aïllades) o profunds (pilons, murs pantalla). […] Elements cilíndrics clavats o perforats al subsòl per transmetre les càrregues a capes més profundes i resistents.', null, '258010b7efd56b36744ccd86fddf522ed32b1a35a8db3d6037f7b52cfb088683', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '258010b7efd56b36744ccd86fddf522ed32b1a35a8db3d6037f7b52cfb088683')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Les sabates corregudes són fonaments superficials.', false), ('B', 'Les sabatilles aïllades són fonaments superficials.', false), ('C', 'Els murs pantalla són fonaments profunds.', false), ('D', 'Els pilots són fonaments superficials.', true)) as v(label, body, ok)
)
