  select 'Quin d''aquests és un material habitual dels murs de càrrega?', 'Els murs de càrrega són de maó massís, pedra, tapial o formigó antic, amb gruixos de 20-60 cm; els altres són aïllaments o impermeabilitzacions.', 'bombexamen_2025', (select id from public.topics where slug = 'bombexamen-2025'), 1, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.GRAL.006-Tema-15.-Manual-Op.-basic-construccio.pdf'), 'Rèplica 81/25 (cf. R4) · MAN.GRAL.006, § 4.2.1', 'Materials habituals: maó massís, pedra, tapial, formigó antic.', null, '3d2d404e5d064a23a105acd89a806753730ea562ef36f2c0e3f9d882bca1e1b5', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '3d2d404e5d064a23a105acd89a806753730ea562ef36f2c0e3f9d882bca1e1b5')
