with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Quina és la funció del diferencial en la transmissió d''un vehicle?', 'En un revolt cada roda recorre una longitud diferent. Repartir el parell entre eixos és feina de la caixa de transferència, connectar el motor és de l''embragatge i adaptar les revolucions és de la caixa de canvis.', 'bombexamen_2025', (select id from public.topics where slug = 'bombexamen-2025'), 1, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-19-MAN.EQIP.002.pdf'), 'Rèplica 81/25 (cf. 14) · MAN.EQIP.002, § 5.5', 'El diferencial és el mecanisme encarregat de permetre un diferent nombre de revolucions a les rodes dels eixos motrius encara que els arribi un nombre constant des de l’arbre de transmissió.', null, '9cdd0610b7c2e7d8a5f2fdf363f491db1c14d418b673952378cede997d352034', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '9cdd0610b7c2e7d8a5f2fdf363f491db1c14d418b673952378cede997d352034')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Repartir el parell motor de la caixa de canvis entre l''eix davanter i el posterior.', false), ('B', 'Connectar o desconnectar el motor de la resta de la transmissió.', false), ('C', 'Adaptar les revolucions del motor per obtenir més força o més velocitat.', false), ('D', 'Permetre que les rodes d''un eix motriu girin a velocitats diferents, per exemple en un revolt.', true)) as v(label, body, ok)
)
