with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Quin d''aquests elements d''un vehicle és de seguretat passiva?', 'La seguretat passiva redueix les lesions un cop s''ha produït l''accident; l''ABS, l''ESP i el control de tracció són de seguretat activa.', 'bombexamen_2025', (select id from public.topics where slug = 'bombexamen-2025'), 1, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-19-MAN.EQIP.002.pdf'), 'Rèplica 81/25 (cf. 94) · MAN.EQIP.002, § 6.1', 'La seguretat passiva és el conjunt de sistemes i dispositius que tenen la funció de minimitzar les lesions i conseqüències d’un accident, un cop aquest ja s’ha produït. […] Coixins de seguretat (airbags)', null, '4c2a60868452700cc57c2eb1c0828902821363fda88574074a4ce9edd5f49521', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '4c2a60868452700cc57c2eb1c0828902821363fda88574074a4ce9edd5f49521')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'L''ABS.', false), ('B', 'El coixí de seguretat (airbag).', true), ('C', 'El control d''estabilitat (ESP).', false), ('D', 'El control de tracció.', false)) as v(label, body, ok)
)
