with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual de prevenció d''incendis, qui ha d''instal·lar les instal·lacions de protecció contra incendis d''un establiment?', 'A més, cal fer-hi el manteniment mínim que fixa el RIPCI (RD 513/2017).', 'bombexamen_2025', (select id from public.topics where slug = 'bombexamen-2025'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SP.000-Tema-23.-Prevencio-basica-incendis.pdf'), 'Rèplica 81/25 (cf. 18) · MAN.SP.000, § 4', 'Les instal·lacions de protecció contra incendis han de ser instal·lades per una empresa instal·ladora degudament autoritzada i el titular de l''establiment haurà de disposar del certificat d''instal·lació emès per un tècnic competent d''aquesta empresa instal·ladora.', null, '0a359a44a8206296cb105f817eeea49ff61b5b7d093441ad248b9c9ee22860ee', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '0a359a44a8206296cb105f817eeea49ff61b5b7d093441ad248b9c9ee22860ee')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Qualsevol electricista, sense cap certificat.', false), ('B', 'Una empresa instal·ladora degudament autoritzada; el titular ha de disposar del certificat d''instal·lació emès per un tècnic competent d''aquesta empresa.', true), ('C', 'El Cos de Bombers, que n''emet el certificat d''instal·lació.', false), ('D', 'El mateix titular de l''establiment, que només ho ha de comunicar a l''ajuntament.', false)) as v(label, body, ok)
)
