with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Arribes a un centre de dades protegit per un sistema d''extinció automàtica per agents gasosos. La central ja ha rebut senyal de les dues zones de detecció, però el gas encara no s''ha descarregat. Per què hi ha aquest retard?', 'Un cop disparat, l''atmosfera del recinte pot esdevenir asfixiant; per això cal el retard i un rètol de sistema disparat a l''entrada.', 'bombexamen_2025', (select id from public.topics where slug = 'bombexamen-2025'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SP.000-Tema-23.-Prevencio-basica-incendis.pdf'), 'Rèplica 81/25 (cf. 58) · MAN.SP.000, § 4.2.6', 'La central de detecció precisa rebre senyal d’ambdues zones simultàniament per tal de disparar el gas extintor, normalment després d’un retard temporal que serveix per advertir al personal present a la zona per tal que abandoni el recinte.', null, '05219aebf3835e0fcdba765ed1503c2588f230c520473a03126cef263244d2bf', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '05219aebf3835e0fcdba765ed1503c2588f230c520473a03126cef263244d2bf')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Per advertir el personal present perquè abandoni el recinte abans de la descàrrega.', true), ('B', 'Per esperar l''arribada dels bombers abans de descarregar.', false), ('C', 'Per deixar que primer actuïn els ruixadors d''aigua.', false), ('D', 'Perquè el gas s''ha d''escalfar abans de sortir de les ampolles.', false)) as v(label, body, ok)
)
