with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'En prevenció d''incendis, què és l''alçada d''evacuació d''un edifici?', 'No es compten les plantes més altes amb presència només ocasional o de manteniment (sales de màquines, trasters…).', 'bombexamen_2025', (select id from public.topics where slug = 'bombexamen-2025'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SP.000-Tema-23.-Prevencio-basica-incendis.pdf'), 'Rèplica 81/25 (cf. 69) · MAN.SP.000, § 7', 'Màxima diferència de cotes entre un origen d''evacuació i la sortida d''edifici que li correspongui. A l''efecte de determinar l''alçada d''evacuació d''un edifici no es consideren les plantes més altes en què la presència de persones sigui únicament ocasional o de manteniment', null, '38daca3cdbe819992cb72e1c9c32c9d773ae4bae45bd4ef8ab2560ca6f997f8f', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '38daca3cdbe819992cb72e1c9c32c9d773ae4bae45bd4ef8ab2560ca6f997f8f')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La màxima diferència de cotes entre un origen d''evacuació i la sortida d''edifici que li correspongui.', true), ('B', 'L''alçada total de l''edifici fins a la coberta, incloses les sales de màquines.', false), ('C', 'La longitud màxima del recorregut d''evacuació fins a la sortida.', false), ('D', 'El nombre de plantes sobre rasant multiplicat per tres metres.', false)) as v(label, body, ok)
)
