  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Quin codi de perill de la placa taronja ADR correspon a un líquid inflamable que reacciona amb l''aigua i desprèn gasos inflamables?', 'El 333 és una matèria líquida pirofòrica i el X423 un sòlid inflamable que reacciona violentament amb l''aigua.', 'bombexamen_2025', (select id from public.topics where slug = 'bombexamen-2025'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.RRTT.000-Tema-27.-Intervencio-NRBQ.pdf'), 'Rèplica 81/25 (cf. 24) · MAN.RRTT.000, § 2.2.2', '323 Líquid inflamable que reacciona amb l’aigua i desprèn gasos inflamables 333 Matèria líquida pirofòrica X423 Sòlid inflamable que reacciona violentament amb l’aigua i desprèn gasos inflamables', null, '514b5882f4620dc0ce57127d4648338075fc763cce70bfc357f3b8b705803d84', false
