with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Què és el Reglament CLP?', 'El transport per carretera és l''ADR; el rombe és la NFPA 704.', 'bombexamen_2025', (select id from public.topics where slug = 'bombexamen-2025'), 1, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.RRTT.000-Tema-27.-Intervencio-NRBQ.pdf'), 'Rèplica 81/25 (cf. 59) · MAN.RRTT.000, § 2.2.1', 'CLP (Classificació, Etiquetatge i Envasament) de la Unió Europea. és la norma europea sobre classificació, etiquetatge i envasament de substàncies i mescles. Aquest Reglament integra els criteris de classificació del sistema globalment harmonitzat de les Nacions Unides (SGA) a la legislació de la Unió Europea.', null, '83c51496b4a160dc2ea2a1f7aab9133cad3c5916fa9d0f5597272a349d02e52b', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '83c51496b4a160dc2ea2a1f7aab9133cad3c5916fa9d0f5597272a349d02e52b')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La norma europea sobre classificació, etiquetatge i envasament de substàncies i mescles, que integra els criteris del SGA de les Nacions Unides.', true), ('B', 'La normativa de transport de mercaderies perilloses per carretera.', false), ('C', 'El sistema del rombe de perill NFPA 704 per a instal·lacions fixes.', false), ('D', 'La normativa que estableix les normes per prevenir accidents greus a les indústries Seveso.', false)) as v(label, body, ok)
)
