  select 'Un camió porta una placa taronja ADR amb «33» a la part superior i «1203» a la part inferior. Què és el 1203?', 'El 33 és el codi de perill (líquid molt inflamable); el 1203 és el número ONU de la gasolina.', 'bombexamen_2025', (select id from public.topics where slug = 'bombexamen-2025'), 1, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.RRTT.000-Tema-27.-Intervencio-NRBQ.pdf'), 'Rèplica 81/25 (cf. 80) · MAN.RRTT.000, § 2.2.2', 'Número ONU (part inferior): número de 4 xifres que identifica la substància concreta (ex. 1203 = gasolina).', null, '07eabc68a3ed25fd55a4370b7e3bb7cf68c0aced50d8b06aed003cd5a733435f', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '07eabc68a3ed25fd55a4370b7e3bb7cf68c0aced50d8b06aed003cd5a733435f')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
