  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Davant d''una aturada cardiorespiratòria, quin és l''ordre correcte de les primeres baules de la cadena assistencial?', 'Primer cal identificar que la persona no respon i no respira amb normalitat i activar el 112; després RCP i DEA tan aviat com sigui possible; els equips sanitaris aporten el suport vital avançat.', 'bombexamen_2025', (select id from public.topics where slug = 'bombexamen-2025'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SANI.000-Tema-28.-Assistencia-sanitaria.pdf'), 'Rèplica 81/25 (cf. 38) · MAN.SANI.000, § cadena assistencial', '1) Prevenció de l’aturada cardíaca, reconeixement precoç i demanda d’ajuda: identificar ràpidament que la persona no respon i no respira amb normalitat, demanar ajuda i activar immediatament el sistema d’emergències mèdiques mitjançant el 112. 2) RCP i desfibril·lació precoces', null, '1eff4b5ab18e63442605c3f7be09f47d2956b1d44804c7756b9d06a5a80200fa', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '1eff4b5ab18e63442605c3f7be09f47d2956b1d44804c7756b9d06a5a80200fa')
  returning id
