with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'La cabina d''un ascensor electromecànic d''adherència s''ha aturat entre dues plantes amb persones a dins. Un cop a la cambra de màquines, quina és la seqüència correcta de la maniobra de rescat?', 'Primer es talla el corrent i després es desbloqueja el fre i es mou la cabina amb el volant, coordinant-se amb els efectius que estan en contacte amb les víctimes. La vàlvula de descàrrega és la maniobra dels ascensors hidràulics.', 'bombexamen_2025', (select id from public.topics where slug = 'bombexamen-2025'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-33-MAN.SVXX.000.pdf'), 'Rèplica 81/25 (cf. 6) · MAN.SVXX.000, § 3.2.1', 'Consisteix a accedir a la cambra de màquines, tallar el subministrament elèctric, desbloquejar el fre motor i iniciar la maniobra girant el volant fins a fer coincidir la cabina amb una planta transitable.', null, '7f0578759f34658d33addce13a65de0ceea24ff86a747d3d2bb166c5321b24ca', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '7f0578759f34658d33addce13a65de0ceea24ff86a747d3d2bb166c5321b24ca')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Tallar el subministrament elèctric, desbloquejar el fre motor i girar el volant fins que la cabina coincideixi amb una planta transitable.', true), ('B', 'Desbloquejar el fre motor, girar el volant i, quan la cabina arribi a planta, tallar el subministrament elèctric.', false), ('C', 'Activar la vàlvula de descàrrega manual perquè la cabina baixi lentament fins a la planta inferior.', false), ('D', 'Girar el volant amb el fre motor bloquejat i el corrent connectat per no perdre el control de la cabina.', false)) as v(label, body, ok)
)
