with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 1.3 de la Constitució espanyola, quina és la forma política de l''Estat espanyol?', 'L''art. 1.3 CE estableix que la forma política de l''Estat espanyol és la monarquia parlamentària.', 'bomb_t01_constitucio_estatut_generalitat', (select id from public.topics where slug = 'bomb-t01-constitucio-estatut-generalitat'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229'), 'Art. 1.3 CE', 'La forma política del Estado español es la Monarquía parlamentaria.', null, '0c92937e4754574fe672ae4691b83939a18c2d323503c82492a4abbeed5baea6', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '0c92937e4754574fe672ae4691b83939a18c2d323503c82492a4abbeed5baea6')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
