  select 'Quins són els valors superiors de l''ordenament jurídic que propugna l''article 1.1 de la Constitució espanyola?', 'L''art. 1.1 CE defineix Espanya com un Estat social i democràtic de dret que propugna aquests quatre valors superiors.', 'bomb_t01_constitucio_estatut_generalitat', (select id from public.topics where slug = 'bomb-t01-constitucio-estatut-generalitat'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229'), 'Art. 1.1 CE', 'propugna como valores superiores de su ordenamiento jurídico la libertad, la justicia, la igualdad y el pluralismo político.', null, 'a616ed09a5770960f104ae67033510a5a67255ac7de6e6e783566583200b1678', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'a616ed09a5770960f104ae67033510a5a67255ac7de6e6e783566583200b1678')
