  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Per a la reforma constitucional per la via ordinària de l''article 167 CE, quina majoria s''exigeix en cada cambra?', 'Si no hi ha acord, es crea una comissió paritària; i, si tampoc s''aconsegueix, el Congrés pot aprovar-la per dos terços sempre que el Senat hagi donat majoria absoluta. La via agreujada de l''art. 168 exigeix dos terços.', 'bomb_t01_constitucio_estatut_generalitat', (select id from public.topics where slug = 'bomb-t01-constitucio-estatut-generalitat'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229'), 'Art. 167 CE', 'Los proyectos de reforma constitucional deberán ser aprobados por una mayoría de tres quintos de cada una de las Cámaras.', null, '3c90890e92baef43de6ea9a0d3adf493679c13fbc117043d1cd10dd3e1f687de', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '3c90890e92baef43de6ea9a0d3adf493679c13fbc117043d1cd10dd3e1f687de')
  returning id
), o as (
