  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Dos terços.', false), ('B', 'Majoria absoluta.', false), ('C', 'Majoria simple.', false), ('D', 'Tres cinquenes parts.', true)) as v(label, body, ok)
)
