insert into public.sources (title, url, kind, publisher, published_on) values ('Ley 26/2010, de 3 de agosto, de régimen jurídico y de procedimiento de las administraciones públicas de Cataluña (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-2010-13313', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('bomb-t01-constitucio-estatut-generalitat', 'Tema 1. La Constitució, l''Estatut d''autonomia i l''organització de la Generalitat') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('bombers-generalitat') and t.slug = 'bomb-t01-constitucio-estatut-generalitat' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Llei 26/2010, de règim jurídic i de procediment de les administracions públiques de Catalunya, com s''adopten, en general, els acords dels òrgans col·legiats?', 'L''art. 19.1 de la Llei 26/2010 fixa la majoria simple, llevat que les normes de l''òrgan diguin una altra cosa; qui fa constar en acta el vot contrari o l''abstenció queda exempt de responsabilitat (art. 19.3).', 'bomb_t01_constitucio_estatut_generalitat', (select id from public.topics where slug = 'bomb-t01-constitucio-estatut-generalitat'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2010-13313'), 'Art. 19 Llei 26/2010', 'Los acuerdos del órgano colegiado se adoptan por mayoría simple de votos, salvo que sus normas reguladoras establezcan una mayoría distinta. En caso de empate dirime los resultados de las votaciones el voto del presidente o presidenta.', null, 'e3e3997066e5e7c72424f63a7d5654431cc48b3281045114209412b24a712a15', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'e3e3997066e5e7c72424f63a7d5654431cc48b3281045114209412b24a712a15')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Per majoria absoluta, i en cas d''empat es repeteix la votació l''endemà.', false), ('B', 'Per unanimitat de tots els membres presents.', false), ('C', 'Per majoria de dues terceres parts, sense vot de qualitat.', false), ('D', 'Per majoria simple de vots, i en cas d''empat dirimeix el vot del president.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Llei 26/2010, quin és, com a regla general, el sentit del silenci administratiu en els procediments iniciats a sol·licitud de la persona interessada?', 'L''art. 54.1 estableix el silenci positiu com a regla; l''art. 54.2 hi estableix excepcions amb efecte desestimatori, com les subvencions o la responsabilitat patrimonial.', 'bomb_t01_constitucio_estatut_generalitat', (select id from public.topics where slug = 'bomb-t01-constitucio-estatut-generalitat'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2010-13313'), 'Art. 54 Llei 26/2010', 'el vencimiento del plazo sin que se haya notificado resolución expresa legitima a la persona interesada para entender estimada su solicitud por silencio administrativo.', null, '815eb9d4ba356c0c33ebd48cf18548e5079e91228a3e50259ccd5d26cff58a28', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '815eb9d4ba356c0c33ebd48cf18548e5079e91228a3e50259ccd5d26cff58a28')
  returning id
