with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el DL 1/1997, per quins sistemes es proveeixen els llocs de treball reservats a funcionaris?', 'L''art. 61 del DL 1/1997 preveu el concurs i la lliure designació com a sistemes de provisió.', 'bomb_t02_funcio_publica', (select id from public.topics where slug = 'bomb-t02-funcio-publica'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=DOGC-f-1997-90001'), 'Art. 61 DL 1/1997', 'Los puestos de trabajo reservados a funcionarios se proveerán por los sistemas de concurso o de libre designación, de acuerdo con lo que se establezca en las correspondientes relaciones de puestos de trabajo.', null, '82861d2e62efd0c7658ee02c868c0f6fc49b3eaf84746929a4a80e30bc8407fc', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '82861d2e62efd0c7658ee02c868c0f6fc49b3eaf84746929a4a80e30bc8407fc')
