  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Quins terminis de prescripció de les faltes fixa l''article 121 del DL 1/1997 de la funció pública catalana?', 'El text refós català fixa terminis propis, diferents dels de l''art. 97 TREBEP.', 'bomb_t02_funcio_publica', (select id from public.topics where slug = 'bomb-t02-funcio-publica'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=DOGC-f-1997-90001'), 'Art. 121 DL 1/1997', 'Las faltas muy graves prescriben a los seis años, las graves a los dos años y las leves a los dos meses.', null, '78807621a8edaaa11af52310d7791f84657516d72011ef26d5591922d1ea2a29', false
