with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el DL 1/1997, quin òrgan és competent per imposar sancions per faltes molt greus?', 'L''art. 118.2 atribueix les lleus a secretaris generals, directors generals o assimilats; les greus al secretari general del departament; i les molt greus al titular del departament. La separació del servei requereix informe previ de la Comissió Tècnica de la Funció Pública.', 'bomb_t02_funcio_publica', (select id from public.topics where slug = 'bomb-t02-funcio-publica'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=DOGC-f-1997-90001'), 'Art. 118 DL 1/1997', 'En el caso de faltas muy graves, el titular del departamento en el que presta servicios el funcionario responsable', null, 'ef65ee6a53e015270b9719c50236323c9bf4953e7d1501472103de400cae5a3c', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'ef65ee6a53e015270b9719c50236323c9bf4953e7d1501472103de400cae5a3c')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El titular del departament en què presta serveis el funcionari responsable.', true), ('B', 'El director general del qual depèn el funcionari.', false), ('C', 'El secretari general del departament.', false), ('D', 'El cap de la unitat orgànica.', false)) as v(label, body, ok)
)
