with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la Llei 21/1987, d''incompatibilitats del personal de la Generalitat, el personal inclòs en el seu àmbit pot invocar la seva condició pública per exercir una activitat mercantil?', 'L''art. 13 ho prohibeix sense excepcions.', 'bomb_t02_funcio_publica', (select id from public.topics where slug = 'bomb-t02-funcio-publica'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1987-28478'), 'Art. 13 Llei 21/1987', 'El personal a que se refiere la presente Ley no podrá invocar o hacer uso de su condición pública para el ejercicio de ninguna actividad mercantil, profesional o industrial.', null, 'b19f64e35ad3fabdb0d02e8ecfa9d42018d7a0d3694b043f7728ce7a6c58565e', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'b19f64e35ad3fabdb0d02e8ecfa9d42018d7a0d3694b043f7728ce7a6c58565e')
