with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el TREBEP, quina de les classes següents NO figura entre les classes d''empleats públics?', 'L''art. 8.2 TREBEP classifica els empleats públics en funcionaris de carrera, funcionaris interins, personal laboral i personal eventual.', 'bomb_t02_funcio_publica', (select id from public.topics where slug = 'bomb-t02-funcio-publica'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719'), 'Art. 8 TREBEP', 'Los empleados públicos se clasifican en: […] a) Funcionarios de carrera. […] b) Funcionarios interinos. […] c) Personal laboral, ya sea fijo, por tiempo indefinido o temporal. […] d) Personal eventual.', null, '2caf7e7a21ab9f28496010671392331ba3999e77818c196f91f82e7f6bffcf28', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '2caf7e7a21ab9f28496010671392331ba3999e77818c196f91f82e7f6bffcf28')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Personal col·laborador honorífic.', true), ('B', 'Funcionaris de carrera.', false), ('C', 'Funcionaris interins.', false), ('D', 'Personal eventual.', false)) as v(label, body, ok)
)
