  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Quina relació vincula el funcionari de carrera amb l''Administració segons el TREBEP?', 'L''art. 9.1 TREBEP defineix el funcionari de carrera per aquesta relació estatutària, per a serveis professionals retribuïts de caràcter permanent.', 'bomb_t02_funcio_publica', (select id from public.topics where slug = 'bomb-t02-funcio-publica'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719'), 'Art. 9 TREBEP', 'Son funcionarios de carrera quienes, en virtud de nombramiento legal, están vinculados a una Administración Pública por una relación estatutaria regulada por el Derecho Administrativo', null, '395112a5007e7ebc124a72772d135b01387548748b5fa82d604a43da64b6603e', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '395112a5007e7ebc124a72772d135b01387548748b5fa82d604a43da64b6603e')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Una relació laboral regulada per l''Estatut dels treballadors.', false), ('B', 'Una relació mercantil de prestació de serveis.', false), ('C', 'Una relació estatutària regulada pel dret administratiu.', true), ('D', 'Una relació temporal vinculada a un programa concret.', false)) as v(label, body, ok)
)
