  select 'Quin nivell de protecció en seguretat i salut han de tenir els treballadors amb relació temporal o de durada determinada?', 'L''art. 28.1 garanteix el mateix nivell de protecció i prohibeix qualsevol diferència de tracte per aquest motiu.', 'bomb_t03_prevencio_riscos_laborals_epi', (select id from public.topics where slug = 'bomb-t03-prevencio-riscos-laborals-epi'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-24292'), 'Art. 28 Llei 31/1995', 'deberán disfrutar del mismo nivel de protección en materia de seguridad y salud que los restantes trabajadores de la empresa en la que prestan sus servicios.', null, 'b902f95a6fbdbc27b8d55c5334b76499d88831199244e42d67c5e88c08f6910a', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'b902f95a6fbdbc27b8d55c5334b76499d88831199244e42d67c5e88c08f6910a')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El mateix nivell de protecció que la resta de treballadors de l''empresa.', true), ('B', 'Un nivell inferior, proporcional a la durada del contracte.', false), ('C', 'Només la protecció que fixi el seu contracte individual.', false), ('D', 'Cap: la Llei 31/1995 només s''aplica als treballadors indefinits.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 16 de la Llei 31/1995, quan s''ha d''actualitzar l''avaluació de riscos laborals?', 'L''art. 16.2.a exigeix una avaluació inicial, que s''ha d''actualitzar quan canvien les condicions de treball i revisar amb ocasió dels danys per a la salut.', 'bomb_t03_prevencio_riscos_laborals_epi', (select id from public.topics where slug = 'bomb-t03-prevencio-riscos-laborals-epi'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-24292'), 'Art. 16 Llei 31/1995', 'La evaluación será actualizada cuando cambien las condiciones de trabajo y, en todo caso, se someterá a consideración y se revisará, si fuera necesario, con ocasión de los daños para la salud que se hayan producido.', null, '56752a7e387abeee4cad39c59b4cd50d176aa0807656bfb54ccb1b775920af4f', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '56752a7e387abeee4cad39c59b4cd50d176aa0807656bfb54ccb1b775920af4f')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Només cada cinc anys, de manera fixa.', false), ('B', 'Només quan ho ordeni la Inspecció de Treball.', false), ('C', 'Quan canviïn les condicions de treball, i s''ha de revisar, si cal, amb ocasió dels danys per a la salut que s''hagin produït.', true), ('D', 'Mai: l''avaluació inicial té validesa indefinida.', false)) as v(label, body, ok)
)
