with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Qui pot accedir a la informació mèdica de caràcter personal derivada de la vigilància de la salud dels treballadors sense el seu consentiment exprés?', 'L''art. 22.4 limita l''accés a la informació mèdica personal; l''empresari i els responsables de prevenció només són informats de les conclusions sobre l''aptitud per al lloc de treball.', 'bomb_t03_prevencio_riscos_laborals_epi', (select id from public.topics where slug = 'bomb-t03-prevencio-riscos-laborals-epi'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-24292'), 'Art. 22 Llei 31/1995', 'El acceso a la información médica de carácter personal se limitará al personal médico y a las autoridades sanitarias que lleven a cabo la vigilancia de la salud de los trabajadores, sin que pueda facilitarse al empresario o a otras personas sin consentimiento expreso del trabajador.', null, '4dbc5694c9161573cd2ed09de449eccc2044c14e9704aebc2837f47cbd2e0d58', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '4dbc5694c9161573cd2ed09de449eccc2044c14e9704aebc2837f47cbd2e0d58')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'L''empresari i el cap directe del treballador.', false), ('B', 'Els delegats de prevenció i el comitè d''empresa.', false), ('C', 'Qualsevol persona amb responsabilitats en prevenció.', false), ('D', 'Només el personal mèdic i les autoritats sanitàries que duen a terme la vigilància de la salud.', true)) as v(label, body, ok)
)
