with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Amb quina periodicitat s''ha de reunir, com a mínim, el comitè de seguretat i salut?', 'L''art. 38.3 de la Llei 31/1995 fixa reunions trimestrals i, a més, sempre que ho demani alguna de les representacions; el comitè adopta les seves pròpies normes de funcionament.', 'bomb_t03_prevencio_riscos_laborals_epi', (select id from public.topics where slug = 'bomb-t03-prevencio-riscos-laborals-epi'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-24292'), 'Art. 38 Llei 31/1995', 'El Comité de Seguridad y Salud se reunirá trimestralmente y siempre que lo solicite alguna de las representaciones en el mismo.', null, '53a88be6ea5fdf425b8e2e061b38f6f7531f25c6a543390958d303450321cad3', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '53a88be6ea5fdf425b8e2e061b38f6f7531f25c6a543390958d303450321cad3')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Mensualment.', false), ('B', 'Semestralment.', false), ('C', 'Trimestralment i sempre que ho sol·liciti alguna de les representacions.', true), ('D', 'Anualment, en aprovar la memòria del servei de prevenció.', false)) as v(label, body, ok)
)
