with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons l''article 25 de la Llei 31/1995, què ha de fer l''empresari respecte dels treballadors especialment sensibles a determinats riscos?', 'L''art. 25.1 exigeix una protecció específica dels treballadors especialment sensibles i adoptar les mesures preventives i de protecció necessàries segons les avaluacions.', 'bomb_t03_prevencio_riscos_laborals_epi', (select id from public.topics where slug = 'bomb-t03-prevencio-riscos-laborals-epi'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-24292'), 'Art. 25 Llei 31/1995', 'El empresario garantizará de manera específica la protección de los trabajadores que, por sus propias características personales o estado biológico conocido, incluidos aquellos que tengan reconocida la situación de discapacidad física, psíquica o sensorial, sean especialmente sensibles a los riesgos derivados del trabajo.', null, '5f823abe1feea4a44b08aed66a4e0bce72f68953d7def8834440b1d1ae2b984e', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '5f823abe1feea4a44b08aed66a4e0bce72f68953d7def8834440b1d1ae2b984e')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Garantir-ne de manera específica la protecció, tenint en compte aquests aspectes en les avaluacions de riscos.', true), ('B', 'Excloure''ls de l''avaluació de riscos.', false), ('C', 'Acomiadar-los si no poden fer totes les tasques del lloc.', false), ('D', 'Aplicar-los les mateixes mesures que a la resta, sense cap adaptació.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
