with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Per a un funcionari públic, quina consideració té l''incompliment de les seves obligacions en matèria de prevenció de riscos segons la Llei 31/1995?', 'L''art. 29.3 qualifica l''incompliment com a incompliment laboral o, en el cas dels funcionaris, com a falta segons el seu règim disciplinari.', 'bomb_t03_prevencio_riscos_laborals_epi', (select id from public.topics where slug = 'bomb-t03-prevencio-riscos-laborals-epi'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-24292'), 'Art. 29 Llei 31/1995', 'tendrá la consideración de incumplimiento laboral a los efectos previstos en el artículo 58.1 del Estatuto de los Trabajadores o de falta, en su caso, conforme a lo establecido en la correspondiente normativa sobre régimen disciplinario de los funcionarios públicos', null, '3c9ea809205a512573ad2abf0e6aada95bf6feeb8badc6c4ada154cb90e36991', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '3c9ea809205a512573ad2abf0e6aada95bf6feeb8badc6c4ada154cb90e36991')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Cap: les obligacions preventives només són exigibles a l''empresari.', false), ('B', 'Pot constituir falta, d''acord amb la normativa sobre règim disciplinari dels funcionaris públics.', true), ('C', 'És sempre un delicte contra la seguretat dels treballadors.', false), ('D', 'Només comporta una recomanació del servei de prevenció.', false)) as v(label, body, ok)
)
