with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'En quin termini han d''elaborar els delegats de prevenció els informes sobre les decisions de l''empresari que els han de ser consultades prèviament?', 'L''art. 36.3 fixa quinze dies; si transcorre el termini sense informe, l''empresari pot posar en pràctica la seva decisió.', 'bomb_t03_prevencio_riscos_laborals_epi', (select id from public.topics where slug = 'bomb-t03-prevencio-riscos-laborals-epi'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-24292'), 'Art. 36 Llei 31/1995', 'deberán elaborarse en un plazo de quince días, o en el tiempo imprescindible cuando se trate de adoptar medidas dirigidas a prevenir riesgos inminentes.', null, '273a30f0332f7bfdb4956d6b6f16b51a421d814b304e075a472943e8ac0c30af', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '273a30f0332f7bfdb4956d6b6f16b51a421d814b304e075a472943e8ac0c30af')
  returning id
), o as (
