  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Un mes, en tots els casos.', false), ('B', 'Tres dies hàbils.', false), ('C', 'Quinze dies, o el temps imprescindible si es tracta de prevenir riscos imminents.', true), ('D', 'Quaranta-vuit hores.', false)) as v(label, body, ok)
)
