with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Quan els representants dels treballadors acorden la paralització de l''activitat per un risc greu i imminent, en quin termini ha d''anul·lar-la o ratificar-la l''autoritat laboral?', 'L''art. 21.3 preveu la comunicació immediata a l''empresa i a l''autoritat laboral, que en 24 hores anul·la o ratifica la paralització.', 'bomb_t03_prevencio_riscos_laborals_epi', (select id from public.topics where slug = 'bomb-t03-prevencio-riscos-laborals-epi'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-24292'), 'Art. 21 Llei 31/1995', 'Tal acuerdo será comunicado de inmediato a la empresa y a la autoridad laboral, la cual, en el plazo de veinticuatro horas, anulará o ratificará la paralización acordada.', null, '7b5f86be5fae5262ee96f8de0cc9ede9d3d63f708734255268f7eff348bf0843', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '7b5f86be5fae5262ee96f8de0cc9ede9d3d63f708734255268f7eff348bf0843')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'En vint-i-quatre hores.', true), ('B', 'En tres dies hàbils.', false), ('C', 'En quinze dies.', false), ('D', 'En un mes.', false)) as v(label, body, ok)
)
