with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Si un inspector de Treball ordena la paralització immediata d''uns treballs per risc greu i imminent, en quin termini pot impugnar-la l''empresa davant l''autoritat laboral?', 'L''art. 44.1 permet impugnar-la en tres dies hàbils i l''autoritat laboral l''ha de resoldre en un màxim de vint-i-quatre hores; la decisió s''ha de complir immediatament.', 'bomb_t03_prevencio_riscos_laborals_epi', (select id from public.topics where slug = 'bomb-t03-prevencio-riscos-laborals-epi'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-24292'), 'Art. 44 Llei 31/1995', 'La empresa, sin perjuicio del cumplimiento inmediato de tal decisión, podrá impugnarla ante la autoridad laboral en el plazo de tres días hábiles, debiendo resolverse tal impugnación en el plazo máximo de veinticuatro horas.', null, '19c9a382421811e3ce464584feec396b9a4769ba0dd35f48c60b181e5b2ca8c4', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '19c9a382421811e3ce464584feec396b9a4769ba0dd35f48c60b181e5b2ca8c4')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'En vint-i-quatre hores, i la paralització queda suspesa mentre es resol.', false), ('B', 'En un mes, mitjançant recurs d''alçada.', false), ('C', 'No es pot impugnar.', false), ('D', 'En tres dies hàbils, sens perjudici del compliment immediat de la paralització.', true)) as v(label, body, ok)
)
