with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Com es computa el temps que els delegats de prevenció dediquen a les reunions del comitè de seguretat i salut?', 'L''art. 37.1 considera temps de treball efectiu, sense imputar-lo al crèdit horari, les reunions del comitè, les convocades per l''empresari en prevenció i determinades visites.', 'bomb_t03_prevencio_riscos_laborals_epi', (select id from public.topics where slug = 'bomb-t03-prevencio-riscos-laborals-epi'), 3, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-24292'), 'Art. 37 Llei 31/1995', 'será considerado en todo caso como tiempo de trabajo efectivo, sin imputación al citado crédito horario, el correspondiente a las reuniones del Comité de Seguridad y Salud', null, 'ad5b675eac2535fdd98e87f60f4d3524983f9be9093ba7b9a18d85316bd2b614', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'ad5b675eac2535fdd98e87f60f4d3524983f9be9093ba7b9a18d85316bd2b614')
  returning id
), o as (
