with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Què ha de fer el treballador si aprecia un defecte en el seu EPI que en pugui reduir l''eficàcia protectora?', 'Art. 10.c RD 773/1997.', 'bomb_t03_prevencio_riscos_laborals_epi', (select id from public.topics where slug = 'bomb-t03-prevencio-riscos-laborals-epi'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1997-12735'), 'Art. 10 RD 773/1997', 'Informar de inmediato a su superior jerárquico directo de cualquier defecto, anomalía o daño apreciado en el equipo de protección individual utilizado', null, '4c9cba1710d8f7fafc4a26b89931ccc63da49e98214eb38d0f69a1a63bcfe6c9', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '4c9cba1710d8f7fafc4a26b89931ccc63da49e98214eb38d0f69a1a63bcfe6c9')
  returning id
), o as (
