  select 'Quan s''han d''utilitzar els EPI segons el RD 773/1997?', 'L''EPI és el darrer recurs preventiu (art. 4 RD 773/1997).', 'bomb_t03_prevencio_riscos_laborals_epi', (select id from public.topics where slug = 'bomb-t03-prevencio-riscos-laborals-epi'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1997-12735'), 'Art. 4 RD 773/1997', 'Los equipos de protección individual deberán utilizarse cuando existan riesgos para la seguridad o salud de los trabajadores que no hayan podido evitarse o limitarse suficientemente por medios técnicos de protección colectiva o mediante medidas, métodos o procedimientos de organización del trabajo.', null, '5e595b8e4447a4cb54d5c4c6f7f5b6c570b2522b525aea85c083043809818d53', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '5e595b8e4447a4cb54d5c4c6f7f5b6c570b2522b525aea85c083043809818d53')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Sempre, en qualsevol lloc de treball.', false), ('B', 'Només quan ho demana el treballador.', false), ('C', 'Només en treballs amb risc elèctric.', false), ('D', 'Quan hi ha riscos que no s''han pogut evitar o limitar prou per mitjans tècnics de protecció col·lectiva o per mesures d''organització del treball.', true)) as v(label, body, ok)
)
