insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el RD 773/1997, què és un equip de protecció individual?', 'L''art. 2 RD 773/1997 ho defineix així i exclou, entre altres, la roba de treball corrent no destinada a protegir.', 'bomb_t03_prevencio_riscos_laborals_epi', (select id from public.topics where slug = 'bomb-t03-prevencio-riscos-laborals-epi'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1997-12735'), 'Art. 2 RD 773/1997', 'cualquier equipo destinado a ser llevado o sujetado por el trabajador para que le proteja de uno o varios riesgos que puedan amenazar su seguridad o su salud, así como cualquier complemento o accesorio destinado a tal fin.', null, '700022cded90d34f24b5c9e41e2bc22c654eef4be47a6348ac0931f8f1f95836', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '700022cded90d34f24b5c9e41e2bc22c654eef4be47a6348ac0931f8f1f95836')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Qualsevol equip destinat a ser portat o subjectat pel treballador perquè el protegeixi d''un o diversos riscos, així com qualsevol complement o accessori amb aquesta finalitat.', true), ('B', 'Qualsevol mesura tècnica col·lectiva que redueixi el risc.', false), ('C', 'La roba de treball corrent i els uniformes.', false), ('D', 'Els dispositius de senyalització de seguretat.', false)) as v(label, body, ok)
)
