select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Indica la resposta INCORRECTA. Per escollir els EPI, el RD 773/1997 obliga l''empresari a:', 'L''art. 6.1 enumera les tres actuacions (analitzar i avaluar els riscos, definir característiques i comparar amb el mercat); el preu no hi figura com a criteri.', 'bomb_t03_prevencio_riscos_laborals_epi', (select id from public.topics where slug = 'bomb-t03-prevencio-riscos-laborals-epi'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1997-12735'), 'Art. 6 RD 773/1997', 'Analizar y evaluar los riesgos existentes que no puedan evitarse o limitarse suficientemente por otros medios. […] Definir las características que deberán reunir los equipos de protección individual para garantizar su función […] Comparar las características de los equipos de protección individual existentes en el mercado con las definidas según lo señalado en el párrafo anterior.', null, '39a1bab902be9eb536aa30db34a02485e84efd090b979a46aac5222b142baa4d', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '39a1bab902be9eb536aa30db34a02485e84efd090b979a46aac5222b142baa4d')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Triar sempre l''equip més econòmic del mercat.', true), ('B', 'Analitzar i avaluar els riscos que no es puguin evitar o limitar prou per altres mitjans.', false), ('C', 'Definir les característiques que han de reunir els EPI per garantir-ne la funció.', false), ('D', 'Comparar les característiques dels EPI existents al mercat amb les definides.', false)) as v(label, body, ok)
)
