select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Indica la resposta INCORRECTA. Segons el RD 773/1997, les condicions d''ús d''un EPI, especialment el temps durant el qual s''ha de portar, es determinen en funció de:', 'L''art. 7.2 esmenta la gravetat del risc, el temps o freqüència d''exposició, les condicions del lloc de treball, les prestacions de l''equip i els riscos addicionals derivats del seu ús.', 'bomb_t03_prevencio_riscos_laborals_epi', (select id from public.topics where slug = 'bomb-t03-prevencio-riscos-laborals-epi'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1997-12735'), 'Art. 7 RD 773/1997', 'La gravedad del riesgo. […] El tiempo o frecuencia de exposición al riesgo. […] Las condiciones del puesto de trabajo. […] Las prestaciones del propio equipo.', null, '4069bbdf0d95b91511566774297f4e55cdf5d516b0ac9ebf0db92af9ca07c37d', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '4069bbdf0d95b91511566774297f4e55cdf5d516b0ac9ebf0db92af9ca07c37d')
  returning id
), o as (
