  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La gravetat del risc.', false), ('B', 'El temps o la freqüència d''exposició al risc.', false), ('C', 'Les prestacions del propi equip.', false), ('D', 'L''antiguitat del treballador a l''empresa.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Quan ha d''informar l''empresari els treballadors sobre els riscos contra els quals els protegeixen els EPI, i com ha de donar les instruccions d''ús?', 'L''art. 8.2 exigeix informar prèviament a l''ús i proporcionar instruccions, preferentment per escrit, sobre la forma correcta d''utilitzar-los i mantenir-los; el manual del fabricant ha d''estar a disposició dels treballadors.', 'bomb_t03_prevencio_riscos_laborals_epi', (select id from public.topics where slug = 'bomb-t03-prevencio-riscos-laborals-epi'), 2, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1997-12735'), 'Art. 8 RD 773/1997', 'El empresario deberá informar a los trabajadores, previamente al uso de los equipos, de los riesgos contra los que les protegen, así como de las actividades u ocasiones en las que deben utilizarse. Asimismo, deberá proporcionarles instrucciones, preferentemente por escrito, sobre la forma correcta de utilizarlos y mantenerlos.', null, 'bfbd4f7cfd72df2417006699de46c5bd9038aae94eeedbbd9d6a2d83431efbb2', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'bfbd4f7cfd72df2417006699de46c5bd9038aae94eeedbbd9d6a2d83431efbb2')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Després del primer ús, i només oralment.', false), ('B', 'Abans d''utilitzar els equips, i amb instruccions preferentment per escrit.', true), ('C', 'Només si el treballador ho sol·licita per escrit.', false), ('D', 'Un cop a l''any, en una sessió general per a tota la plantilla.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
