insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('bombers-generalitat') and t.slug = 'bomb-t04-igualtat-no-discriminacio' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Quin és l''objecte de la Llei 19/2020, d''igualtat de tracte i no-discriminació?', 'L''art. 1.1 de la Llei 19/2020 en fixa l''objecte.', 'bomb_t04_igualtat_no_discriminacio', (select id from public.topics where slug = 'bomb-t04-igualtat-no-discriminacio'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2021-1663'), 'Art. 1 Llei 19/2020', 'El objeto de la presente ley es garantizar el derecho a la igualdad de trato y a la no discriminación y erradicar cualquier actuación o comportamiento que puedan atentar contra la dignidad de las personas', null, '19a11b36f155b708cf5394182ba15497d35a05c4d04e709c65ad3ea8a395922f', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '19a11b36f155b708cf5394182ba15497d35a05c4d04e709c65ad3ea8a395922f')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Garantir el dret a la igualtat de tracte i a la no-discriminació i eradicar qualsevol actuació que pugui atemptar contra la dignitat de les persones.', true), ('B', 'Regular exclusivament la igualtat salarial entre dones i homes.', false), ('C', 'Crear un cos d''inspecció laboral propi de Catalunya.', false), ('D', 'Regular el dret d''asil i refugi.', false)) as v(label, body, ok)
)
