  select 'Quin d''aquests drets lingüístics NO reconeix l''article 4.1 de la Llei 1/1998?', 'L''art. 4.1 reconeix conèixer, expressar-se, ser ateses, utilitzar lliurement i no ser discriminades; la llengua no és requisit de forma dels documents privats (art. 15.1).', 'bomb_t05_politica_linguistica', (select id from public.topics where slug = 'bomb-t05-politica-linguistica'), 1, 'ca', true, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1998-2989'), 'Art. 4 Llei 1/1998', 'a) Conocer las dos lenguas oficiales. […] b) Expresarse en cualquiera de las dos lenguas oficiales, oralmente y por escrito, en las relaciones y actos públicos y privados. […] e) No ser discriminadas por razón de la lengua oficial que utilizan.', null, 'e4893f02748fb25830ed89d7ce81840682ea57863ba748f7b06d36779229eb2d', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'e4893f02748fb25830ed89d7ce81840682ea57863ba748f7b06d36779229eb2d')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Conèixer les dues llengües oficials.', false), ('B', 'Expressar-se en qualsevol de les dues llengües oficials.', false), ('C', 'El dret a exigir que tota la documentació privada s''hagi de redactar en català.', true), ('D', 'No ser discriminades per raó de la llengua oficial que utilitzen.', false)) as v(label, body, ok)
)
