with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Com defineix el Decret 276/2016 el sistema de comandament dels serveis de prevenció, extinció d''incendis i salvaments de la Generalitat?', 'Art. 20.1 del Decret 276/2016. Tots els serveis han de ser comandats per un cap d''intervenció (art. 20.2).', 'bomb_t07_guardia_comandament_departament', (select id from public.topics where slug = 'bomb-t07-guardia-comandament-departament'), 3, 'ca', true, (select id from public.sources where url = 'https://portaljuridic.gencat.cat/eli/es-ct/d/2016/07/19/276'), 'Art. 20 Decret 276/2016', 'es defineix com el model organitzatiu integrat pel conjunt de persones, procediments, instal·lacions i equipaments que formen part d''una estructura jeràrquica i comuna per a tots els agents intervinents i que té com a finalitat donar resposta a cada situació d''emergència sota un únic comandament i basant-se en una organització modular i escalable.', null, '5e33409f84271dc4ea9e4fec434d9507420b529a16c859dd4222fec1b37bcf79', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '5e33409f84271dc4ea9e4fec434d9507420b529a16c859dd4222fec1b37bcf79')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Com el conjunt de vehicles i dotacions assignats a cada parc.', false), ('B', 'Com un model organitzatiu de persones, procediments, instal·lacions i equipaments, d''estructura jeràrquica i comuna per a tots els agents, que respon a cada emergència sota un únic comandament i amb una organització modular i escalable.', true), ('C', 'Com el pla d''emergència que aprova cada ajuntament.', false), ('D', 'Com una estructura de comandament pròpia i separada per a cada cos que intervé.', false)) as v(label, body, ok)
)
