with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el Manual operatiu bàsic de la teoria del foc i agents extintors, quins són els tres mecanismes principals de transmissió de la calor?', 'El manual identifica tres mecanismes: la conducció (contacte directe entre molècules), la convecció (corrents del fluid escalfat) i la radiació (ones electromagnètiques).', 'bomb_t08_teoria_foc_agents_extintors', (select id from public.topics where slug = 'bomb-t08-teoria-foc-agents-extintors'), 1, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-08-MAN.GRAL.008.pdf'), 'MAN.GRAL.008, § mecanismes de transmissió de la calor', 'Hi ha tres mecanismes principals de transmissió de la calor: conducció, convecció i radiació.', null, '32b6268117fa62638637cc72712bfefe69211858927f7060373617553f0f56f9', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '32b6268117fa62638637cc72712bfefe69211858927f7060373617553f0f56f9')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Conducció, difusió i reflexió.', false), ('B', 'Convecció, piròlisi i radiació.', false), ('C', 'Radiació, inducció i evaporació.', false), ('D', 'Conducció, convecció i radiació.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Com defineix el manual de teoria del foc la conducció?', 'La conducció es produeix pel contacte directe entre molècules; les ones electromagnètiques corresponen a la radiació i els corrents d''un fluid, a la convecció.', 'bomb_t08_teoria_foc_agents_extintors', (select id from public.topics where slug = 'bomb-t08-teoria-foc-agents-extintors'), 1, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-08-MAN.GRAL.008.pdf'), 'MAN.GRAL.008, § conducció', 'Conducció La conducció és la transferència de calor a través del contacte directe entre molècules.', null, 'e6165f120b00b4b606ee3ea3a3f298aa7218b0d1dd50f651b53307e4228a1d98', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'e6165f120b00b4b606ee3ea3a3f298aa7218b0d1dd50f651b53307e4228a1d98')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La transferència de calor a través del contacte directe entre molècules.', true), ('B', 'La transferència de calor en forma d''ones electromagnètiques.', false), ('C', 'La transferència de calor mitjançant els corrents d''un fluid escalfat.', false), ('D', 'La transferència de calor per contacte directe de la flama amb els gasos no cremats.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual de teoria del foc, la radiació és la transferència de calor:', 'La radiació transmet la calor en forma d''ones electromagnètiques i no necessita cap medi material; per això també escalfa a distància.', 'bomb_t08_teoria_foc_agents_extintors', (select id from public.topics where slug = 'bomb-t08-teoria-foc-agents-extintors'), 1, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-08-MAN.GRAL.008.pdf'), 'MAN.GRAL.008, § radiació', 'Radiació La radiació és la transferència de calor en forma d''ones electromagnètiques.', null, 'f84f6a33385d1398766957db8d20f697215b211a2b80289c102c35a8801d7bf7', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'f84f6a33385d1398766957db8d20f697215b211a2b80289c102c35a8801d7bf7')
  returning id
), o as (
