  select q.id, v.label, v.body, v.ok from q, (values ('A', 'A través del contacte directe entre molècules.', false), ('B', 'Per mitjà dels corrents ascendents del fum.', false), ('C', 'En forma d''ones electromagnètiques.', true), ('D', 'Només a través de materials metàl·lics.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual de teoria del foc, quin percentatge mínim d''oxigen a l''atmosfera necessiten la majoria de focs per mantenir-se?', 'L''aire conté aproximadament un 21 % d''oxigen; la majoria de focs necessiten com a mínim un 16 % per mantenir-se, i per sota d''aquest nivell actua la sufocació.', 'bomb_t08_teoria_foc_agents_extintors', (select id from public.topics where slug = 'bomb-t08-teoria-foc-agents-extintors'), 1, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-08-MAN.GRAL.008.pdf'), 'MAN.GRAL.008, § concentració d''oxigen', 'La majoria de focs necessiten almenys un 16% d''oxigen a l''atmosfera per mantenir-se.', null, 'eb1cb1388f9fc0e7166553dac2e54f98821fb7ad47475f0b0397e3752d310e56', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'eb1cb1388f9fc0e7166553dac2e54f98821fb7ad47475f0b0397e3752d310e56')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Almenys un 21 %.', false), ('B', 'Almenys un 16 %.', true), ('C', 'Almenys un 10 %.', false), ('D', 'Almenys un 5 %.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual de teoria del foc, quin volum aproximat de vapor genera un litre d''aigua en vaporitzar-se?', 'L''aigua, en vaporitzar-se, genera aproximadament 1.700 litres de vapor per litre; aquest vapor pot desplaçar l''oxigen i contribuir a la sufocació.', 'bomb_t08_teoria_foc_agents_extintors', (select id from public.topics where slug = 'bomb-t08-teoria-foc-agents-extintors'), 1, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-08-MAN.GRAL.008.pdf'), 'MAN.GRAL.008, § aigua com a agent extintor', 'Quan l''aigua es vaporitza, genera un gran volum de vapor (aproximadament 1.700 litres de vapor per cada litre d''aigua).', null, '2b9ab939614f2032aa20729986485cf6c81c8eaf82179d9f05a242d7c4f13a00', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '2b9ab939614f2032aa20729986485cf6c81c8eaf82179d9f05a242d7c4f13a00')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Uns 170 litres.', false), ('B', 'Uns 17.000 litres.', false), ('C', 'Uns 540 litres.', false), ('D', 'Uns 1.700 litres.', true)) as v(label, body, ok)
)
