with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'D''acord amb el manual de teoria del foc, quina afirmació és CORRECTA sobre la classe E de focs?', 'La norma UNE-EN 2 no té classe E: l''electricitat no crema, sinó que hi pot haver focs de classe A, B, C... amb presència d''electricitat.', 'bomb_t08_teoria_foc_agents_extintors', (select id from public.topics where slug = 'bomb-t08-teoria-foc-agents-extintors'), 1, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-08-MAN.GRAL.008.pdf'), 'MAN.GRAL.008, § classes de foc (UNE-EN 2)', 'No existeix una Classe E de focs elèctrics.', null, '187516e98dc4d4d21295a47322b36684e041c0abb8751ca33fab136d30ae8c2e', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '187516e98dc4d4d21295a47322b36684e041c0abb8751ca33fab136d30ae8c2e')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La classe E correspon als focs d''equips elèctrics en tensió.', false), ('B', 'La classe E correspon als focs d''olis i greixos de cuina.', false), ('C', 'No existeix una classe E de focs elèctrics.', true), ('D', 'La classe E correspon als focs de metalls combustibles.', false)) as v(label, body, ok)
)
