with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual de teoria del foc, una deflagració és un tipus d''explosió en què la combustió es propaga a una velocitat:', 'La deflagració és subsònica (entre 1 m/s i la velocitat del so); la detonació és supersònica i genera una ona de xoc destructiva.', 'bomb_t08_teoria_foc_agents_extintors', (select id from public.topics where slug = 'bomb-t08-teoria-foc-agents-extintors'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-08-MAN.GRAL.008.pdf'), 'MAN.GRAL.008, § deflagració', 'És un tipus d''explosió on la combustió es propaga a una velocitat superior a 1 m/s però inferior a la velocitat del so en el medi (subsònica).', null, '0b8700b032aee1bed6b0c2598668067ace4fbfc38c84f2b66e13afb53b11972c', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '0b8700b032aee1bed6b0c2598668067ace4fbfc38c84f2b66e13afb53b11972c')
  returning id
