  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Una reignició explosiva provocada per l''entrada sobtada d''aire en un compartiment amb ventilació limitada.', false), ('B', 'L''ebullició sobtada de l''aigua acumulada sota un combustible líquid que projecta el combustible fora del recipient.', false), ('C', 'La transició ràpida d''un incendi localitzat a un incendi totalment desenvolupat, en què totes les superfícies combustibles s''encenen gairebé simultàniament.', true), ('D', 'La ruptura d''un recipient que conté un líquid a pressió per sobre del seu punt d''ebullició.', false)) as v(label, body, ok)
