with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Hi ha una fuita de propà en un soterrani. Segons el manual de teoria del foc, on és més probable que s''acumuli el gas?', 'Els vapors amb densitat relativa superior a 1 baixen i formen «llacs» invisibles a les zones baixes; el metà (≈ 0,55) i l''hidrogen pugen cap al sostre.', 'bomb_t08_teoria_foc_agents_extintors', (select id from public.topics where slug = 'bomb-t08-teoria-foc-agents-extintors'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-08-MAN.GRAL.008.pdf'), 'MAN.GRAL.008, § densitat relativa de vapors', 'Densitat de vapor > 1 (més pesats que l''aire): Aquests són particularment perillosos. Tendeixen a baixar i acumular-se a prop del terra, en zones baixes, fosses, depressions o soterranis. […] Exemples: Propà ≈ 1.55', null, 'e22f80a5f4cc204941ec852f1a8a7d66c326641070d773939a6092c35bd53a31', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'e22f80a5f4cc204941ec852f1a8a7d66c326641070d773939a6092c35bd53a31')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'A prop del terra i a les zones baixes, perquè és més pesant que l''aire (densitat relativa ≈ 1,55).', true), ('B', 'Al sostre, perquè és més lleuger que l''aire.', false), ('C', 'Repartit uniformement de seguida, perquè té la mateixa densitat que l''aire.', false), ('D', 'Enlloc, perquè el propà no forma barreges inflamables.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
