  select 'Segons el manual de teoria del foc, quines proporcions d''escumogen en aigua són les habituals?', 'Depèn del tipus d''escuma i de l''aplicació; la tendència és cap a escumògens més concentrats.', 'bomb_t08_teoria_foc_agents_extintors', (select id from public.topics where slug = 'bomb-t08-teoria-foc-agents-extintors'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-08-MAN.GRAL.008.pdf'), 'MAN.GRAL.008, § escuma: dosificació', 'La proporció d''escumogen en aigua sol ser del 1%, 3% o 6%', null, '1218b60896a87db408e04b9c052cf9a995f12a23279b12f95740cace9d42ead8', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '1218b60896a87db408e04b9c052cf9a995f12a23279b12f95740cace9d42ead8')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El 10 %, el 20 % o el 30 %.', false), ('B', 'El 0,1 %, el 0,3 % o el 0,6 %.', false), ('C', 'Sempre el 50 %.', false), ('D', 'L''1 %, el 3 % o el 6 %.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'En un incendi d''un dipòsit d''acetona o d''alcohol, quin tipus d''escuma indica el manual de teoria del foc?', 'Els combustibles polars (alcohols, cetones com l''acetona, èsters) es barregen amb l''aigua i destruirien les escumes convencionals; les AR porten polímers que fan de barrera.', 'bomb_t08_teoria_foc_agents_extintors', (select id from public.topics where slug = 'bomb-t08-teoria-foc-agents-extintors'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-08-MAN.GRAL.008.pdf'), 'MAN.GRAL.008, § escumes resistents a alcohols', 'Escumes Resistents a Alcohols (AR): Dissenyades per a combustibles polars (com alcohols, cetones, èsters, etc.) que, per la seva miscibilitat amb l''aigua, destruirien les escumes convencionals.', null, '87c635e692dd2d727c8de8c722706b392931db936ffdf63a218d2c5eee57f966', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '87c635e692dd2d727c8de8c722706b392931db936ffdf63a218d2c5eee57f966')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Una escuma proteínica convencional.', false), ('B', 'Una escuma resistent a alcohols (AR).', true), ('C', 'Qualsevol escuma convencional, sempre que sigui d''alta expansió.', false), ('D', 'Cap: l''escuma no serveix per a líquids inflamables.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
