with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual de teoria del foc, quin és el mecanisme d''extinció principal de la pols química seca?', 'La sufocació és el mecanisme secundari de la pols; la saponificació és pròpia dels agents per a focs de classe F.', 'bomb_t08_teoria_foc_agents_extintors', (select id from public.topics where slug = 'bomb-t08-teoria-foc-agents-extintors'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-08-MAN.GRAL.008.pdf'), 'MAN.GRAL.008, § pols química seca', 'Inhibició (principal): La seva acció principal es basa en la interrupció de la reacció en cadena del foc.', null, '94534dc97dbaa794a54f0a7eb8b00d0cbd3691b3c7409d748b27518ea1d789da', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '94534dc97dbaa794a54f0a7eb8b00d0cbd3691b3c7409d748b27518ea1d789da')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El refredament.', false), ('B', 'La dilució de l''oxigen per un gas inert.', false), ('C', 'La saponificació del combustible.', false), ('D', 'La inhibició: interromp la reacció en cadena.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
