with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual de teoria del foc, per què es van prohibir la producció i l''ús dels halons a partir de 1994?', 'Eren agents d''inhibició molt eficaços i nets; només es permeten halons recuperats per a usos crítics molt limitats.', 'bomb_t08_teoria_foc_agents_extintors', (select id from public.topics where slug = 'bomb-t08-teoria-foc-agents-extintors'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-08-MAN.GRAL.008.pdf'), 'MAN.GRAL.008, § halons', 'Producció i ús prohibits a partir del 1994 (Protocol de Montreal) a causa del seu alt potencial de destrucció de la capa d''ozó (ODP).', null, '715166ab518ddd28e46ecd73aa7b90782eadc512afcf97ed648b20926ee5d922', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '715166ab518ddd28e46ecd73aa7b90782eadc512afcf97ed648b20926ee5d922')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Perquè eren poc eficaços.', false), ('B', 'Pel seu alt potencial de destrucció de la capa d''ozó (Protocol de Montreal).', true), ('C', 'Perquè deixaven molts residus.', false), ('D', 'Perquè eren conductors de l''electricitat.', false)) as v(label, body, ok)
)
