select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual de teoria del foc, què caracteritza un incendi limitat per la ventilació (ILV)?', 'Una entrada d''aire sobtada (trencar una finestra, obrir una porta) pot desencadenar una reignició violenta. L''incendi limitat pel combustible (ILC) és el que es desenvolupa lliurement.', 'bomb_t08_teoria_foc_agents_extintors', (select id from public.topics where slug = 'bomb-t08-teoria-foc-agents-extintors'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-08-MAN.GRAL.008.pdf'), 'MAN.GRAL.008, § ventilació', 'Incendi limitat per la ventilació (ILV): Amb una ventilació limitada (espais tancats), pot provocar una ràpida consumició d''oxigen i l''acumulació de fums i gasos combustibles sense cremar. […] El foc està governat per la disponibilitat d’oxigen.', null, 'b831c9410fe13ce251c2a410fed35782ba7c8646abd1145bf9cf3d07d44a8528', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'b831c9410fe13ce251c2a410fed35782ba7c8646abd1145bf9cf3d07d44a8528')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Està governat per la disponibilitat d''oxigen i s''hi acumulen fums i gasos combustibles sense cremar.', true), ('B', 'Està governat per la disponibilitat de combustible i es desenvolupa lliurement.', false), ('C', 'És un incendi a l''aire lliure amb vent fort.', false), ('D', 'És un incendi sense cap risc de reignició.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
