with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'En un incendi d''hidrocarburs en un dipòsit, l''aigua d''extinció s''ha anat acumulant al fons sota el combustible. Segons el manual de teoria del foc, quin fenomen pot produir-se?', 'L''aigua del fons s''escalfa per sobre de 100 °C sense bullir per la pressió del combustible; quan aquest es consumeix, bull massivament i sense avís.', 'bomb_t08_teoria_foc_agents_extintors', (select id from public.topics where slug = 'bomb-t08-teoria-foc-agents-extintors'), 3, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-08-MAN.GRAL.008.pdf'), 'MAN.GRAL.008, § aigua: limitacions (boil-over)', 'l''aigua sobreescalfada pot bullir, de cop, massivament i sense senyals d’avís, projectant el combustible en flames fora del recipient (fenomen conegut com a boil-over)', null, '4988f29e7529c7a26a9af6d972d4f98b0b1296d5352bfb96286965658ae7c0b7', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '4988f29e7529c7a26a9af6d972d4f98b0b1296d5352bfb96286965658ae7c0b7')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El backdraft: l''entrada sobtada d''aire en un compartiment tancat.', false), ('B', 'La saponificació del combustible, que deixa de cremar.', false), ('C', 'El boil-over: l''aigua sobreescalfada bull de cop i projecta el combustible en flames fora del recipient.', true), ('D', 'L''extinció segura, perquè l''aigua fa de capa aïllant.', false)) as v(label, body, ok)
)
