with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Un bomber rep una certa intensitat de calor radiant a 2 m de les flames. Si s''allunya fins a 6 m, quina fracció d''aquella intensitat rebrà, segons la relació que dona el manual de teoria del foc?', 'La distància es triplica (6/2 = 3) i la intensitat es divideix pel quadrat: 3² = 9, és a dir, 1/9 de la inicial.', 'bomb_t08_teoria_foc_agents_extintors', (select id from public.topics where slug = 'bomb-t08-teoria-foc-agents-extintors'), 3, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-08-MAN.GRAL.008.pdf'), 'MAN.GRAL.008, § radiació', 'La intensitat de radiació emesa que rebem és […] inversament proporcional al quadrat de la distància.', null, 'a59ee40f07409bbf018ee1fdeb0ece2ef18ba7c7ac097b3b4245ce7bfdf4bfef', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'a59ee40f07409bbf018ee1fdeb0ece2ef18ba7c7ac097b3b4245ce7bfdf4bfef')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Una novena part.', true), ('B', 'Un terç.', false), ('C', 'La meitat.', false), ('D', 'Una sisena part.', false)) as v(label, body, ok)
)
