with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Un explosímetre marca un 12 % de propà en volum en un local tancat. Segons la taula de rangs d''inflamabilitat del manual de teoria del foc, com és aquesta barreja?', 'El propà crema entre el 2,1 % i el 9,5 %. Per sobre del LSI no crema, però si es ventila o es dilueix pot entrar dins del rang i encendre''s (el 15 % és el LSI del metà).', 'bomb_t08_teoria_foc_agents_extintors', (select id from public.topics where slug = 'bomb-t08-teoria-foc-agents-extintors'), 3, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-08-MAN.GRAL.008.pdf'), 'MAN.GRAL.008, § límits d''inflamabilitat', 'Propà 2,1 9,5 7,4 […] Per sobre de l’LSI, la barreja tampoc crema ni explota.', null, 'd7a390489b3a36afba442a0a2ac959428de1480df331f8dbd5aa5877ab352aff', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'd7a390489b3a36afba442a0a2ac959428de1480df331f8dbd5aa5877ab352aff')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Dins del rang d''inflamabilitat: pot encendre''s.', false), ('B', 'Massa rica: està per sobre del LSI del propà (9,5 %) i, tal com està, no crema.', true), ('C', 'Massa pobra: està per sota del LII del propà.', false), ('D', 'Dins del rang, perquè el LSI del propà és del 15 %.', false)) as v(label, body, ok)
)
