with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual de teoria del foc, fins a quina concentració d''oxigen poden continuar cremant sense flama (foc latent) alguns materials?', 'La flama s''extingeix per sota d''un 14 % aproximadament, però les brases poden continuar pirolitzant i, amb una entrada d''aire sobtada, provocar un backdraft.', 'bomb_t08_teoria_foc_agents_extintors', (select id from public.topics where slug = 'bomb-t08-teoria-foc-agents-extintors'), 3, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-08-MAN.GRAL.008.pdf'), 'MAN.GRAL.008, § concentració d''oxigen <21%', 'els materials poden continuar cremant sense flama (foc latent), en forma de brases, fins i tot amb concentracions d''oxigen tan baixes com el 5-8%.', null, '45c44190d592d7b77ef6a9d4981b572eadd2e56e1b3a469e1671ab751f9b3944', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '45c44190d592d7b77ef6a9d4981b572eadd2e56e1b3a469e1671ab751f9b3944')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
