with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Indica l''afirmació INCORRECTA sobre la pols química seca segons el manual de teoria del foc.', 'El manual diu el contrari: la pols no crea una atmosfera inerta duradora i hi pot haver reignició si no s''actua amb rapidesa o no es combina amb altres mètodes. Les altres tres afirmacions hi són literalment.', 'bomb_t08_teoria_foc_agents_extintors', (select id from public.topics where slug = 'bomb-t08-teoria-foc-agents-extintors'), 3, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-08-MAN.GRAL.008.pdf'), 'MAN.GRAL.008, § pols química seca: limitacions', 'No crea una atmosfera inerta duradora, fet que pot provocar la reignició del foc', null, '8861ecd65ecbf5badf775976f5edd52a237a441a8510045a521c23054b8a9baf', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '8861ecd65ecbf5badf775976f5edd52a237a441a8510045a521c23054b8a9baf')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'És un agent no conductor de l''electricitat.', false), ('B', 'No és adequada per a entorns amb equips electrònics delicats.', false), ('C', 'La pols ABC deixa una capa enganxosa i pot ser corrosiva.', false), ('D', 'Crea una atmosfera inerta duradora que impedeix la reignició.', true)) as v(label, body, ok)
)
