  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Quina de les forces següents és NO conservativa segons el manual de Física?', 'Les forces conservatives (gravetat, força elàstica) retornen íntegrament l''energia; el fregament, la resistència aerodinàmica o la pèrdua de càrrega en una mànega no.', 'bomb_t09_fisica', (select id from public.topics where slug = 'bomb-t09-fisica'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-09-MAN.GRAL.003.pdf'), 'MAN.GRAL.003, § forces no conservatives', 'Són forces no conservatives el fregament, la resistència aerodinàmica, el fregament en líquids (pèrdua de càrrega en una mànega, amortidors del cotxe).', null, '46813cb54cc980bcae8e1bc5f17b8a275adb1c5624c6ad8035c9722a546cb9e4', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '46813cb54cc980bcae8e1bc5f17b8a275adb1c5624c6ad8035c9722a546cb9e4')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El fregament.', true), ('B', 'La gravetat.', false), ('C', 'La força elàstica d''una molla.', false), ('D', 'El pes d''un cos.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual de Física, en una palanca de segon gènere:', 'En el segon gènere (perpalina, carretó de mà, trencanous) la resistència és al mig, de manera que l''AM és sempre superior a 1.', 'bomb_t09_fisica', (select id from public.topics where slug = 'bomb-t09-fisica'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-09-MAN.GRAL.003.pdf'), 'MAN.GRAL.003, § palanques de segon gènere', 'En aquest cas, la força de sortida (la resistència) es troba entre el fulcre i la força aplicada. […] Aquestes palanques sempre proporcionen un avantatge mecànic superior a 1.', null, '1d133e84a2af1a1cf0d901d42b028f2f76908d880d48a0468e3bf134c10c6733', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '1d133e84a2af1a1cf0d901d42b028f2f76908d880d48a0468e3bf134c10c6733')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El fulcre es troba entre la força aplicada i la resistència.', false), ('B', 'La força aplicada es troba entre el fulcre i la resistència, i l''avantatge mecànic sempre és inferior a 1.', false), ('C', 'La resistència es troba entre el fulcre i la força aplicada, i l''avantatge mecànic sempre és superior a 1.', true), ('D', 'L''avantatge mecànic és sempre igual a 1.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual de Física, per què el rendiment o eficiència d''un sistema mecànic sempre és inferior al 100 %?', 'Una part de l''energia es dissipa per fregament i resistència de l''aire; per això la potència a les rodes és inferior a la del motor.', 'bomb_t09_fisica', (select id from public.topics where slug = 'bomb-t09-fisica'), 3, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-09-MAN.GRAL.003.pdf'), 'MAN.GRAL.003, § rendiment', 'L''eficiència sempre és inferior al 100% perquè les forces no conservatives, com el fregament i la resistència aerodinàmica, transformen una part de l''energia en calor o turbulències de l’aire, que no podem aprofitar per fer la tasca que volem.', null, 'b2fc72c3ec425f75e095ee4bb3ffa9b6b05de643499ef56374f1f830f07d73af', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'b2fc72c3ec425f75e095ee4bb3ffa9b6b05de643499ef56374f1f830f07d73af')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Perquè l''energia potencial sempre es converteix íntegrament en energia cinètica.', false), ('B', 'Perquè la massa dels sistemes augmenta amb la velocitat.', false), ('C', 'Perquè el treball útil es mesura en watts i el consumit en joules.', false), ('D', 'Perquè les forces no conservatives, com el fregament i la resistència aerodinàmica, transformen part de l''energia en calor o turbulències no aprofitables.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'En una palanca de primer gènere, com una pota de cabra, quan és l''avantatge mecànic més gran que 1 segons el manual de Física?', 'En el primer gènere, l''AM depèn de la posició del fulcre: és més gran que 1 si està a prop de la resistència, més petit si està a prop de la força i igual a 1 si és al centre.', 'bomb_t09_fisica', (select id from public.topics where slug = 'bomb-t09-fisica'), 3, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-09-MAN.GRAL.003.pdf'), 'MAN.GRAL.003, § palanques de primer gènere', 'Si el fulcre està més a prop de la resistència, l''avantatge mecànic és més gran que 1.', null, '49c59959eee0299c62b6b68b80336f1c8fdd5fe1de5979391268b3e9453f961b', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '49c59959eee0299c62b6b68b80336f1c8fdd5fe1de5979391268b3e9453f961b')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Quan el fulcre està més a prop de la resistència.', true), ('B', 'Quan el fulcre està més a prop de la força aplicada.', false), ('C', 'Quan el fulcre es troba exactament al centre.', false), ('D', 'Mai: les palanques de primer gènere sempre tenen AM inferior a 1.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'En un cabestrant en què el cable s''enrotlla en diverses capes, quan és màxima la força de sortida al cable per a un mateix parell d''entrada, segons el manual de Física?', 'El torn funciona com una palanca giratòria: com més petit és el radi del tambor (braç de la resistència), més gran és la força al cable per al mateix parell.', 'bomb_t09_fisica', (select id from public.topics where slug = 'bomb-t09-fisica'), 3, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-09-MAN.GRAL.003.pdf'), 'MAN.GRAL.003, § torn', 'Així, quan el cable està gairebé estirat del tot, el radi del tambor és el més petit possible i, per la mateixa força (parell) d’entrada, la força de sortida (en el cable) és màxima.', null, '38274031937dcb1d4acea5459142461ad2956a8e2caf6b1a158be441841c1d36', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '38274031937dcb1d4acea5459142461ad2956a8e2caf6b1a158be441841c1d36')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Quan el cable està totalment enrotllat, perquè el radi del tambor és el més gran possible.', false), ('B', 'La força de sortida no depèn del radi del tambor.', false), ('C', 'Quan el cable està a mig enrotllar, perquè els radis es compensen.', false), ('D', 'Quan el cable està gairebé del tot estirat, perquè el radi del tambor és el més petit possible.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual de Física, en quin principi es basa el funcionament del pla inclinat?', 'Com que el treball és força per distància, si es vol fer menys força cal recórrer més distància per assolir la mateixa alçada.', 'bomb_t09_fisica', (select id from public.topics where slug = 'bomb-t09-fisica'), 3, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-09-MAN.GRAL.003.pdf'), 'MAN.GRAL.003, § pla inclinat', 'El seu funcionament es basa en el principi de la conservació de l''energia.', null, '7f7d84ad2a184951cc555ae6484bc325e25d50ffc168053e40c59c355f9abea5', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '7f7d84ad2a184951cc555ae6484bc325e25d50ffc168053e40c59c355f9abea5')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'En el principi de Pascal: la pressió es transmet igual en totes direccions.', false), ('B', 'En el principi de la conservació de l''energia: es fa el mateix treball amb menys força al llarg de més distància.', true), ('C', 'En el principi d''Arquimedes: tot cos submergit rep una empenta vertical.', false), ('D', 'En la llei d''acció-reacció: la rampa empeny l''objecte cap amunt.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual de Física, què mesura el moment d''inèrcia d''un cos?', 'El moment d''inèrcia és l''anàleg rotacional de la massa: la massa s''oposa als canvis de velocitat lineal i el moment d''inèrcia, als de velocitat de rotació.', 'bomb_t09_fisica', (select id from public.topics where slug = 'bomb-t09-fisica'), 3, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-09-MAN.GRAL.003.pdf'), 'MAN.GRAL.003, § moment d''inèrcia', 'Mentre que la massa dona idea de la resistència d''un cos a canviar la seva velocitat lineal, el moment d''inèrcia mesura la resistència d''un cos a modificar la seva velocitat de rotació.', null, '55183dfdb5f09a83fddf46a2044db8d5f3ebb8b7148f17bc88ccf3aaa732814d', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '55183dfdb5f09a83fddf46a2044db8d5f3ebb8b7148f17bc88ccf3aaa732814d')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La resistència del cos a canviar la seva velocitat lineal.', false), ('B', 'L''energia que té el cos a causa de la seva alçada.', false), ('C', 'La resistència del cos a modificar la seva velocitat de rotació.', true), ('D', 'La força necessària per vèncer el fregament estàtic.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
