  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual de Física, com és normalment el coeficient de fregament estàtic (μs) respecte al dinàmic (μd)?', 'El fregament estàtic s''oposa a l''inici del moviment i el dinàmic actua quan el cos ja es mou; el dinàmic és generalment inferior.', 'bomb_t09_fisica', (select id from public.topics where slug = 'bomb-t09-fisica'), 1, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-09-MAN.GRAL.003.pdf'), 'MAN.GRAL.003, § fregament i adherència', 'sent normalment μs > μd (costa arrancar, un cop en moviment fa falta menys força).', null, 'a42e1e1fbfc649a9198e6186cab125e5c70572bed84211d371a259d1c881727f', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'a42e1e1fbfc649a9198e6186cab125e5c70572bed84211d371a259d1c881727f')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Més petit: costa menys arrencar que mantenir el moviment.', false), ('B', 'Més gran: costa més arrencar un objecte que mantenir-lo en moviment.', true), ('C', 'Sempre exactament igual.', false), ('D', 'Negatiu, perquè afavoreix el moviment.', false)) as v(label, body, ok)
)
