  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Per pujar el material a un segon pis es fa un treball de 3.000 J en 10 s. Segons el manual de Física, quina potència s''ha desenvolupat?', 'P = W / t = 3.000 J / 10 s = 300 W. Si el mateix treball es fes en menys temps, la potència seria més gran.', 'bomb_t09_fisica', (select id from public.topics where slug = 'bomb-t09-fisica'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-09-MAN.GRAL.003.pdf'), 'MAN.GRAL.003, § potència', 'Com el treball (J) realitzat dividit pel temps (s), o com la força (N) per la velocitat (m/s). La potència es mesura en watts (W).', null, 'd59f8e61ee7a58a46b75efb3e5ea8ddcfd0a811a785093529fefc7d8970c7a80', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'd59f8e61ee7a58a46b75efb3e5ea8ddcfd0a811a785093529fefc7d8970c7a80')
