  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Cal arribar a una finestra a 8 m d''alçada amb la base de l''escala a 6 m de la paret. Segons el teorema de Pitàgores del manual de Física, quina longitud mínima ha de tenir l''escala?', 'l² = 8² + 6² = 64 + 36 = 100, per tant l = 10 m (és el triangle 6-8-10, múltiple del 3-4-5).', 'bomb_t09_fisica', (select id from public.topics where slug = 'bomb-t09-fisica'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-09-MAN.GRAL.003.pdf'), 'MAN.GRAL.003, § teorema de Pitàgores', 'El teorema estableix que el quadrat de la hipotenusa (el costat més llarg del triangle, c) és igual a la suma dels quadrats dels altres dos costats (els catets, a i b).', null, 'ca1b96fd0645090c46b1c4b8acd8dab87f282c7f29d324c17eb286c42d3108cd', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'ca1b96fd0645090c46b1c4b8acd8dab87f282c7f29d324c17eb286c42d3108cd')
