with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Un bomber treballa a 20 m sobre el carrer amb un martell de 2 kg. Segons el manual de Física (g = 9,8 m/s²), quina energia potencial té el martell respecte al carrer?', 'Ep = m · g · h = 2 · 9,8 · 20 = 392 J. Si la referència fos el terra de la cistella, l''alçada i l''energia serien molt més petites.', 'bomb_t09_fisica', (select id from public.topics where slug = 'bomb-t09-fisica'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-09-MAN.GRAL.003.pdf'), 'MAN.GRAL.003, § energia potencial', 'L’energia potencial gravitacional és l''energia que té un objecte a causa de la seva alçada. […] g és l’acceleració de la gravetat terrestre, 9,8 m/s 2', null, '7af593f844c4615bf1627462480150146597d2e2bb36f581cedac092cab66035', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '7af593f844c4615bf1627462480150146597d2e2bb36f581cedac092cab66035')
