  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Remolques un vehicle 10 m amb una eslinga que tiba amb 2.000 N formant 60° amb la direcció del desplaçament. Segons el manual de Física (cos 60° = 0,5), quin treball fas?', 'Només treballa la component en la direcció del moviment: Fx = 2.000 · cos 60° = 1.000 N; W = 1.000 · 10 = 10.000 J. 20.000 J seria ignorar l''angle i 17.320 J, usar el sinus.', 'bomb_t09_fisica', (select id from public.topics where slug = 'bomb-t09-fisica'), 3, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-09-MAN.GRAL.003.pdf'), 'MAN.GRAL.003, § treball', 'només la component de la força projectada en la direcció del moviment és la que realitza treball […] Fx = 1000 · cos (60º)= 1000 · 0,5= 500 N.', null, '3e4a9e1e1e28e82ba55257adeaca0901fa73e0ad5eb826e4864551e743ba9c5a', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '3e4a9e1e1e28e82ba55257adeaca0901fa73e0ad5eb826e4864551e743ba9c5a')
  returning id
