)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Has de pujar una càrrega de 800 N per una rampa de 6 m de llarg fins a 1,5 m d''alçada. Segons el manual de Física, sense fregament, quina força cal aplicar?', 'AM = L / h = 6 / 1,5 = 4; F = P · h / L = 800 / 4 = 200 N. Amb fregament caldria sumar-hi la força per vèncer-lo.', 'bomb_t09_fisica', (select id from public.topics where slug = 'bomb-t09-fisica'), 3, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-09-MAN.GRAL.003.pdf'), 'MAN.GRAL.003, § pla inclinat', 'L''avantatge mecànic (AM) d''un pla inclinat és la relació entre la força que hauríem de fer per aixecar-lo (el pes de l''objecte) i la força que fem realment per moure''l. […] Això significa que com més llarg és el pla inclinat respecte a la seva alçada, més gran és l''avantatge mecànic i menys força s''ha d''aplicar.', null, '496885029638b93a439ec1d8c4ae372014911a4712249203a814507817046a9e', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '496885029638b93a439ec1d8c4ae372014911a4712249203a814507817046a9e')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', '200 N.', true), ('B', '3.200 N.', false), ('C', '533 N.', false), ('D', '800 N.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'El braç d''una autoescala de 20 m forma 30° amb el terra horitzontal. Segons el manual de Física (sin 30° = 0,5), a quina alçada arriba l''extrem del braç respecte a la base del braç?', 'L''alçada és el costat oposat i el braç, la hipotenusa: alçada = 20 · sin 30° = 20 · 0,5 = 10 m. 17,3 m sortiria d''usar el cosinus (distància horitzontal).', 'bomb_t09_fisica', (select id from public.topics where slug = 'bomb-t09-fisica'), 3, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-09-MAN.GRAL.003.pdf'), 'MAN.GRAL.003, § trigonometria bàsica', 'Utilitzem el sinus, ja que relaciona el costat oposat (alçada) amb la hipotenusa (braç de l''escala). […] sin α 0 √1 2 = 0,5', null, '5f1d515396db3febfa3fe7a2553c7ff2ceb2bf52d65fd9742a7adadc3efec43c', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '5f1d515396db3febfa3fe7a2553c7ff2ceb2bf52d65fd9742a7adadc3efec43c')
  returning id
), o as (
