with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Un camió de 8.000 kg a 10 m/s xoca per darrere amb un cotxe aturat de 2.000 kg i queden enganxats. Segons el principi de conservació de la quantitat de moviment del manual de Física, sense forces externes, a quina velocitat es mou el conjunt just després del xoc?', 'p inicial = 8.000 · 10 + 2.000 · 0 = 80.000 kg·m/s; massa final 10.000 kg; v = 80.000 / 10.000 = 8 m/s.', 'bomb_t09_fisica', (select id from public.topics where slug = 'bomb-t09-fisica'), 3, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-09-MAN.GRAL.003.pdf'), 'MAN.GRAL.003, § conservació de la quantitat de moviment', 'la quantitat de moviment total del sistema es manté constant abans i després d''un esdeveniment, com un xoc.', null, '26a7aedd10357017edf0d470260354e32ba83145a9723fa3581daaaf9f15d5a9', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '26a7aedd10357017edf0d470260354e32ba83145a9723fa3581daaaf9f15d5a9')
