with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual de Química, quin tipus d''enllaç, amb un núvol d''electrons que es mouen lliurement, confereix als materials conductivitat elèctrica i tèrmica, ductilitat i mal·leabilitat?', 'En l''enllaç metàl·lic els àtoms comparteixen els electrons més externs, que formen un núvol electrònic; aquesta estructura dona als metalls conductivitat, ductilitat i mal·leabilitat.', 'bomb_t10_quimica', (select id from public.topics where slug = 'bomb-t10-quimica'), 1, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-10-MAN.GRAL.004.pdf'), 'MAN.GRAL.004, § 3.1.3 enllaç metàl·lic', 'L’enllaç metàl·lic és la unió característica dels metalls, en què els àtoms comparteixen els seus electrons més externs. Aquests electrons es mouen lliurement formant un núvol electrònic que envolta els nuclis metàl·lics. Aquesta estructura confereix als metalls les seves propietats típiques: conductivitat elèctrica i tèrmica, ductilitat, mal·leabilitat i, sovint, duresa.', null, '11a1bae51483eff78856a1c80d88480265e1ba09e3aadda6fb659182c31f1749', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '11a1bae51483eff78856a1c80d88480265e1ba09e3aadda6fb659182c31f1749')
  returning id
