with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual de Química, quin tipus de reacció explica que l''aigua dura reaccioni amb components del concentrat d''escuma i formi precipitats que poden obstruir injectors?', 'La substitució doble (AB + CD → AD + CB) és un intercanvi d''ions entre dos compostos; amb aigua dura pot generar sals insolubles que fan l''escuma menys estable.', 'bomb_t10_quimica', (select id from public.topics where slug = 'bomb-t10-quimica'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-10-MAN.GRAL.004.pdf'), 'MAN.GRAL.004, § 4.1.4 reacció de substitució doble', 'Intercanvi d’ions entre dos compostos formant dos compostos nous. AB+CD→AD+CB Exemple aplicat: Quan es barregen aigua i additius escumògens, els ions presents a l’aigua (sobretot si és dura, amb molta concentració de calci i magnesi) poden reaccionar amb alguns components del concentrat d’escuma.', null, 'ccfad9e8ee09449e8c09823426e28c9dd1397547748c50072e163312441a0e18', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'ccfad9e8ee09449e8c09823426e28c9dd1397547748c50072e163312441a0e18')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Una reacció de substitució doble (intercanvi d''ions).', true), ('B', 'Una reacció de síntesi.', false), ('C', 'Una reacció de combustió.', false), ('D', 'Una reacció de substitució simple d''un metall.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual de Química, la degradació tèrmica de la cel·lulosa en un incendi, que genera gasos inflamables i fum tòxic, és un exemple de reacció de:', 'En la descomposició un compost es divideix en substàncies més simples, sovint per acció de la calor (piròlisi), com passa amb els materials orgànics en un incendi.', 'bomb_t10_quimica', (select id from public.topics where slug = 'bomb-t10-quimica'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-10-MAN.GRAL.004.pdf'), 'MAN.GRAL.004, § 4.1.2 reacció de descomposició', 'Un compost es divideix en dues o més substàncies més simples, sovint per acció de calor (piròlisi).', null, 'de1d63671b0c54692604a424db1e8c6e3eb749c9719cb28ae5160f8d1849eaed', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'de1d63671b0c54692604a424db1e8c6e3eb749c9719cb28ae5160f8d1849eaed')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Síntesi.', false), ('B', 'Neutralització.', false), ('C', 'Substitució simple.', false), ('D', 'Descomposició (piròlisi).', true)) as v(label, body, ok)
)
