with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual de Química, quantes vegades més conductora tèrmica és l''aigua que l''aire, fet que explica cremades per vapor tot i dur l''EPI?', 'L''aigua és 20 vegades més conductora tèrmica que l''aire; l''aire sec és un bon aïllant, però amb humitat passa a ser un bon conductor.', 'bomb_t10_quimica', (select id from public.topics where slug = 'bomb-t10-quimica'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-10-MAN.GRAL.004.pdf'), 'MAN.GRAL.004, § 9.2 conductivitat tèrmica', 'L''aigua és 20 vegades més conductora tèrmica que l''aire', null, 'ebb95495d0cf1b50b56933292c4a7881e590dcc9281a82604679afa41a2b79ff', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'ebb95495d0cf1b50b56933292c4a7881e590dcc9281a82604679afa41a2b79ff')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', '2 vegades.', false), ('B', '200 vegades.', false), ('C', '20 vegades.', true), ('D', 'Igual, perquè tots dos són fluids.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'En la combustió del propà, C₃H₈ + 5 O₂ → 3 CO₂ + 4 H₂O, es disposa d''1 mol de propà i 4 mol d''oxigen. Seguint el mètode del manual de Química, quin és el reactiu limitant?', 'Es divideixen els mols pels coeficients: propà 1/1 = 1; oxigen 4/5 = 0,8. El valor més petit indica el limitant: l''oxigen; el propà queda en excés.', 'bomb_t10_quimica', (select id from public.topics where slug = 'bomb-t10-quimica'), 3, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-10-MAN.GRAL.004.pdf'), 'MAN.GRAL.004, § 5.4 reactiu limitant', 'Dividir aquests mols pels coeficients estequiomètrics corresponents de l’equació ajustada. 3. El valor més petit indica el reactiu limitant. Per exemple, en la combustió del propà: C3H8+5 O2→3 CO2+4 H2O', null, '57fd60d191bf8f7d8568ac9a7ce6d0175a470f370ea83befbf4dc25d7eb2d4c3', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '57fd60d191bf8f7d8568ac9a7ce6d0175a470f370ea83befbf4dc25d7eb2d4c3')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El propà, perquè n''hi ha menys mols.', false), ('B', 'L''oxigen, perquè 4/5 = 0,8 és més petit que 1/1 = 1.', true), ('C', 'Cap dels dos, perquè estan en la proporció exacta.', false), ('D', 'El propà, perquè 1/1 = 1 és el valor més gran.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Una ampolla de gas a 200 bar i 27 °C (300 K) s''escalfa en un incendi fins a 327 °C (600 K) sense variar el volum. Segons la llei de Gay-Lussac del manual de Química, quina pressió assolirà?', 'P₁/T₁ = P₂/T₂ amb T en kelvin: 200/300 = P₂/600 → P₂ = 400 bar. Si s''usen graus Celsius (200 · 327/27) s''obté un resultat erroni d''uns 2.422 bar.', 'bomb_t10_quimica', (select id from public.topics where slug = 'bomb-t10-quimica'), 3, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-10-MAN.GRAL.004.pdf'), 'MAN.GRAL.004, § 6.3.4 llei de Gay-Lussac', 'Aquesta llei es simbolitza amb la relació següent, en la qual la temperatura s''ha d''expressar en graus Kelvin: P/T = constant (V = ct)', null, '0e2451b432a3326af6b22b0f41b423d427bd678dc4962570eeab384741d410c2', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '0e2451b432a3326af6b22b0f41b423d427bd678dc4962570eeab384741d410c2')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', '400 bar.', true), ('B', '200 bar.', false), ('C', 'Uns 2.422 bar.', false), ('D', '100 bar.', false)) as v(label, body, ok)
)
