select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons les dades del manual de Química (Ce de l''aigua = 1 cal/g°C i calor latent de vaporització = 539 cal/g), quanta calor cal per convertir en vapor 2 kg d''aigua que són a 20 °C?', 'Escalfar fins a 100 °C: 2.000 · 1 · 80 = 160 kcal; vaporitzar: 2.000 · 539 = 1.078 kcal; total 1.238 kcal. 619 kcal és el resultat per a 1 kg.', 'bomb_t10_quimica', (select id from public.topics where slug = 'bomb-t10-quimica'), 3, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-10-MAN.GRAL.004.pdf'), 'MAN.GRAL.004, § 7.3.2 calor latent', 'Q 1 = m·Ce·(T ebullició-T inicial ) […] Q 2 = m · Lvaporització Q 2 = 1000 g · 539 cal/g = 539000 cal = 539 kcal', null, '8122e3ef2551c96a9ee7a9acf1e7375edfa958157b7498ca9ce9223b47ab8884', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '8122e3ef2551c96a9ee7a9acf1e7375edfa958157b7498ca9ce9223b47ab8884')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', '1.078 kcal.', false), ('B', '1.238 kcal.', true), ('C', '160 kcal.', false), ('D', '619 kcal.', false)) as v(label, body, ok)
)
