with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'En la combustió completa de 32 g de metà amb 128 g d''oxigen es formen 88 g de CO₂. Segons la llei de conservació de la massa, quina massa d''aigua es forma?', 'Massa de reactius = 32 + 128 = 160 g; massa d''aigua = 160 − 88 = 72 g. És el doble de l''exemple del manual (16 g + 64 g → 44 g + 36 g).', 'bomb_t10_quimica', (select id from public.topics where slug = 'bomb-t10-quimica'), 3, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-10-MAN.GRAL.004.pdf'), 'MAN.GRAL.004, § 4.2 llei de conservació de la massa', 'en la combustió completa del metà, 16 g de CH₄ reaccionen amb 64 g d’O₂ per produir 44 g de CO₂ i 36 g d’H₂O.', null, '16b48c3cc36d209796a9103c381491c29e7b8007ecaab7318b9adfc0db4b3b93', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '16b48c3cc36d209796a9103c381491c29e7b8007ecaab7318b9adfc0db4b3b93')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', '36 g.', false), ('B', '160 g.', false), ('C', '72 g.', true), ('D', '40 g.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el conveni de signes del manual de Química, què indica que la calor intercanviada per un sistema sigui negativa (q < 0)?', 'q > 0: el sistema absorbeix calor (endotèrmic); q < 0: el sistema cedeix calor a l''entorn (exotèrmic).', 'bomb_t10_quimica', (select id from public.topics where slug = 'bomb-t10-quimica'), 3, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-10-MAN.GRAL.004.pdf'), 'MAN.GRAL.004, § 7.2 entalpia, calor i treball', 'q > 0: el sistema absorbeix calor (procés endotèrmic). q < 0: el sistema cedeix calor a l’entorn (procés exotèrmic).', null, '84856e13eb6e4998236f870897b5cbfe9ef683a10c72f6f0413a4fe48068cdc5', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '84856e13eb6e4998236f870897b5cbfe9ef683a10c72f6f0413a4fe48068cdc5')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Que el sistema absorbeix calor: és un procés endotèrmic.', false), ('B', 'Que el sistema fa treball d''expansió sense intercanviar calor.', false), ('C', 'Que la temperatura del sistema és inferior a 0 °C.', false), ('D', 'Que el sistema cedeix calor a l''entorn: és un procés exotèrmic.', true)) as v(label, body, ok)
)
