insert into public.sources (title, url, kind, publisher, published_on) values ('Cos de Bombers de la Generalitat · MAN.GRAL.005 Manual operatiu bàsic d''electricitat (Guia orientativa d''estudi, convocatòria 81/26)', 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-11-MAN.GRAL.005.pdf', 'web_oficial'::public.source_kind, 'Generalitat de Catalunya · Departament d''Interior i Seguretat Pública (DGPEIS)', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('bomb-t11-electricitat', 'Tema 11. Electricitat') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('bombers-generalitat') and t.slug = 'bomb-t11-electricitat' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el Manual operatiu bàsic d''electricitat, en quin sentit es mouen realment els electrons en un circuit?', 'Per convenció històrica es va dir que el corrent anava del + al −, però físicament els electrons van del pol negatiu (excés d''electrons) al positiu.', 'bomb_t11_electricitat', (select id from public.topics where slug = 'bomb-t11-electricitat'), 1, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-11-MAN.GRAL.005.pdf'), 'MAN.GRAL.005, § sentit del corrent', 'No obstant això, en la realitat física, els electrons es mouen des del pol negatiu (on hi ha un excés d''electrons) cap al pol positiu (on hi ha una manca d''electrons).', null, 'af95f57863dcc1d9ca14877553dab420e2013e9e883246a8368462f49c9364b7', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'af95f57863dcc1d9ca14877553dab420e2013e9e883246a8368462f49c9364b7')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Des del pol positiu cap al pol negatiu.', false), ('B', 'Del neutre a la fase.', false), ('C', 'En els dos sentits alhora, en qualsevol tipus de corrent.', false), ('D', 'Des del pol negatiu cap al pol positiu.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual d''electricitat, quin és un exemple de font de corrent continu?', 'En el corrent continu els electrons circulen sempre en el mateix sentit: piles, bateries i panells solars. A les llars arriba corrent altern.', 'bomb_t11_electricitat', (select id from public.topics where slug = 'bomb-t11-electricitat'), 1, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-11-MAN.GRAL.005.pdf'), 'MAN.GRAL.005, § corrent continu', 'Els electrons circulen sempre en el mateix sentit. […] Piles, bateries, panells solars.', null, 'da0f360d65b0ce4d42c05afdc119a1173feb30e30007547ee23801470566035f', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'da0f360d65b0ce4d42c05afdc119a1173feb30e30007547ee23801470566035f')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La xarxa elèctrica domèstica.', false), ('B', 'Un alternador de central.', false), ('C', 'Una bateria.', true), ('D', 'La presa de corrent de 230 V d''un habitatge.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual d''electricitat, quin dels materials següents és un aïllant?', 'Són aïllants el plàstic, la goma, el vidre, la ceràmica, la fusta seca i l''aire. El coure i l''aigua amb sals són conductors, i el silici és un semiconductor.', 'bomb_t11_electricitat', (select id from public.topics where slug = 'bomb-t11-electricitat'), 1, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-11-MAN.GRAL.005.pdf'), 'MAN.GRAL.005, § materials aïllants', 'Exemples: plàstic, goma, vidre, ceràmica, fusta seca, aire.', null, '711ea9b43d5f03d5c4f428f3fef3bcab47d1915c5c853f66902492fabd0f1808', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '711ea9b43d5f03d5c4f428f3fef3bcab47d1915c5c853f66902492fabd0f1808')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El vidre.', true), ('B', 'El coure.', false), ('C', 'L''aigua amb sals.', false), ('D', 'El silici.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Com defineix el manual d''electricitat la resistència elèctrica?', 'La resistència és l''oposició al pas del corrent i és inversa a la conductivitat; la càrrega per segon és la intensitat.', 'bomb_t11_electricitat', (select id from public.topics where slug = 'bomb-t11-electricitat'), 1, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-11-MAN.GRAL.005.pdf'), 'MAN.GRAL.005, § resistència', 'Resistència La resistència elèctrica és l''oposició que un material presenta al pas del corrent elèctric.', null, 'c342e5da302c5b4d0f609d11dfdd03b3746b5cfbda4b82842a89937366e00cef', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'c342e5da302c5b4d0f609d11dfdd03b3746b5cfbda4b82842a89937366e00cef')
