  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual d''electricitat, quin és el llindar crític d''intensitat de corrent altern (a 50 Hz) per sota del qual la probabilitat de fibril·lació ventricular és menor en un percentatge elevat de la població?', 'Per sota de 30 mA hi pot haver dolor i contraccions, però la fibril·lació és menys probable. Amb corrent continu no es produeix fibril·lació ventricular.', 'bomb_t11_electricitat', (select id from public.topics where slug = 'bomb-t11-electricitat'), 3, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-11-MAN.GRAL.005.pdf'), 'MAN.GRAL.005, § fibril·lació ventricular', 'S''ha establert el llindar crític de 30 mA (a 50 Hz): per sota d''aquest valor, tot i que es pot experimentar dolor, contraccions musculars o dificultat per respirar, la probabilitat de fibril·lació ventricular és menor en un percentatge elevat de la població.', null, 'c6b22dba51bc7e955f99a822db6f020f73d1927d4c5e5ce43d6fbbc122383146', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'c6b22dba51bc7e955f99a822db6f020f73d1927d4c5e5ce43d6fbbc122383146')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', '30 mA.', true), ('B', '3 mA.', false), ('C', '300 mA.', false), ('D', '3 A.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual d''electricitat, quina afirmació és CORRECTA sobre els efectes del corrent continu (DC) en el cor?', 'El manual diu que amb DC no hi ha fibril·lació ventricular, però sí que hi pot haver una contracció involuntària del cor i aturada cardíaca amb intensitats superiors.', 'bomb_t11_electricitat', (select id from public.topics where slug = 'bomb-t11-electricitat'), 3, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-11-MAN.GRAL.005.pdf'), 'MAN.GRAL.005, § corrent continu i cos humà', 'Amb corrent continu (DC), no es produeix fibril·lació ventricular. […] No obstant això, amb intensitats superiors, sí que pot haver-hi una contracció involuntària del cor que resulti en una aturada cardíaca.', null, '2926a8b311e8dffb5451cb6bd929ea86a3f6d53cbb039998a432a103724f56a1', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '2926a8b311e8dffb5451cb6bd929ea86a3f6d53cbb039998a432a103724f56a1')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Produeix fibril·lació ventricular a partir de 3 mA.', false), ('B', 'No té cap efecte sobre el cor, sigui quina sigui la intensitat.', false), ('C', 'No produeix fibril·lació ventricular, però a intensitats altes pot provocar una contracció involuntària que acabi en aturada cardíaca.', true), ('D', 'És més perillós que l''altern perquè produeix fibril·lació a qualsevol intensitat.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Prop d''un cable d''alta tensió caigut a terra, què recomana el manual d''electricitat per reduir el risc de la tensió de pas?', 'Com més separats estan els peus i més a prop del cable, més diferència de potencial i més corrent pel cos; per això cal fer passos petits amb els peus junts.', 'bomb_t11_electricitat', (select id from public.topics where slug = 'bomb-t11-electricitat'), 3, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-11-MAN.GRAL.005.pdf'), 'MAN.GRAL.005, § tensió de pas', 'En aquests casos es recomana fer passos petits amb els peus ben junts i tocant-se, i mai estirar-se a terra ni caure.', null, '48289fedd3c3c393273ccf2e157cb9a7eb639f10b015b082556906095a114b00', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '48289fedd3c3c393273ccf2e157cb9a7eb639f10b015b082556906095a114b00')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Fer passes llargues per allunyar-se com més aviat millor.', false), ('B', 'Fer passos petits amb els peus ben junts i tocant-se, sense estirar-se a terra ni caure.', true), ('C', 'Estirar-se a terra per repartir el contacte.', false), ('D', 'Córrer saltant amb els dos peus alhora.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual d''electricitat, quina característica d''un conductor li permet transportar més corrent?', 'Com més curt i gruixut és el conductor, menys resistència ofereix i més corrent pot transportar.', 'bomb_t11_electricitat', (select id from public.topics where slug = 'bomb-t11-electricitat'), 3, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-11-MAN.GRAL.005.pdf'), 'MAN.GRAL.005, § conductors', 'Com més curt i gruixut és el conductor, més corrent pot transportar.', null, 'a339e91ba3b8cb88892a287e593a144b2016c864b00dc0975c919cd4387e73c7', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'a339e91ba3b8cb88892a287e593a144b2016c864b00dc0975c919cd4387e73c7')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
