)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual d''electricitat, en quina unitat s''expressa més comunament l''energia elèctrica consumida, que és el que es paga a la factura?', 'L''energia és la potència consumida al llarg del temps i es mesura en Wh o kWh. L''Ah mesura la capacitat, no l''energia; el kW és potència.', 'bomb_t11_electricitat', (select id from public.topics where slug = 'bomb-t11-electricitat'), 1, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-11-MAN.GRAL.005.pdf'), 'MAN.GRAL.005, § 3.6 energia (consum)', 'Unitat de mesura: El watt-hora (Wh) o, més comunament, el kilowatt-hora (kWh).', null, '0f9f96f54e9e2352c4f731045c5de58a8dd254053db4af9333295807dc66af7c', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '0f9f96f54e9e2352c4f731045c5de58a8dd254053db4af9333295807dc66af7c')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'En kilowatts (kW).', false), ('B', 'En amperes-hora (Ah).', false), ('C', 'En kilowatts-hora (kWh).', true), ('D', 'En kilovolts-amperes (kVA).', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual d''electricitat, quina és la freqüència estàndard del corrent altern a Europa?', 'A Europa la freqüència és de 50 Hz: 50 cicles per segon. 230 és la tensió eficaç en volts, no una freqüència.', 'bomb_t11_electricitat', (select id from public.topics where slug = 'bomb-t11-electricitat'), 1, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-11-MAN.GRAL.005.pdf'), 'MAN.GRAL.005, § 7.2 corrent altern (freqüència)', 'A Europa, la freqüència estàndard és de 50 Hertz (Hz), el que significa que la tensió i la intensitat completen 50 cicles per segon', null, '3a0374408676914d1764cccf782ebdc7ebb8ed2b3f06d46d2765003067ba04cb', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '3a0374408676914d1764cccf782ebdc7ebb8ed2b3f06d46d2765003067ba04cb')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', '60 Hz.', false), ('B', '50 Hz.', true), ('C', '100 Hz.', false), ('D', '230 Hz.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'En el símil hidràulic del manual d''electricitat, a què equival la intensitat del corrent?', 'Tensió ↔ pressió; intensitat ↔ cabal; resistència ↔ escanyament o rugositat; generador ↔ bomba.', 'bomb_t11_electricitat', (select id from public.topics where slug = 'bomb-t11-electricitat'), 1, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-11-MAN.GRAL.005.pdf'), 'MAN.GRAL.005, § 6 símil hidràulic', 'Intensitat, corrent (A) Cabal (quantitat d’aigua per unitat de temps)', null, '8039cf18067751f11dbb53db51653ff4aba608c776217ce18a16593fba2adbd7', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '8039cf18067751f11dbb53db51653ff4aba608c776217ce18a16593fba2adbd7')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Al cabal, la quantitat d''aigua per unitat de temps.', true), ('B', 'A la pressió de l''aigua.', false), ('C', 'A l''escanyament o rugositat de la canonada.', false), ('D', 'A la bomba d''aigua.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Una resistència de 46 Ω es connecta a 230 V. Segons la llei d''Ohm del manual d''electricitat, quina intensitat hi circula?', 'I = V / R = 230 V / 46 Ω = 5 A. Multiplicar (230 · 46) o dividir al revés (46/230 = 0,2) és incorrecte.', 'bomb_t11_electricitat', (select id from public.topics where slug = 'bomb-t11-electricitat'), 1, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-11-MAN.GRAL.005.pdf'), 'MAN.GRAL.005, § 4.1 llei d''Ohm', 'Es pot expressar amb la següent fórmula: I = V / R', null, '0845879f63edcef7ef5fbce4e14aa4bed490a39242389ad760e4875ee284c598', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '0845879f63edcef7ef5fbce4e14aa4bed490a39242389ad760e4875ee284c598')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', '0,2 A.', false), ('B', '10.580 A.', false), ('C', '184 A.', false), ('D', '5 A.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual d''electricitat, quin element d''un circuit bàsic converteix l''energia elèctrica en llum, calor o moviment?', 'La font crea la diferència de potencial, els conductors transporten el corrent, l''interruptor obre o tanca el circuit i el receptor (bombeta, motor) transforma l''energia.', 'bomb_t11_electricitat', (select id from public.topics where slug = 'bomb-t11-electricitat'), 1, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-11-MAN.GRAL.005.pdf'), 'MAN.GRAL.005, § 5.1 elements d''un circuit bàsic', 'Receptor o càrrega: Converteix l’energia elèctrica en llum, calor, moviment, etc. (ex. bombeta, motor).', null, '29cdec8f7ddb709a1cb59949d31dd60f94aef2ce2778b836e62d779849671e77', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '29cdec8f7ddb709a1cb59949d31dd60f94aef2ce2778b836e62d779849671e77')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La font de tensió.', false), ('B', 'El receptor o càrrega.', true), ('C', 'El conductor.', false), ('D', 'L''interruptor.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual d''electricitat, indica la resposta INCORRECTA:', 'Els transformadors només funcionen amb corrent altern. La resta d''afirmacions coincideixen amb el manual.', 'bomb_t11_electricitat', (select id from public.topics where slug = 'bomb-t11-electricitat'), 1, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-11-MAN.GRAL.005.pdf'), 'MAN.GRAL.005, § 7.3 i 8.2 conversions i transformadors', 'Són reversibles i només funcionen amb corrent altern. […] La rectificació transforma el corrent altern en continu. Es fa principalment amb díodes […] La inversió converteix la DC en AC. […] l’alternador del cotxe genera AC, que després es rectifica a DC per carregar la bateria.', null, 'b7b44ecf2e61d1e39f4a232a2d1848ca9a7cf63c9f6788fcaf4b274555b6b599', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'b7b44ecf2e61d1e39f4a232a2d1848ca9a7cf63c9f6788fcaf4b274555b6b599')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La rectificació transforma el corrent altern en continu, principalment amb díodes.', false), ('B', 'Els inversors converteixen el corrent continu en altern.', false), ('C', 'L''alternador del cotxe genera corrent altern, que es rectifica per carregar la bateria.', false), ('D', 'Els transformadors permeten pujar o baixar la tensió del corrent continu.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Una estufa (càrrega resistiva) connectada a 230 V consumeix 10 A. Quina potència té, segons la fórmula bàsica del manual d''electricitat?', 'P = V × I = 230 V × 10 A = 2.300 W (2,3 kW). Aquesta fórmula és vàlida en continu o amb càrregues purament resistives en altern.', 'bomb_t11_electricitat', (select id from public.topics where slug = 'bomb-t11-electricitat'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-11-MAN.GRAL.005.pdf'), 'MAN.GRAL.005, § 4.3 potència elèctrica', 'La formula (bàsica) per calcular la potència elèctrica és vàlida en corrent continu o per càrregues purament resistives en corrent altern: P = V × I', null, '4284343277146dab8ad731afa2fdb7c3ff9a3313ba273b393f40d22faf5430c0', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '4284343277146dab8ad731afa2fdb7c3ff9a3313ba273b393f40d22faf5430c0')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', '23 W.', false), ('B', '240 W.', false), ('C', '2.300 W.', true), ('D', '23.000 W.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Una estufa de 1.500 W funciona durant 4 hores. Seguint els exemples del manual d''electricitat, quina energia consumeix?', 'Energia = potència × temps = 1,5 kW × 4 h = 6 kWh (6.000 Wh, no 6.000 kWh).', 'bomb_t11_electricitat', (select id from public.topics where slug = 'bomb-t11-electricitat'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-11-MAN.GRAL.005.pdf'), 'MAN.GRAL.005, § 3.6 energia (consum)', 'Una bombeta de 10 W encesa durant10 hores consumeix 100 Wh = 0.1 kWh. Un termo elèctric de 1000 W escalfant aigua durant 2 hores consumeix 2 kWh.', null, '88ff28d7b0ad14e2975be025f63ebd538c9b7e297fd3dece928878db0f8984b6', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '88ff28d7b0ad14e2975be025f63ebd538c9b7e297fd3dece928878db0f8984b6')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', '6 kWh.', true), ('B', '0,375 kWh.', false), ('C', '6.000 kWh.', false), ('D', '1,5 kWh.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Tres resistències de 10 Ω, 20 Ω i 30 Ω es connecten en sèrie a una font de 120 V. Segons el manual d''electricitat, quina intensitat circula pel circuit?', 'Rtotal = 10 + 20 + 30 = 60 Ω; I = V / Rtotal = 120 / 60 = 2 A, la mateixa per a tots els elements.', 'bomb_t11_electricitat', (select id from public.topics where slug = 'bomb-t11-electricitat'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-11-MAN.GRAL.005.pdf'), 'MAN.GRAL.005, § 5.2.1 connexió en sèrie', 'Rtotal = R1 + R2 + R3 + ... […] Itotal = V / Rtotal', null, '7005373b7cc60dfe82fb93ff840c1e60ff7ca17267d82c48aaa04f1ba8de9a8d', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '7005373b7cc60dfe82fb93ff840c1e60ff7ca17267d82c48aaa04f1ba8de9a8d')
  returning id
), o as (
