)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Dues resistències iguals de 60 Ω es connecten en paral·lel. Segons la fórmula del manual d''electricitat, quina és la resistència equivalent?', '1/Rtotal = 1/60 + 1/60 = 2/60 → Rtotal = 30 Ω. En paral·lel la resistència equivalent és menor que la de cada branca; 120 Ω seria la suma en sèrie.', 'bomb_t11_electricitat', (select id from public.topics where slug = 'bomb-t11-electricitat'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-11-MAN.GRAL.005.pdf'), 'MAN.GRAL.005, § 5.2.2 connexió en paral·lel', 'La resistència equivalent de varies càrregues connectades en paral·lel es calcula: 1/ Rtotal = 1/R1 + 1/R2 + 1/R3 + ...', null, '5489d9ca126494ffdf133d6df94982e9f3a7061868abd2bebf508d24c4ae6641', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '5489d9ca126494ffdf133d6df94982e9f3a7061868abd2bebf508d24c4ae6641')
