with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual d''electricitat, quines tensions es consideren segures, en condicions normals d''ambient sec, segons la normativa internacional?', 'En ambient sec: 50 V AC i 120 V DC. En ambient humit o amb la pell mullada es redueixen a la meitat: 25 V AC i 60 V DC.', 'bomb_t11_electricitat', (select id from public.topics where slug = 'bomb-t11-electricitat'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-11-MAN.GRAL.005.pdf'), 'MAN.GRAL.005, § 9.1.1 el cos humà és conductor', 'En la normativa internacional es consideren tensions segures per sota de 50V AC i 120 V DC en condicions normals (ambient sec). Si l’ambient és humit o la pell pot estar mullada (baixa la resistència), les tensions segures es redueixen a la meitat, 25 V AC i 60 V DC.', null, 'bd1277efcbbe5e0ed8b7cf270c4b163858dea23f6c155985e528516c14ea7bb7', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'bd1277efcbbe5e0ed8b7cf270c4b163858dea23f6c155985e528516c14ea7bb7')
  returning id
