with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'En un sistema trifàsic equilibrat cada fase subministra 230 V i 10 A a una càrrega resistiva. Segons el manual d''electricitat, quina és la potència total?', 'Pfase = 230 × 10 = 2.300 W; en un sistema equilibrat Ptotal = 3 × Pfase = 6.900 W.', 'bomb_t11_electricitat', (select id from public.topics where slug = 'bomb-t11-electricitat'), 3, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-11-MAN.GRAL.005.pdf'), 'MAN.GRAL.005, § 7.2.2 càlcul de potència en trifàsic', 'Si considerem un sistema equilibrat (on la tensió i la intensitat són iguals en les tres fases), la potència total es pot calcular com el triple de la potència d''una sola fase. És a dir: Ptotal = 3 × Pfase', null, 'a3c893ec8a3e836e14226fc4dc3dd69afa23c3084429b4ac73a363781d4fe56d', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'a3c893ec8a3e836e14226fc4dc3dd69afa23c3084429b4ac73a363781d4fe56d')
