with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Un grup electrogen de 10 kVA alimenta electrobombes amb un factor de potència baix. Què indica el manual d''electricitat sobre la potència útil que pot donar?', 'La capacitat en kVA és potència aparent; amb càrregues molt inductives una part és reactiva i la potència activa disponible és menor.', 'bomb_t11_electricitat', (select id from public.topics where slug = 'bomb-t11-electricitat'), 3, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-11-MAN.GRAL.005.pdf'), 'MAN.GRAL.005, § 7.2.6 consideracions pràctiques sobre la potència aparent', 'així, un equip de 10 kVA podria subministrar només 8 o 9 kW de potència activa si alimenta motors o electrobombes amb un factor de potència baix.', null, '6fb3366490ddc098498d51bfbf83d56103372e00275d6290860ae0f82dbc5819', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '6fb3366490ddc098498d51bfbf83d56103372e00275d6290860ae0f82dbc5819')
  returning id
), o as (
