)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Un camió grua toca accidentalment una línia elèctrica. Segons el manual d''electricitat, per què és perillós que una persona toqui el camió?', 'L''elevada resistència dels pneumàtics fa que el corrent cap a terra sigui petit, però la persona que toca el camió hi afegeix un camí en paral·lel més fàcil.', 'bomb_t11_electricitat', (select id from public.topics where slug = 'bomb-t11-electricitat'), 3, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-11-MAN.GRAL.005.pdf'), 'MAN.GRAL.005, § 9.1.2 el cos humà en el circuit elèctric', 'Un camió grua toca accidentalment una línia elèctrica. L''elevada resistència dels pneumàtics fa que el corrent que passa cap a terra sigui petit. Tanmateix, si una persona toca el camió, el seu cos “ofereix” un camí més fàcil (menys resistència que els pneumàtics).', null, 'b9880293a6cd342d17464a3201753cab92dc72ce0e59cea4bd36aecd17808179', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'b9880293a6cd342d17464a3201753cab92dc72ce0e59cea4bd36aecd17808179')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Perquè els pneumàtics tenen una resistència molt baixa i tot el corrent ja passa a terra.', false), ('B', 'Perquè la persona queda en sèrie amb els pneumàtics i en multiplica la resistència.', false), ('C', 'No és perillós, perquè el camió queda al mateix potencial que el terra.', false), ('D', 'Perquè el seu cos ofereix un camí cap a terra en paral·lel amb menys resistència que els pneumàtics.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Una persona amb una resistència corporal suposada de 1.000 Ω tanca el circuit entre una fase de 230 V i terra. Aplicant la llei d''Ohm del manual d''electricitat, quina intensitat la travessa i com és respecte al llindar crític?', 'I = V / R = 230 / 1.000 = 0,23 A = 230 mA, gairebé vuit vegades el llindar de 30 mA a 50 Hz.', 'bomb_t11_electricitat', (select id from public.topics where slug = 'bomb-t11-electricitat'), 3, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-11-MAN.GRAL.005.pdf'), 'MAN.GRAL.005, § 9.1.2 el cos humà en el circuit elèctric', 'el corrent que circula pel cos només queda limitat per la nostra resistència (V = I x R). […] S''ha establert el llindar crític de 30 mA (a 50 Hz)', null, '295b2e4169724ea1eef4ccad3948672b9d889a30c72433bf844f24f1ba6d9170', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '295b2e4169724ea1eef4ccad3948672b9d889a30c72433bf844f24f1ba6d9170')
  returning id
), o as (
