  select 'Segons el manual d''instal·lacions, quina sensibilitat de diferencial és obligatòria als habitatges?', 'El diferencial de 30 mA és obligatori als habitatges per protegir les persones; els de 100 o 300 mA s''utilitzen en indústries i enllumenat públic.', 'bomb_t12_installacions', (select id from public.topics where slug = 'bomb-t12-installacions'), 1, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.GRAL.007-Tema-12.-Installacions.pdf'), 'MAN.GRAL.007, § diferencials', '30 mA: obligatori a habitatges; nivell de protecció per a persones.', null, '896925e9e29adbc0436e7651236c6039db043d08a5f20d09c43a4d2627c441f3', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '896925e9e29adbc0436e7651236c6039db043d08a5f20d09c43a4d2627c441f3')
