with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual d''instal·lacions, en què consisteix la segona regla d''or («prevenir qualsevol possible realimentació»)?', 'Cal bloquejar els dispositius de tall, tenir en compte les realimentacions automàtiques i senyalitzar («Treballs en curs», «No connectar»).', 'bomb_t12_installacions', (select id from public.topics where slug = 'bomb-t12-installacions'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.GRAL.007-Tema-12.-Installacions.pdf'), 'MAN.GRAL.007, § 5 regles d''or', '2) Prevenir qualsevol possible realimentació Els dispositius utilitzats per desconnectar la instal·lació s’han d’assegurar contra qualsevol possible reconnexió, amb cadenats o bloquejos.', null, '0611a45571fffa4aa34399a54d7235d18ababa476bf1f159bede617cbec18bb7', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '0611a45571fffa4aa34399a54d7235d18ababa476bf1f159bede617cbec18bb7')
  returning id
