with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual d''instal·lacions, quina afirmació sobre el gas natural és CORRECTA?', 'El gas natural és lleuger i inodor; l''odoritzant permet detectar les fuites. Els GLP (butà i propà) es distribueixen liquats.', 'bomb_t12_installacions', (select id from public.topics where slug = 'bomb-t12-installacions'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.GRAL.007-Tema-12.-Installacions.pdf'), 'MAN.GRAL.007, § gas natural', 'El gas natural és menys dens que l’aire i té un alt poder calorífic, cosa que el fa molt eficient com a combustible. […] No és tòxic i és inolor (per això se li afegeix un component químic odoritzant per facilitar-ne la detecció en cas de fuita).', null, '0272226d6d3d08b7d9c19a224057c40e57b1d5ecd30a409b5a461067521cc1f3', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '0272226d6d3d08b7d9c19a224057c40e57b1d5ecd30a409b5a461067521cc1f3')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'És més dens que l''aire i s''acumula a les parts baixes.', false), ('B', 'És tòxic per inhalació i té una olor característica pròpia.', false), ('C', 'És menys dens que l''aire, no és tòxic i és inodor, per això se li afegeix un odoritzant.', true), ('D', 'Es distribueix en estat líquid en bombones.', false)) as v(label, body, ok)
)
