with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual d''instal·lacions, què passa amb un fusible quan actua per una sobrecàrrega o un curtcircuit?', 'El fil conductor del fusible es fon per efecte Joule i obre el circuit; a diferència del magnetotèrmic, no és reutilitzable.', 'bomb_t12_installacions', (select id from public.topics where slug = 'bomb-t12-installacions'), 1, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.GRAL.007-Tema-12.-Installacions.pdf'), 'MAN.GRAL.007, § 2.3.1 fusibles', 'Funcionen amb un fil conductor que es fon quan el corrent supera el seu valor nominal (efecte Joule), obrint el circuit i protegint cables i equips davant sobrecàrregues i curtcircuits. Quan un fusible actua, queda inutilitzat i s’ha de substituir.', null, '86a0741c57ba6fd3f32b3e63aa955fa2a682476de07e03faa57e5312576ddf84', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '86a0741c57ba6fd3f32b3e63aa955fa2a682476de07e03faa57e5312576ddf84')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Es rearma automàticament en uns segons.', false), ('B', 'Es rearma manualment amb una palanca, com un magnetotèrmic.', false), ('C', 'Queda inutilitzat i s''ha de substituir.', true), ('D', 'Continua deixant passar el corrent però avisa amb un llum.', false)) as v(label, body, ok)
)
