insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'En un servei prop d''una línia aèria es compten 12 discos a la cadena d''aïlladors. Segons la regla mnemotècnica del manual d''instal·lacions, de quina tensió aproximada és la línia?', 'La regla aproximada és 11 kV per disc: 12 × 11 = 132 kV (amb 20 discos serien 220 kV).', 'bomb_t12_installacions', (select id from public.topics where slug = 'bomb-t12-installacions'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.GRAL.007-Tema-12.-Installacions.pdf'), 'MAN.GRAL.007, § 2.2.4 infraestructures d''AT (i MT)', 'Una regla mnemotècnica aproximada per aïlladors (de vidre o ceràmica) és 11kV per peça o disc, per exemple, si veus un aïllador de 20 peces és una línia de 220 kV.', null, 'd8fad8b6ff4d5aa3574bedd0b61089f032cd0f25bf272dd4e567dd399f9af239', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'd8fad8b6ff4d5aa3574bedd0b61089f032cd0f25bf272dd4e567dd399f9af239')
