with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Abans d''intervenir en un quadre elèctric, el detector de tensió sense contacte no pita. Segons el manual d''instal·lacions, què cal fer?', 'Si el detector pita, hi ha tensió; si no pita, no es pot assegurar al 100 % que no n''hi hagi (posició, distància), i cal confirmar-ho amb un voltímetre.', 'bomb_t12_installacions', (select id from public.topics where slug = 'bomb-t12-installacions'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.GRAL.007-Tema-12.-Installacions.pdf'), 'MAN.GRAL.007, § 2.4.1 detector sense contacte', 'No obstant això, si no pita, no podem assegurar al 100% que no hi hagi tensió. […] Per tant, l''absència de senyal no eximeix de fer una segona comprovació amb un voltímetre per confirmar que realment no hi ha tensió.', null, '3bea458818ccc44819767757a086e5fd2331351b078ba699437042e223a27319', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '3bea458818ccc44819767757a086e5fd2331351b078ba699437042e223a27319')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Considerar que no hi ha tensió i començar a treballar.', false), ('B', 'Fer una segona comprovació amb un voltímetre per confirmar que realment no hi ha tensió.', true), ('C', 'Tocar el conductor amb el dors de la mà per confirmar-ho.', false), ('D', 'Repetir la prova amb el mateix detector i, si tampoc pita, actuar.', false)) as v(label, body, ok)
)
