  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual d''instal·lacions, per a quines tensions està dissenyat el tornavís buscapols?', 'El buscapols té una gran resistència en sèrie que limita el corrent a dècimes de mA, però només serveix per a 230 V entre fase i terra; fora d''aquest rang no és útil ni segur.', 'bomb_t12_installacions', (select id from public.topics where slug = 'bomb-t12-installacions'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.GRAL.007-Tema-12.-Installacions.pdf'), 'MAN.GRAL.007, § 2.4.2 tornavís buscapols', 'Important: El buscapols només està dissenyat per a les tensions usuals de la xarxa, 230 V entre la fase i el terra. Fora d''aquest rang, no és útil ni segur.', null, '3e925cceecdd4cdc553256305dfdc5f8550a3f275eeb5fb4b8dffa3ad56763ee', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '3e925cceecdd4cdc553256305dfdc5f8550a3f275eeb5fb4b8dffa3ad56763ee')
