select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'En un incendi en un habitatge amb plaques fotovoltaiques d''autoconsum sense acumulació (on-grid), s''ha tallat el subministrament de la xarxa. Segons el manual d''instal·lacions, quin risc continua present?', 'En cas de tall de xarxa l''inversor s''atura (protecció anti-illa) i no dona electricitat a la instal·lació, però el tram de DC des de les plaques fins a l''inversor està sempre en tensió amb llum.', 'bomb_t12_installacions', (select id from public.topics where slug = 'bomb-t12-installacions'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.GRAL.007-Tema-12.-Installacions.pdf'), 'MAN.GRAL.007, § 2.1.3 instal·lacions d''autoconsum', 'En cas de tall de subministrament a la xarxa, l’inversor també s’atura (protecció anti-illa) i no dona electricitat a la instal·lació. Tot i això, la part de corrent continu (DC) —plaques i cables fins a l’inversor— sempre està en tensió mentre hi hagi llum, encara que sigui poca.', null, '07153a26b5780710733f8aded79c5cf0e180f54fad8f41d96a766a510593cf17', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '07153a26b5780710733f8aded79c5cf0e180f54fad8f41d96a766a510593cf17')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Cap, perquè la protecció anti-illa deixa sense tensió tota la instal·lació, plaques incloses.', false), ('B', 'Només la bateria, que manté tensió durant hores.', false), ('C', 'L''inversor continua injectant corrent altern a la instal·lació interior.', false), ('D', 'La part de corrent continu (plaques i cables fins a l''inversor) continua en tensió mentre hi hagi llum.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual d''instal·lacions, quin risc específic presenten els grups electrògens fixos d''un edifici?', 'Els grups fixos formen part d''una instal·lació protegida, però poden arrencar sols en fallar la xarxa; la protecció limitada (sovint sense diferencial) és pròpia dels portàtils.', 'bomb_t12_installacions', (select id from public.topics where slug = 'bomb-t12-installacions'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.GRAL.007-Tema-12.-Installacions.pdf'), 'MAN.GRAL.007, § 2.1.3 grups electrògens', 'Els grups fixos formen part d’una instal·lació completa i protegida, però presenten un altre risc: poden arrancar automàticament quan falla la tensió de la xarxa. Per tant, encara que desconnectem l’alimentació principal, la instal·lació pot tornar a quedar en tensió sense avís.', null, '83e36c34ccb7f54970bce45841508213a7eadd80e6eae8ca42e99b4baeac0ec2', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '83e36c34ccb7f54970bce45841508213a7eadd80e6eae8ca42e99b4baeac0ec2')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Poden arrancar automàticament quan falla la tensió de la xarxa i tornar a posar la instal·lació en tensió sense avís.', true), ('B', 'No poden incorporar cap protecció elèctrica, a diferència dels portàtils.', false), ('C', 'Funcionen sempre en corrent continu a 800 V.', false), ('D', 'No es poden desconnectar mai.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual d''instal·lacions, quina és la quarta de les 5 regles d''or per treballar amb seguretat en una instal·lació elèctrica?', 'L''ordre és: 1) desconnectar, 2) prevenir la realimentació, 3) verificar l''absència de tensió, 4) posar a terra i en curtcircuit, 5) protegir i senyalitzar la zona.', 'bomb_t12_installacions', (select id from public.topics where slug = 'bomb-t12-installacions'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.GRAL.007-Tema-12.-Installacions.pdf'), 'MAN.GRAL.007, § 2.5 les 5 regles d''or', '3) Verificar l’absència de tensió […] 4) Posar a terra i en curtcircuit Cal curtcircuitar i connectar a terra la instal·lació perquè, en cas de realimentació accidental, la descàrrega es produeixi a terra i no arribi al personal, i saltin els dispositius de protecció.', null, 'eb3d94b6dbc300bd2a20aef4b4bcddb0bab79f51b5f50ede790429f66425c61e', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'eb3d94b6dbc300bd2a20aef4b4bcddb0bab79f51b5f50ede790429f66425c61e')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Verificar l''absència de tensió.', false), ('B', 'Protegir i senyalitzar la zona de treball.', false), ('C', 'Posar a terra i en curtcircuit.', true), ('D', 'Prevenir qualsevol possible realimentació.', false)) as v(label, body, ok)
)
