  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual d''instal·lacions, quina longitud màxima poden tenir els tubs flexibles de seguretat que connecten els aparells mòbils de gas?', 'Els tubs flexibles de seguretat incorporen autotall en cas de despreniment i no poden superar 1,5 m.', 'bomb_t12_installacions', (select id from public.topics where slug = 'bomb-t12-installacions'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.GRAL.007-Tema-12.-Installacions.pdf'), 'MAN.GRAL.007, § 4.2.1 instal·lació de gas domèstica (canonades)', 'Els aparells mòbils es connecten amb tubs flexibles de seguretat, que incorporen sistemes d’autotall en cas de despreniment. La seva longitud màxima no pot superar 1,5 metres.', null, '3a210479c3608c4c87120a4d099ce46ac11159741f7e5f2cc64fb097b784d37a', false
