with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual d''instal·lacions, a partir de quina potència és obligatori que un aparell de gas tingui conducte d''evacuació dels gasos de la combustió?', 'Els conductes d''evacuació són obligatoris en escalfadors, calderes i qualsevol aparell de gas de 4,7 kW o més.', 'bomb_t12_installacions', (select id from public.topics where slug = 'bomb-t12-installacions'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.GRAL.007-Tema-12.-Installacions.pdf'), 'MAN.GRAL.007, § 4.2.1 conductes d''evacuació', 'Són obligatoris en escalfadors, calderes i en qualsevol aparell de gas amb una potència igual o superior a 4,7 kW.', null, '376410e52498a01b1fef2f49efd9f6c3fb96872169df2cf644e24b52ec5cf714', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '376410e52498a01b1fef2f49efd9f6c3fb96872169df2cf644e24b52ec5cf714')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Igual o superior a 47 kW.', false), ('B', 'Igual o superior a 1,5 kW.', false), ('C', 'Només en aparells de més de 20 kW.', false), ('D', 'Igual o superior a 4,7 kW.', true)) as v(label, body, ok)
)
