with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual d''instal·lacions, a quina part de la xarxa de subministrament de gas natural correspon un gasoducte que treballa a 40 bar?', 'Xarxa bàsica: més de 60 bar; transport secundari: entre 16 i 60 bar; distribució: fins a 16 bar en trams principals. 40 bar és transport secundari.', 'bomb_t12_installacions', (select id from public.topics where slug = 'bomb-t12-installacions'), 3, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.GRAL.007-Tema-12.-Installacions.pdf'), 'MAN.GRAL.007, § 4.2 xarxa de subministrament de gas natural', 'Transporten gas a pressions superiors a 60 bar. […] Xarxa de transport secundari: transporten gas a pressions entre 16 i 60 bar. […] La xarxa de distribució pot operar a pressions de fins a 16 bar en trams principals.', null, '898cf08afb7b121c256efcea3e4dece8179f2d8d43a00ca041ff85eabdd936c1', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '898cf08afb7b121c256efcea3e4dece8179f2d8d43a00ca041ff85eabdd936c1')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'A la xarxa de transport secundari.', true), ('B', 'A la xarxa bàsica.', false), ('C', 'A la xarxa de distribució.', false), ('D', 'A la instal·lació receptora de l''edifici.', false)) as v(label, body, ok)
)
