with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual d''instal·lacions, la distribució de gas natural pot arribar a 4 bar i els aparells domèstics treballen habitualment a uns 20 mbar. Quantes vegades ha de reduir la pressió el regulador en aquest cas?', '4 bar = 4.000 mbar; 4.000 / 20 = 200. Dit d''una altra manera, 0,020 bar és 200 vegades menys que 4 bar.', 'bomb_t12_installacions', (select id from public.topics where slug = 'bomb-t12-installacions'), 3, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.GRAL.007-Tema-12.-Installacions.pdf'), 'MAN.GRAL.007, § 4.2 i 4.2.1 pressions del gas natural', 'En els aparells domèstics alimentats amb gas natural, la pressió d’utilització habitual és de l’ordre de 20 mbar (0,020 bar) […] La distribució de gas natural pot arribar fins a 4 bar, per la qual cosa cal reduir la pressió fins a la pressió de servei adequada per als aparells de consum.', null, '4e6684d4feb920f7e5a4b6c68c17f2d8a06acb0f5d385b46570cff263cc26ee6', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '4e6684d4feb920f7e5a4b6c68c17f2d8a06acb0f5d385b46570cff263cc26ee6')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', '200 vegades.', true), ('B', '20 vegades.', false), ('C', '2.000 vegades.', false), ('D', '5 vegades.', false)) as v(label, body, ok)
)
