with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual d''instal·lacions, indica la resposta INCORRECTA sobre la capacitat aïllant de l''equipament de bombers:', 'El manual diu que els guants d''intervenció de cuir no són aïllants, i encara menys si estan molls; per a tensió calen guants dielèctrics de la classe adequada.', 'bomb_t12_installacions', (select id from public.topics where slug = 'bomb-t12-installacions'), 3, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.GRAL.007-Tema-12.-Installacions.pdf'), 'MAN.GRAL.007, § 2.6.2 eines i equips de protecció dielèctrics', 'Els guants d’intervenció de cuir no són aïllants, i molt menys si estan molls. […] Les botes altes de cuir d’intervenció tenen sola dielèctrica. […] El casc d’intervenció pesant està certificat com aïllant fins a 440 V. […] Les escales de fibra també són dielèctriques i estan certificades.', null, '0f9afa38d8988d671443216f8a2bd673ceaa7c4288a4f67af5a9dd22032bdecb', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '0f9afa38d8988d671443216f8a2bd673ceaa7c4288a4f67af5a9dd22032bdecb')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Les botes altes de cuir d''intervenció tenen sola dielèctrica.', false), ('B', 'El casc d''intervenció pesant està certificat com a aïllant fins a 440 V.', false), ('C', 'Els guants d''intervenció de cuir proporcionen prou aïllament elèctric si estan secs.', true), ('D', 'Les escales de fibra són dielèctriques i estan certificades.', false)) as v(label, body, ok)
)
