with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Una rentadora té un defecte d''aïllament i la carcassa no té una bona presa de terra. Segons el manual d''instal·lacions, què passa quan una persona toca la carcassa en una instal·lació amb diferencial de 30 mA?', 'Sense bona presa de terra el corrent de defecte és molt petit i no fa disparar el diferencial; quan la persona toca la carcassa, la fuita passa pel cos i el diferencial dispara, amb un xoc breu considerat no letal.', 'bomb_t12_installacions', (select id from public.topics where slug = 'bomb-t12-installacions'), 3, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.GRAL.007-Tema-12.-Installacions.pdf'), 'MAN.GRAL.007, § 2.3.3 funcionament del diferencial', 'La carcassa queda en tensió però el corrent de defecte és molt petit i no fa disparar el diferencial. Quan una persona toca la carcassa, es converteix en camí cap a terra i llavors el diferencial actua. Hi ha xoc elèctric, però limitat a uns 30 mA durant un instant, considerat no letal.', null, 'c293e87073aacc4ae87a220a1fb848cda82615b9c5bd4742e91de0b6a10b77fe', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'c293e87073aacc4ae87a220a1fb848cda82615b9c5bd4742e91de0b6a10b77fe')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El diferencial ja havia disparat abans, perquè el corrent de defecte era gran.', false), ('B', 'La persona es converteix en camí cap a terra, el diferencial actua i el xoc queda limitat a uns 30 mA durant un instant.', true), ('C', 'El diferencial no actua mai sense presa de terra i la persona queda electrocutada.', false), ('D', 'No hi ha xoc, perquè el corrent de defecte és massa petit.', false)) as v(label, body, ok)
)
