select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Un col·lector soterrat d''aigües residuals fa 50 m de llargada. Segons el manual d''instal·lacions, quin desnivell mínim ha de tenir entre els extrems i on s''ha de col·locar respecte a l''aigua potable?', 'Pendent mínim del 2 %: 50 m × 0,02 = 1 m. Els col·lectors soterrats van sempre per sota de la xarxa d''aigua potable.', 'bomb_t12_installacions', (select id from public.topics where slug = 'bomb-t12-installacions'), 3, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.GRAL.007-Tema-12.-Installacions.pdf'), 'MAN.GRAL.007, § 3.2.1 col·lectors soterrats', 'En el cas de col·lectors soterrats, les canalitzacions s’han de col·locar en rases de dimensions adequades, sempre per sota de la xarxa d’aigua potable i amb un pendent mínim del 2%.', null, 'b39123f86c9c204841b4c08dbbafe23774c1e5e3214d029f14801ca2c77b3a9f', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'b39123f86c9c204841b4c08dbbafe23774c1e5e3214d029f14801ca2c77b3a9f')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', '1 m, i sempre per sobre de la xarxa d''aigua potable.', false), ('B', '0,1 m, i sempre per sota de la xarxa d''aigua potable.', false), ('C', '10 m, i a la mateixa cota que la xarxa d''aigua potable.', false), ('D', '1 m, i sempre per sota de la xarxa d''aigua potable.', true)) as v(label, body, ok)
)
