with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el Manual operatiu bàsic sobre hidràulica i bombes, la densitat d''un fluid és:', 'La densitat és massa per unitat de volum; la resistència a fluir és la viscositat i la força superficial, la tensió superficial.', 'bomb_t13_hidraulica_bombes', (select id from public.topics where slug = 'bomb-t13-hidraulica-bombes'), 1, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-13-MAN.GRAL.009.pdf'), 'MAN.GRAL.009, § densitat', 'Densitat La densitat d’un fluid és la quantitat de massa que conté per unitat de volum.', null, '8495ae267616c6c1a76e8ed2c30ce8d2b63da80c76ade3f9e000f541ee697bbd', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '8495ae267616c6c1a76e8ed2c30ce8d2b63da80c76ade3f9e000f541ee697bbd')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La resistència interna del líquid a fluir.', false), ('B', 'La quantitat de massa que conté per unitat de volum.', true), ('C', 'La força que manté unides les molècules de la superfície.', false), ('D', 'La pressió que fan les molècules que s''escapen en forma de vapor.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
