with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual d''hidràulica, què mesura la viscositat?', 'La viscositat és la resistència interna a fluir; l''aigua té una viscositat dinàmica molt baixa (0,001 Pa·s).', 'bomb_t13_hidraulica_bombes', (select id from public.topics where slug = 'bomb-t13-hidraulica-bombes'), 1, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-13-MAN.GRAL.009.pdf'), 'MAN.GRAL.009, § viscositat', 'Viscositat dinàmica (η) La viscositat és la mesura de la resistència interna d''un líquid a fluir.', null, '6c3fd3330940aa66cb711c306dcecba721e7ffbd66ab5004e137e64a61015661', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '6c3fd3330940aa66cb711c306dcecba721e7ffbd66ab5004e137e64a61015661')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La quantitat de massa per unitat de volum.', false), ('B', 'La capacitat d''un líquid de pujar per un tub estret.', false), ('C', 'La pressió total mesurada des del buit absolut.', false), ('D', 'La resistència interna d''un líquid a fluir.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
