with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual d''hidràulica, a quants metres de columna d''aigua equival aproximadament 1 bar?', '1 bar ≈ 10 m.c.a.; per això, de manera ideal i sense pèrdues, l''aigua que surt a 8 bar podria pujar uns 80 m.', 'bomb_t13_hidraulica_bombes', (select id from public.topics where slug = 'bomb-t13-hidraulica-bombes'), 1, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-13-MAN.GRAL.009.pdf'), 'MAN.GRAL.009, § unitats de pressió', '1 bar = 10 metres de columna d’aigua', null, '56c6b11e8980f1bb79b1624f3e393aa5d6130d7e270a628bedae5befaacd2176', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '56c6b11e8980f1bb79b1624f3e393aa5d6130d7e270a628bedae5befaacd2176')
  returning id
), o as (
