  select q.id, v.label, v.body, v.ok from q, (values ('A', 'A 10 metres.', true), ('B', 'A 1 metre.', false), ('C', 'A 100 metres.', false), ('D', 'A 0,76 metres.', false)) as v(label, body, ok)
)
