with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual d''hidràulica, el principi d''Arquimedes diu que un cos submergit en un fluid rep una empenta vertical cap amunt igual a:', 'L''empenta hidrostàtica és igual al pes del fluid desplaçat i explica la flotabilitat.', 'bomb_t13_hidraulica_bombes', (select id from public.topics where slug = 'bomb-t13-hidraulica-bombes'), 1, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-13-MAN.GRAL.009.pdf'), 'MAN.GRAL.009, § principi d''Arquimedes', 'Principi d’Arquímedes El Principi d’Arquímedes diu que un cos, total o parcialment submergit en un fluid experimenta una empenta vertical cap amunt (força d''empenta) que és igual al pes del fluid que desplaça.', null, '12f8535796fdcfab045fcc9fa6dd8e886ad0de3677edb33534e96d052cefc404', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '12f8535796fdcfab045fcc9fa6dd8e886ad0de3677edb33534e96d052cefc404')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El pes del cos submergit.', false), ('B', 'La pressió atmosfèrica per la superfície del cos.', false), ('C', 'El pes del fluid que desplaça.', true), ('D', 'La massa del cos multiplicada per la seva velocitat.', false)) as v(label, body, ok)
)
