with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual d''hidràulica, quin tipus de bomba és el més utilitzat pels bombers?', 'Les bombes centrífugues transformen l''energia mecànica en energia cinètica i pressió i són les més utilitzades pels bombers.', 'bomb_t13_hidraulica_bombes', (select id from public.topics where slug = 'bomb-t13-hidraulica-bombes'), 1, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-13-MAN.GRAL.009.pdf'), 'MAN.GRAL.009, § bombes centrífugues', 'Bombes centrífugues Les bombes centrífugues transformen l’energia mecànica en energia cinètica i pressió. […] Són les més utilitzades pels bombers.', null, 'fe16bca8b031ad6d7ab4866f2830ab80e00138a28e641da148582369b8555a52', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'fe16bca8b031ad6d7ab4866f2830ab80e00138a28e641da148582369b8555a52')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La bomba volumètrica de pistó.', false), ('B', 'La bomba de membrana.', false), ('C', 'La bomba centrífuga.', true), ('D', 'La bomba d''engranatges.', false)) as v(label, body, ok)
)
