with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual d''hidràulica, de quina longitud són normalment els trams de mànega que utilitzen els Bombers?', 'Les mànegues es fan en trams de 20 m amb ràcords Barcelona; també n''hi ha de 30 o 40 m per a autoescales i de 5 o 10 m per alimentar des de l''hidrant.', 'bomb_t13_hidraulica_bombes', (select id from public.topics where slug = 'bomb-t13-hidraulica-bombes'), 1, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-13-MAN.GRAL.009.pdf'), 'MAN.GRAL.009, § 6.1 mànegues', 'Les mànegues que utilitzem a Bombers són flexibles, lleugeres, de fàcil manipulació i plegat, en trams de 20 metres normalment, dotades de ràcords Barcelona d’alumini als extrems per ser acoblades entre sí.', null, '4ce4668c258768631e3b519386b580f574bf63ea0fd77ffa2bf3f25c223a87a7', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '4ce4668c258768631e3b519386b580f574bf63ea0fd77ffa2bf3f25c223a87a7')
  returning id
), o as (
