with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual d''hidràulica, quin és el tipus de manòmetre més habitual?', 'El manòmetre Bourdon transmet el moviment del tub corbat a una agulla; com que l''exterior del tub és a pressió atmosfèrica, mesura pressió relativa.', 'bomb_t13_hidraulica_bombes', (select id from public.topics where slug = 'bomb-t13-hidraulica-bombes'), 1, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-13-MAN.GRAL.009.pdf'), 'MAN.GRAL.009, § 3.1.4 manòmetres', 'El més habitual és el de tipus Bourdon, format per un tub metàl·lic corbat que s''estira a mesura que augmenta la pressió.', null, '41da1ed0145f11f24aefedb54b5f228a0374623de7777885efe772ff29075ce3', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '41da1ed0145f11f24aefedb54b5f228a0374623de7777885efe772ff29075ce3')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El vacuòmetre, que només mesura depressió.', false), ('B', 'El tub de Venturi.', false), ('C', 'El baròmetre de mercuri de Torricelli.', false), ('D', 'El de tipus Bourdon, amb un tub metàl·lic corbat que s''estira quan augmenta la pressió.', true)) as v(label, body, ok)
)
