with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual d''hidràulica, quines funcions fa la vàlvula de peu o «pinya» connectada a l''extrem d''entrada dels manegots?', 'La pinya evita que entrin objectes a la bomba i impedeix que es buidi la columna d''aigua dels manegots, de manera que no calgui tornar a cebar cada vegada que s''atura la bomba.', 'bomb_t13_hidraulica_bombes', (select id from public.topics where slug = 'bomb-t13-hidraulica-bombes'), 1, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-13-MAN.GRAL.009.pdf'), 'MAN.GRAL.009, § 6.2 manegots', 'A l’extrem d’entrada dels manegots es connecta la vàlvula de peu o “pinya”, que fa la funcions de filtre, per evitar l’entrada a la bomba d’objectes, i també de vàlvula antiretorn', null, '9140bcf3fdd8d0f475fe4b2414e9ceb0c1511ff14d689ece57c9f5c3d25ba74c', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '9140bcf3fdd8d0f475fe4b2414e9ceb0c1511ff14d689ece57c9f5c3d25ba74c')
  returning id
