with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual d''hidràulica, quin tipus de raig aconsegueix la màxima distància de projecció i força d''impacte?', 'El raig tens surt en línia recta; el con d''atac (fins a uns 50°) abasta més superfície però menys distància, i la cortina (fins a 120-130°) protegeix de la radiació.', 'bomb_t13_hidraulica_bombes', (select id from public.topics where slug = 'bomb-t13-hidraulica-bombes'), 1, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-13-MAN.GRAL.009.pdf'), 'MAN.GRAL.009, § 6.3.1 tipus de raig', 'Raig tens: El raig surt en línia recta i pràcticament no augmenta la seva secció. Aconseguim la màxima distància de projecció i força d’impacte.', null, '8f0188cc5305771b3ab57042f8b10a8941cbc88cf082a0df8ba7ebbf33f67690', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '8f0188cc5305771b3ab57042f8b10a8941cbc88cf082a0df8ba7ebbf33f67690')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El raig tens.', true), ('B', 'El con d''atac.', false), ('C', 'La cortina de protecció.', false), ('D', 'El raig polvoritzat de màxima obertura.', false)) as v(label, body, ok)
)
