with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la regla pràctica del manual d''hidràulica, fins a quina alçada ideal (sense pèrdues) es pot impulsar l''aigua que surt de la bomba a 5 bar?', '1 bar ≈ 10 m de columna d''aigua; 5 bar × 10 = 50 m (el manual posa l''exemple de 8 bar → 80 m).', 'bomb_t13_hidraulica_bombes', (select id from public.topics where slug = 'bomb-t13-hidraulica-bombes'), 1, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-13-MAN.GRAL.009.pdf'), 'MAN.GRAL.009, § 3.1.1 unitats de pressió (cas pràctic)', '1 bar = 10 metres de columna d’aigua Això permet saber, per exemple, que si l’aigua surt a 8 bar de pressió des de la bomba, pot pujar fins a uns 80 metres (de forma ideal i sense pèrdues).', null, 'db5e6cd1ee6c832b38475ce7b5aac85b7f2e022b49a3f18a885cbffd45c660cf', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'db5e6cd1ee6c832b38475ce7b5aac85b7f2e022b49a3f18a885cbffd45c660cf')
  returning id
