with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual d''hidràulica, quin tipus de circulació de l''aigua és el més comú en les operacions de bombers?', 'La circulació forçada permet impulsar l''aigua a grans distàncies i superar desnivells; la circulació lliure per gravetat no és habitual en emergències.', 'bomb_t13_hidraulica_bombes', (select id from public.topics where slug = 'bomb-t13-hidraulica-bombes'), 1, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-13-MAN.GRAL.009.pdf'), 'MAN.GRAL.009, § 4.1.1 circulació lliure o forçada', 'Circulació forçada: el líquid és impulsat per una bomba, generant una pressió que força el moviment. És el tipus més comú en les operacions de bombers', null, 'fbe7854e983bed9846c86da135db71b48b2ca25f364936b48c8927dc956551c1', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'fbe7854e983bed9846c86da135db71b48b2ca25f364936b48c8927dc956551c1')
