  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Una línia està formada per 5 mànegues de 45 mm de 20 m. Segons el manual d''hidràulica, quants litres d''aigua aproximadament calen per omplir-la?', 'Una mànega de 45 mm conté uns 1,5 L/m, és a dir, 30 L per tram de 20 m: 5 × 30 = 150 L. 385 L correspondrien a 5 mànegues de 70 mm (77 L cadascuna).', 'bomb_t13_hidraulica_bombes', (select id from public.topics where slug = 'bomb-t13-hidraulica-bombes'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-13-MAN.GRAL.009.pdf'), 'MAN.GRAL.009, § 6.1.2 mànegues de 45 mm', 'Aproximadament hi cap 1,5 litres d’aigua per metre lineal, és a dir, 30 litres d’aigua per cada mànega de 20 metres.', null, '072edc91efc29c81946b93fdf77375fb097fb8e37c9b947f941da8683aef6ae7', false
