with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Una llança es troba 30 m per sobre de la bomba. Segons el manual d''hidràulica, quanta pressió es perd només pel desnivell, sense comptar les pèrdues per fregament?', 'Els desnivells fan variar la pressió a raó d''1 bar per cada 10 m: 30 m → 3 bar.', 'bomb_t13_hidraulica_bombes', (select id from public.topics where slug = 'bomb-t13-hidraulica-bombes'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-13-MAN.GRAL.009.pdf'), 'MAN.GRAL.009, § 4.3 equació de Bernoulli (desnivells)', 'En canvi, el que si ens farà variar molt significativament la pressió són els desnivells, a raó de 1 bar per cada 10 m de desnivell.', null, 'f9f76f403271c760c99df62ab1f73c8d9b410473f573cc88888691e1fb805b29', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'f9f76f403271c760c99df62ab1f73c8d9b410473f573cc88888691e1fb805b29')
  returning id
), o as (
