)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'En un gat hidràulic s''aplica una força de 200 N sobre un èmbol de 2 cm². L''altre èmbol fa 50 cm². Segons el principi de Pascal, quina força s''obté a l''èmbol gran?', 'P = 200 N / 2 cm² = 100 N/cm²; F = 100 N/cm² × 50 cm² = 5.000 N. La força es multiplica per la relació de superfícies (50/2 = 25).', 'bomb_t13_hidraulica_bombes', (select id from public.topics where slug = 'bomb-t13-hidraulica-bombes'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-13-MAN.GRAL.009.pdf'), 'MAN.GRAL.009, § 3.3 principi de Pascal', 'La pressió exercida en un punt qualsevol d’un líquid tancat i en repòs es transmet amb la mateixa intensitat i en totes les direccions a tots els punts del líquid i a les parets del recipient que el conté. […] Hem multiplicat la força per 100, la relació de superfícies dels èmbols.', null, '85a35cce38a746dc1ab3243218b601ca05b81a29c71397cce3fa91f187353c41', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '85a35cce38a746dc1ab3243218b601ca05b81a29c71397cce3fa91f187353c41')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', '200 N.', false), ('B', '8 N.', false), ('C', '5.000 N.', true), ('D', '10.000 N.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Una bomba buida completament un dipòsit de 3.000 litres en 5 minuts. Segons la definició de cabal del manual d''hidràulica, quin cabal mitjà ha impulsat?', 'Q = V / t = 3.000 L / 5 min = 600 l/min (36 m³/h).', 'bomb_t13_hidraulica_bombes', (select id from public.topics where slug = 'bomb-t13-hidraulica-bombes'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-13-MAN.GRAL.009.pdf'), 'MAN.GRAL.009, § 4.2.1 el cabal', 'Q és el cabal, en m3/s V és el volum, en m3 t el temps en segons […] Litre per minut (l/min o lpm)', null, 'd50a1611cc2900cc11058bf95a0b6185364c965fa776558a2e9125bb0f54135f', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'd50a1611cc2900cc11058bf95a0b6185364c965fa776558a2e9125bb0f54135f')
  returning id
), o as (
