)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'En una instal·lació amb mànega de 70 mm cal tancar una vàlvula de bola. Segons el manual d''hidràulica, com s''ha de fer per evitar el cop d''ariet?', 'Les vàlvules de rosca triguen prou a tancar; les de bola s''han de tancar lentament, sobretot amb cabals grans (uns 8 s en 70 mm).', 'bomb_t13_hidraulica_bombes', (select id from public.topics where slug = 'bomb-t13-hidraulica-bombes'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-13-MAN.GRAL.009.pdf'), 'MAN.GRAL.009, § 4.6 cop d''ariet', 'On s’ha de tenir especial cura és en les vàlvules de bola, que hem de ser conscients a tancar-les lenta i progressivament, sobretot com més gran sigui el cabal que circula (uns 8 segons en mànegues de 70 mm).', null, 'f02556bacbc2ab4ca99f46bf2937517d1df359d82222af7537856735d1928d8e', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'f02556bacbc2ab4ca99f46bf2937517d1df359d82222af7537856735d1928d8e')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Lenta i progressivament, uns 8 segons en mànegues de 70 mm.', true), ('B', 'De cop, perquè com més ràpid es tanca menys sobrepressió es genera.', false), ('C', 'Primer aturant la bomba i després obrint la llança del tot.', false), ('D', 'No cal cap precaució, perquè les vàlvules de bola no generen cop d''ariet.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Per fer una aspiració des d''una bassa, per què cal utilitzar manegots i no mànegues flexibles, segons el manual d''hidràulica?', 'Amb pressió relativa negativa les mànegues col·lapsen; els manegots són semirígids (espires d''acer) i s''acoblen amb ràcords Storz, perquè el Barcelona no garanteix l''estanqueïtat en depressió.', 'bomb_t13_hidraulica_bombes', (select id from public.topics where slug = 'bomb-t13-hidraulica-bombes'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-13-MAN.GRAL.009.pdf'), 'MAN.GRAL.009, § 6.2 manegots', 'Les mànegues flexibles només poden treballar amb pressió, ja que si la pressió disminueix per sota l''atmosfèrica (pressió relativa negativa) les mànegues col·lapsen.', null, 'bdaaf9e0600e8a9534680bf34f7d00d29c196da70f03dcaac6a38f5819898ca8', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'bdaaf9e0600e8a9534680bf34f7d00d29c196da70f03dcaac6a38f5819898ca8')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Perquè les mànegues flexibles col·lapsen quan la pressió baixa per sota de l''atmosfèrica.', true), ('B', 'Perquè les mànegues flexibles no suporten pressions superiors a 1 bar.', false), ('C', 'Perquè els manegots porten ràcord Barcelona, que és més estanc en depressió.', false), ('D', 'Perquè els manegots tenen menys diàmetre i augmenten la velocitat de l''aigua.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual d''hidràulica, què cal fer amb un monitor portàtil abans de posar-lo en servei?', 'Per les grans forces de reacció, el monitor portàtil s''ha d''ancorar; a més, no pot treballar per sota d''uns 30-35° respecte a l''horitzontal perquè no llisqui enrere.', 'bomb_t13_hidraulica_bombes', (select id from public.topics where slug = 'bomb-t13-hidraulica-bombes'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-13-MAN.GRAL.009.pdf'), 'MAN.GRAL.009, § 6.3.4 monitors', 'A causa de les grans forces de reacció que es generen, els monitors portàtils han d''estar ancorats a un punt fix o a una estaca abans de posar-los en servei.', null, 'b189516d9d53cdb746859ac804a8d7d9b9b7495d937eabf084f51fd6b0af4cfc', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'b189516d9d53cdb746859ac804a8d7d9b9b7495d937eabf084f51fd6b0af4cfc')
  returning id
), o as (
