)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual d''hidràulica, si el fabricant no indica una altra cosa, a quina pressió es refereix habitualment el cabal nominal d''una llança?', 'Les llances es classifiquen pel cabal nominal, que habitualment es refereix a 6 bar; si la pressió real és superior, el cabal efectiu també ho és.', 'bomb_t13_hidraulica_bombes', (select id from public.topics where slug = 'bomb-t13-hidraulica-bombes'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-13-MAN.GRAL.009.pdf'), 'MAN.GRAL.009, § 6.3.2 reacció del raig (cabal nominal)', 'Si el fabricant no indica una altra cosa, aquest cabal nominal es refereix habitualment a una pressió de 6 bar.', null, 'd1dc9c5104219312c9d526c8d87ab0c74b0573e20948d2aa41c7d07af9628be1', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'd1dc9c5104219312c9d526c8d87ab0c74b0573e20948d2aa41c7d07af9628be1')
  returning id
