)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual d''hidràulica, la pressió atmosfèrica baixa uns 0,129 m.c.a. per cada 100 m d''altitud. Quanta alçada d''aspiració es perd, respecte al nivell del mar, a 2.000 m d''altitud?', '2.000 m / 100 m = 20; 20 × 0,129 = 2,58 m (a 1.000 m serien 1,29 m).', 'bomb_t13_hidraulica_bombes', (select id from public.topics where slug = 'bomb-t13-hidraulica-bombes'), 3, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-13-MAN.GRAL.009.pdf'), 'MAN.GRAL.009, § 4.5.3 aspiració', 'la variació de pressió atmosfèrica amb l’alçada és d’aproximadament 0,129 mca per cada 100 m que pugem, així a 1000 m d’altitud ja hem perdut 1,29 m d’alçada d’aspiració respecte al que podríem aspirar a nivell del mar.', null, '95374aec2e12ab362488a57aee2d64b533863ad22cd6a65f221cb83f4780f3eb', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '95374aec2e12ab362488a57aee2d64b533863ad22cd6a65f221cb83f4780f3eb')
  returning id
), o as (
