  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Uns 1,29 m.', false), ('B', 'Uns 2,58 m.', true), ('C', 'Uns 0,26 m.', false), ('D', 'Uns 25,8 m.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'En una mateixa instal·lació de mànegues es duplica el cabal. Segons el manual d''hidràulica, com varien aproximadament les pèrdues de càrrega?', 'Les pèrdues de càrrega són proporcionals a la longitud i al quadrat de la velocitat (i del cabal): 2² = 4.', 'bomb_t13_hidraulica_bombes', (select id from public.topics where slug = 'bomb-t13-hidraulica-bombes'), 3, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-13-MAN.GRAL.009.pdf'), 'MAN.GRAL.009, § 4.4 pèrdues de càrrega', 'Són directament proporcionals al quadrat de la velocitat, és a dir, directament proporcionals al quadrat del cabal.', null, '218d6aec17509c138bc8fd5344d2643c370c6debfda4027321d497146ec2e7d7', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '218d6aec17509c138bc8fd5344d2643c370c6debfda4027321d497146ec2e7d7')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Es dupliquen, perquè són proporcionals al cabal.', false), ('B', 'Es multipliquen per 4, perquè són proporcionals al quadrat del cabal.', true), ('C', 'Es redueixen a la meitat.', false), ('D', 'No varien, perquè només depenen de la longitud.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'A 8 bar, una mànega de 45 mm per la qual circulen 700 l/min té una pèrdua de càrrega de gairebé 1,8 bar. Segons el manual d''hidràulica, quina pèrdua per fregament tindrà una línia de 5 d''aquestes mànegues en sèrie amb el mateix cabal?', 'En sèrie, la pèrdua total és la suma de les de cada mànega: 5 × 1,8 ≈ 9 bar. Amb mànegues de 70 mm la pèrdua per tram seria de poc més de 0,2 bar.', 'bomb_t13_hidraulica_bombes', (select id from public.topics where slug = 'bomb-t13-hidraulica-bombes'), 3, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-13-MAN.GRAL.009.pdf'), 'MAN.GRAL.009, § 4.4 pèrdues de càrrega en mànegues', 'Quan connectem mànegues una darrera l’altre, les estem posant en sèrie, la pèrdua de càrrega total és la suma de les pèrdua de càrrega en cada una d’elles. […] a 8 bar, si volem fer circular un cabal de 700 l/min, en una mànega de 45 mm tenim una pèrdua de càrrega per mànega de gairebé 1,8 bar', null, '293503454fe3bce988888780c51729fd63ff884336bc6b5083be0f6be81c0bea', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '293503454fe3bce988888780c51729fd63ff884336bc6b5083be0f6be81c0bea')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Gairebé 1,8 bar.', false), ('B', 'Gairebé 3,6 bar.', false), ('C', 'Gairebé 0,36 bar.', false), ('D', 'Gairebé 9 bar.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual d''hidràulica, si en una mateixa instal·lació s''augmenta la velocitat de gir de la bomba (de 2.400 a 2.800 rpm), què passa amb el punt de funcionament?', 'El punt de funcionament és la intersecció entre la corba de la bomba i la corba resistent de la instal·lació; en l''exemple del manual (instal·lació amb 100 m de desnivell) passa de 22 bar i 270 l/min a 2.400 rpm a 26 bar i 325 l/min a 2.800 rpm.', 'bomb_t13_hidraulica_bombes', (select id from public.topics where slug = 'bomb-t13-hidraulica-bombes'), 3, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-13-MAN.GRAL.009.pdf'), 'MAN.GRAL.009, § 5.3.4 punt de funcionament', 'El punt de funcionament és la intersecció entre la corba característica de la bomba i la corba resistent de la instal·lació. […] No només hem augmentat la pressió, també augmenta el cabal.', null, '50236f74fca2f9a3e39aa97e7fb386cf133f3a8fb323f7444afd6dc6018d8235', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '50236f74fca2f9a3e39aa97e7fb386cf133f3a8fb323f7444afd6dc6018d8235')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
