with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual d''hidràulica, què interessa sobretot d''un hidrant per abastir les autobombes?', 'La pressió ja la donen les bombes dels vehicles; un hidrant amb més de 5 bar en estàtic pot no donar més de 500 l/min si les pèrdues de càrrega de la seva canonada són grans.', 'bomb_t13_hidraulica_bombes', (select id from public.topics where slug = 'bomb-t13-hidraulica-bombes'), 3, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-13-MAN.GRAL.009.pdf'), 'MAN.GRAL.009, § 5.3.2 corba característica d''un hidrant', 'D’un hidrant ens interessa sobretot la seva capacitat de proveir cabal, la pressió no ens interessa tant ja que l’aconseguirem amb les nostres bombes. Així, a priori, un hidrant que ens doni molta pressió en estàtic no implica que sigui un bon hidrant.', null, '1b01091c2106a906204123be6ff0de37d631582147af5021328a70a1bd48e7e8', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '1b01091c2106a906204123be6ff0de37d631582147af5021328a70a1bd48e7e8')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La pressió estàtica: com més pressió dona tancat, millor és l''hidrant.', false), ('B', 'Que tingui diverses corbes segons la velocitat de gir.', false), ('C', 'La seva capacitat de proveir cabal; molta pressió en estàtic no implica que sigui un bon hidrant.', true), ('D', 'Que doni exactament 6 bar, la pressió nominal de les llances.', false)) as v(label, body, ok)
)
