with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual de cartografia, les corbes de nivell (isohipses) són línies imaginàries que connecten els punts del terreny que tenen:', 'Una corba de nivell uneix punts d''igual altitud; la separació vertical entre corbes és l''equidistància.', 'bomb_t14_cartografia_orientacio', (select id from public.topics where slug = 'bomb-t14-cartografia-orientacio'), 1, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-14-MAN.GRAL.002.pdf'), 'MAN.GRAL.002, § corbes de nivell', 'Corbes de nivell Les corbes de nivell (o isohipses) són les línies imaginaries que connecten tots els punts de la superfície del terreny que tenen la mateixa cota o altitud sobre el nivell del mar.', null, '7df90674eb39973994190cddecc2093e63b2ca21f286339892c28e87b32df37f', false
