  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual de cartografia, en quina zona UTM es troba tot el territori de Catalunya?', 'Tot Catalunya és dins la 31T i normalment no cal especificar-la; la resta de la Península abasta els fusos 29, 30 i 31.', 'bomb_t14_cartografia_orientacio', (select id from public.topics where slug = 'bomb-t14-cartografia-orientacio'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-14-MAN.GRAL.002.pdf'), 'MAN.GRAL.002, § zona 31T', 'A Catalunya això és més senzill perquè tot el territori es troba dins la zona 31T, i per tant normalment no cal especificar-la, mentre que a la resta de la Península Ibèrica sí, ja que hi ha tres fusos diferents (29, 30 i 31).', null, '08d8a4e5fcf27bd0b400837762071884257dbedc4e1d6029070d0da74093e938', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '08d8a4e5fcf27bd0b400837762071884257dbedc4e1d6029070d0da74093e938')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'A la zona 31T.', true), ('B', 'A la zona 30T.', false), ('C', 'A la zona 29T.', false), ('D', 'Una part a la 30T i una altra a la 31T.', false)) as v(label, body, ok)
)
