with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual de cartografia, com s''anomena la corba de nivell dibuixada amb un traç més gruixut, generalment cada 5 corbes?', 'La corba mestra es dibuixa més gruixuda per facilitar la lectura i el recompte de corbes.', 'bomb_t14_cartografia_orientacio', (select id from public.topics where slug = 'bomb-t14-cartografia-orientacio'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-14-MAN.GRAL.002.pdf'), 'MAN.GRAL.002, § corba mestra', 'Cada cert numero de corbes (generalment cada 5 corbes) es dibuixa la corba amb un traç més gruixut, és l’anomenada corba mestra, per facilitar la lectura del mapa i el recompte de corbes.', null, 'a7932bd918d40f4bd637ee18ff1468ed7f384c83edf8b35f22417f2b2c0e42f3', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'a7932bd918d40f4bd637ee18ff1468ed7f384c83edf8b35f22417f2b2c0e42f3')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Corba auxiliar.', false), ('B', 'Corba d''equidistància.', false), ('C', 'Corba mestra.', true), ('D', 'Isòbata.', false)) as v(label, body, ok)
)
