with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual de cartografia, quin és el gran avantatge de l''escala gràfica respecte a la numèrica?', 'En una fotocòpia o en un mapa digital ampliat, l''escala gràfica canvia de mida amb el mapa; la numèrica deixaria de ser vàlida.', 'bomb_t14_cartografia_orientacio', (select id from public.topics where slug = 'bomb-t14-cartografia-orientacio'), 3, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-14-MAN.GRAL.002.pdf'), 'MAN.GRAL.002, § escala gràfica', 'El gran avantatge de l''escala gràfica és que si el mapa s''amplia o es redueix (per exemple, en una fotocòpia, un mapa digital), l''escala gràfica es redimensiona amb ell, mantenint la seva relació amb la realitat.', null, '191fc6209872738db481a8906f0b5837de914efdf50afb5122116f7d45d5b992', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '191fc6209872738db481a8906f0b5837de914efdf50afb5122116f7d45d5b992')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Que permet calcular l''altitud de qualsevol punt sense corbes de nivell.', false), ('B', 'Que es redimensiona amb el mapa si aquest s''amplia o es redueix, i manté la relació amb la realitat.', true), ('C', 'Que corregeix automàticament la declinació magnètica.', false), ('D', 'Que és més precisa que l''escala numèrica en qualsevol circumstància.', false)) as v(label, body, ok)
)
