with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual de cartografia, sobre la diferència entre el Nord magnètic i el Nord geogràfic, és correcte afirmar que:', 'El Nord magnètic no coincideix amb el geogràfic; la desviació varia segons lloc i any i el mapa l''ha d''indicar.', 'bomb_t14_cartografia_orientacio', (select id from public.topics where slug = 'bomb-t14-cartografia-orientacio'), 3, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-14-MAN.GRAL.002.pdf'), 'MAN.GRAL.002, § declinació magnètica', 'Tinguem en compte que el Nord magnètic no coincideix exactament amb el Nord geogràfic, hi ha una petita desviació que varia amb el lloc i amb els anys, per això ha de venir indicada en el mapa.', null, 'af66a11aa1fda2dbaad27c105729c1bddaf0d7e1183e46f916f823ef9b689708', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'af66a11aa1fda2dbaad27c105729c1bddaf0d7e1183e46f916f823ef9b689708')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'És constant a tot el planeta i no cal indicar-la.', false), ('B', 'Només existeix a l''hemisferi sud.', false), ('C', 'Depèn de l''escala del mapa.', false), ('D', 'Varia amb el lloc i amb els anys i, per això, ha de venir indicada en el mapa.', true)) as v(label, body, ok)
)
