  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual de cartografia, quina estrella resta fixa al firmament i assenyala directament el nord geogràfic?', 'Totes les estrelles es mouen pel firmament excepte la Polar, que assenyala el nord geogràfic; l''Ossa Major i Cassiopea només serveixen per localitzar-la.', 'bomb_t14_cartografia_orientacio', (select id from public.topics where slug = 'bomb-t14-cartografia-orientacio'), 1, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-14-MAN.GRAL.002.pdf'), 'MAN.GRAL.002, § 3.2.3 Orientació a partir dels estels', 'Només una estrella resta fixa en un punt sense moure''s: l''estrella Polar, que assenyala directament cap al nord geogràfic.', null, '485a043d63025490bcfecd486d6d560ce54dc0e9fec32959f1ecbec419b92471', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '485a043d63025490bcfecd486d6d560ce54dc0e9fec32959f1ecbec419b92471')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
