with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual de cartografia, si a les 12:00 h hora solar clavem una estaca a terra, la seva ombra assenyala:', 'A les 12:00 h solars el sol és exactament sobre el sud, de manera que l''ombra apunta en sentit contrari: cap al nord.', 'bomb_t14_cartografia_orientacio', (select id from public.topics where slug = 'bomb-t14-cartografia-orientacio'), 1, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-14-MAN.GRAL.002.pdf'), 'MAN.GRAL.002, § 3.2.1 Posició del sol a determinades hores', 'a les 12:00 h del migdia hora solar, el sol es troba exactament a sobre del punt cardinal sud. Si en aquest moment clavéssim una estaca a terra, l’ombra de l’estaca assenyalaria directament cap al nord.', null, 'edb4d7b1667bc371a3d6d51e73baa70233d26c91a2bdc9c38ac2cda2c67ed40a', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'edb4d7b1667bc371a3d6d51e73baa70233d26c91a2bdc9c38ac2cda2c67ed40a')
  returning id
