with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual de cartografia, si ens donen la coordenada UTM (4594842, 425888) d''un punt de Catalunya, què hem de deduir?', 'A Catalunya la X té 6 xifres i la Y en té 7; aquí el primer valor en té 7 i el segon 6, per tant s''han intercanviat.', 'bomb_t14_cartografia_orientacio', (select id from public.topics where slug = 'bomb-t14-cartografia-orientacio'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-14-MAN.GRAL.002.pdf'), 'MAN.GRAL.002, § 2.2.2 Xifres de les coordenades UTM', 'A més, les coordenades UTM a Catalunya tenen sempre 6 xifres per a la X i 7 per a la Y […] (4594842, 425888) probablement està en metres i ens han donat Y i X girades.', null, '909d0d3131c787719f2af5419e0e7ccdc5e364c141045d737fa8744b7ee5f841', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '909d0d3131c787719f2af5419e0e7ccdc5e364c141045d737fa8744b7ee5f841')
  returning id
