)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual de cartografia, com indica la lletra de la zona UTM que un punt és a l''hemisferi nord?', 'La lletra de la zona permet saber l''hemisferi: a partir de la N (de Nord) és hemisferi nord. Les lletres I i O s''exclouen per no confondre-les amb números.', 'bomb_t14_cartografia_orientacio', (select id from public.topics where slug = 'bomb-t14-cartografia-orientacio'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-14-MAN.GRAL.002.pdf'), 'MAN.GRAL.002, § 2.2.2 Zones UTM', 'La zona ens serveix per saber si estem a l’hemisferi nord o al sud, hem de saber que a partir de la lletra N són zones de l’hemisferi nord (N de Nord).', null, '62896303ac825f331cc5e5048d70c84d47cb90adadf70513efc5cf17d590343b', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '62896303ac825f331cc5e5048d70c84d47cb90adadf70513efc5cf17d590343b')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Les zones de la lletra C a la M són de l''hemisferi nord.', false), ('B', 'Les zones identificades amb les lletres I i O són de l''hemisferi nord.', false), ('C', 'Les zones a partir de la lletra N són de l''hemisferi nord.', true), ('D', 'La lletra no ho indica; només ho indica el número del fus.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual de cartografia, com creuen les corbes de nivell els cursos d''aigua naturals?', 'Els rius i rierols creuen les corbes perpendicularment seguint el màxim pendent; és un camí o carretera paral·lel a una corba el que no guanya ni perd alçada. Els canals artificials no segueixen aquesta regla.', 'bomb_t14_cartografia_orientacio', (select id from public.topics where slug = 'bomb-t14-cartografia-orientacio'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-14-MAN.GRAL.002.pdf'), 'MAN.GRAL.002, § 2.3.3 Interpretació de les corbes de nivell', 'Els cursos d’aigua naturals creuen les corbes de nivell perpendicularment ja que l’aigua segueix la línia de màxim pendent (els canals artificials no).', null, '526d03e23f6b5f02bff99aa0964af83aac9aa1acaae1a424f0e0a01f141809ff', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '526d03e23f6b5f02bff99aa0964af83aac9aa1acaae1a424f0e0a01f141809ff')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Perpendicularment, perquè l''aigua segueix la línia de màxim pendent.', true), ('B', 'Paral·lelament, perquè l''aigua no guanya ni perd alçada.', false), ('C', 'Sempre en diagonal, formant un angle de 45º.', false), ('D', 'No les creuen mai, perquè discorren per les carenes.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual de cartografia, per localitzar una columna de fum per triangulació, quants observadors calen com a mínim?', 'La posició de l''objectiu és el punt on es creuen les visuals (azimuts) de diversos observadors; amb dos ja n''hi ha prou, però més observadors donen més precisió.', 'bomb_t14_cartografia_orientacio', (select id from public.topics where slug = 'bomb-t14-cartografia-orientacio'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-14-MAN.GRAL.002.pdf'), 'MAN.GRAL.002, § 3.1.1 Triangulació', 'Amb un mínim de dos observadors es pot triangular, però com més observadors hi participin, més precís serà el resultat.', null, '6a57be9a9b0110a7ab2090fffc6274ca91e31c82c4c77b45d97f6653bff91f29', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '6a57be9a9b0110a7ab2090fffc6274ca91e31c82c4c77b45d97f6653bff91f29')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Un de sol, si disposa d''una brúixola amb limbe.', false), ('B', 'Dos, prou separats entre si; com més n''hi hagi, més precís serà el resultat.', true), ('C', 'Tres, perquè amb menys les visuals no es poden creuar.', false), ('D', 'Quatre, com en el càlcul de la posició en 3D del GNSS.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual de cartografia, de quants satèl·lits com a mínim ha de rebre senyal un receptor GNSS per calcular una posició en 3D?', 'La posició es calcula per trilateració a partir del temps que tarda el senyal de diversos satèl·lits, com a mínim quatre per a una posició en 3D.', 'bomb_t14_cartografia_orientacio', (select id from public.topics where slug = 'bomb-t14-cartografia-orientacio'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-14-MAN.GRAL.002.pdf'), 'MAN.GRAL.002, § 4.1 Principis de funcionament del GNSS', 'El càlcul de la posició es fa per trilateració (com la triangulació però amb distàncies), a partir del temps que tarda el senyal de ràdio a viatjar des de diversos satèl·lits (un mínim de quatre per a una posició en 3D) fins al receptor.', null, '4c33e6751dd930cba4a3f4248c70ad2bf5f0a6d01500f4e838b8cdb63232da66', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '4c33e6751dd930cba4a3f4248c70ad2bf5f0a6d01500f4e838b8cdb63232da66')
  returning id
