with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual de cartografia, amb un rellotge de manetes ajustat a l''hora solar, horitzontal i amb la maneta de les hores apuntant al Sol, què assenyala el sud?', 'La bisectriu (línia que divideix l''angle en dues meitats iguals) entre la maneta de les hores i el 12 apunta cap al sud.', 'bomb_t14_cartografia_orientacio', (select id from public.topics where slug = 'bomb-t14-cartografia-orientacio'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-14-MAN.GRAL.002.pdf'), 'MAN.GRAL.002, § 3.2.2 Orientació amb un rellotge de manetes', 'La bisectriu (línia que divideix un angle en dues meitats iguals) que formen la maneta de les hores amb la xifra 12 del rellotge assenyala cap al Sud.', null, '6f9281196da363304948e67b9eb7909d5361755179fbdc53d133ac8dc45145d9', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '6f9281196da363304948e67b9eb7909d5361755179fbdc53d133ac8dc45145d9')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La bisectriu de l''angle que formen la maneta de les hores i la xifra 12.', true), ('B', 'La maneta dels minuts.', false), ('C', 'La xifra 12 del rellotge.', false), ('D', 'La prolongació de la maneta de les hores en sentit contrari al Sol.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
