with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Dos punts de Catalunya tenen les coordenades UTM, en metres, A (430000, 4600000) i B (433000, 4604000). Quina distància en línia recta els separa?', 'ΔX = 433.000 − 430.000 = 3.000 m i ΔY = 4.604.000 − 4.600.000 = 4.000 m. Per Pitàgores: √(3.000² + 4.000²) = √25.000.000 = 5.000 m. 7.000 m seria sumar les dues diferències.', 'bomb_t14_cartografia_orientacio', (select id from public.topics where slug = 'bomb-t14-cartografia-orientacio'), 3, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-14-MAN.GRAL.002.pdf'), 'MAN.GRAL.002, § 2.2.2 Càlcul de distàncies en UTM', 'Com que el sistema és una quadrícula en metres, és molt fàcil fer-hi càlculs de distància amb operacions senzilles o amb el teorema de Pitàgores.', null, '73d22a2d5e20a300e2844b5919abc45349f7ea5eca78b13bec28a2cfc80c810b', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '73d22a2d5e20a300e2844b5919abc45349f7ea5eca78b13bec28a2cfc80c810b')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', '7.000 m.', false), ('B', '1.000 m.', false), ('C', '5.000 m.', true), ('D', '3.500 m.', false)) as v(label, body, ok)
)
