with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'El 10 de gener el rellotge marca les 13:00 h (hora oficial). Segons el manual de cartografia, on es troba el sol en aquell moment?', 'El 10 de gener és horari d''hivern: hora solar = 13:00 − 1 h = 12:00 h, i a les 12:00 h solars el sol és exactament sobre el sud.', 'bomb_t14_cartografia_orientacio', (select id from public.topics where slug = 'bomb-t14-cartografia-orientacio'), 3, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-14-MAN.GRAL.002.pdf'), 'MAN.GRAL.002, § 3.2.1 Hora oficial i hora solar', 'Durant l’horari d’hivern cal restar-li una hora. […] l’horari d’estiu és el vigent a partir de l’últim diumenge de març i durant tots els mesos següents fins arribar a l’últim diumenge d’octubre […] a les 12:00 h del migdia hora solar, el sol es troba exactament a sobre del punt cardinal sud.', null, '6edca0dfa362673141a552997f2d214ec939e2798505735937655b6fe1355452', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '6edca0dfa362673141a552997f2d214ec939e2798505735937655b6fe1355452')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Al sud-est, perquè són les 9:00 h hora solar.', false), ('B', 'Al sud-oest, perquè són les 15:00 h hora solar.', false), ('C', 'A l''est, perquè són les 6:00 h hora solar.', false), ('D', 'Exactament al sud, perquè són les 12:00 h hora solar.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual de cartografia, quines característiques han de complir els punts d''aigua de la xarxa bàsica per a incendis forestals (PAIF)?', 'Els PAIF han de superar els 200 m³ (o els 120 m³ de l''antic criteri), ser accessibles per mitjans aeris i terrestres i tenir mecanismes de manteniment. Qualsevol lloc on omplir el camió és un punt d''aigua, però no necessàriament un PAIF.', 'bomb_t14_cartografia_orientacio', (select id from public.topics where slug = 'bomb-t14-cartografia-orientacio'), 3, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-14-MAN.GRAL.002.pdf'), 'MAN.GRAL.002, § 5.2.2 Punts d''aigua (PAIF)', 'Una capacitat superior als 200 metres cúbics […] Accessibles per mitjans aeris (helicòpters) i per mitjans terrestres d’extinció d’incendis forestals.', null, '1a94b873af744f31a1a491c695004d95d23b87ff66dc2bee3e8fcac749217660', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '1a94b873af744f31a1a491c695004d95d23b87ff66dc2bee3e8fcac749217660')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Capacitat superior a 200 m³, però accessibles només per a mitjans terrestres.', false), ('B', 'Capacitat superior a 20 m³ i ús exclusivament públic.', false), ('C', 'Capacitat superior a 200 m³ i accessibilitat per a helicòpters i per a mitjans terrestres d''extinció.', true), ('D', 'Qualsevol bassa o piscina on es pugui omplir el camió, sense requisit de capacitat.', false)) as v(label, body, ok)
)
