with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual de cartografia, en el codi SOC 28BJ09, què identifica la part «09»?', 'El quadrant (5 × 5 km) es codifica amb dos números i dues lletres (28BJ); cada quadrant es divideix en 25 seccions d''1 × 1 km numerades de l''1 al 25, i 09 n''és la secció.', 'bomb_t14_cartografia_orientacio', (select id from public.topics where slug = 'bomb-t14-cartografia-orientacio'), 3, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-14-MAN.GRAL.002.pdf'), 'MAN.GRAL.002, § 5.3.2 El codi SOC', 'El quadrant identifica un reticle de 5×5 km i utilitza una combinació de dos números i dues lletres. […] Cada quadrant se subdivideix en 25 quadrats d’1x1 km anomenats seccions, numerats de l’1 al 25 (d’oest a est i de nord a sud).', null, '23306668928748fa1d42f29e498993bc6564caa18690b19406debce0966c5af6', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '23306668928748fa1d42f29e498993bc6564caa18690b19406debce0966c5af6')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Una secció d''1 × 1 km dins del quadrant de 5 × 5 km.', true), ('B', 'Un quadrant de 5 × 5 km.', false), ('C', 'El full del mapa MTN 1:25.000.', false), ('D', 'La coordenada UTM X en quilòmetres.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual de cartografia, sobre les referències aproximatives d''orientació, indica la resposta INCORRECTA:', 'Els panells solars de les carreteres estan gairebé sempre orientats cap al sud, no cap al nord; la resta d''afirmacions són les que recull el manual.', 'bomb_t14_cartografia_orientacio', (select id from public.topics where slug = 'bomb-t14-cartografia-orientacio'), 3, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-14-MAN.GRAL.002.pdf'), 'MAN.GRAL.002, § 3.3 Altres referències aproximatives d''orientació', 'La molsa creixerà en les zones més ombrívoles i humides d’un tronc (normalment cap al Nord). […] els anells de creixement solen estar més junts i atapeïts cap al cantó que li tocava menys el sol (normalment cap al Nord). […] la zona on va l’altar quedi assenyalant cap al lloc on surt el sol (cap a l’Est). […] Aquests panells solars estan gairebé sempre orientats cap al sud.', null, 'beb536de38c5ffa92ceec396c965fde5be1325e647ee30ec752258ce1226dfeb', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'beb536de38c5ffa92ceec396c965fde5be1325e647ee30ec752258ce1226dfeb')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La molsa creix a les zones més ombrívoles i humides del tronc, normalment cap al nord.', false), ('B', 'Les plaques solars de les carreteres estan gairebé sempre orientades cap al nord.', true), ('C', 'L''altar de les esglésies i ermites cristianes acostuma a assenyalar cap a l''est.', false), ('D', 'Els anells de creixement de les soques solen estar més junts cap al cantó menys assolellat, normalment el nord.', false)) as v(label, body, ok)
)
