  select 'Segons el Manual operatiu bàsic de construcció, la tracció és l''esforç que:', 'Tracció = estirar; compressió = aixafar; torsió = retorçar; tallant = lliscar.', 'bomb_t15_construccio', (select id from public.topics where slug = 'bomb-t15-construccio'), 1, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.GRAL.006-Tema-15.-Manual-Op.-basic-construccio.pdf'), 'MAN.GRAL.006, § tracció', 'Tracció La tracció és l’esforç que estira un element.', null, '46d7d75e1d0327283106e4c52a98b4b8f652d917e0c252fbc1c423c0c15c850e', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '46d7d75e1d0327283106e4c52a98b4b8f652d917e0c252fbc1c423c0c15c850e')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Estira un element.', true), ('B', 'Aixafa un element.', false), ('C', 'Tendeix a retorçar un element.', false), ('D', 'Vol fer lliscar una part de l''element respecte a l''altra.', false)) as v(label, body, ok)
)
