  select 'Segons el manual de construcció, la flexió és:', 'La flexió combina compressió i tracció; hi treballen la majoria de bigues, jàsseres i mènsules.', 'bomb_t15_construccio', (select id from public.topics where slug = 'bomb-t15-construccio'), 1, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.GRAL.006-Tema-15.-Manual-Op.-basic-construccio.pdf'), 'MAN.GRAL.006, § flexió', 'Flexió La flexió és la combinació de compressió i tracció en una peça que es corba.', null, '4fa3790b6106caf44c26d9aa12ac4f0ee178349f65a2aed5ee0e8b7146f45b44', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '4fa3790b6106caf44c26d9aa12ac4f0ee178349f65a2aed5ee0e8b7146f45b44')
