  select 'Segons el manual de construcció, quin tipus de fonamentació s''utilitza quan les càrregues es concentren en punts concrets, generalment pilars aïllats?', 'Cada pilar descansa sobre una sabata independent; són habituals en edificis de pilars i forjats. Les sabates corregudes reparteixen càrregues lineals de murs.', 'bomb_t15_construccio', (select id from public.topics where slug = 'bomb-t15-construccio'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.GRAL.006-Tema-15.-Manual-Op.-basic-construccio.pdf'), 'MAN.GRAL.006, § 4.1.1 Sabatilles aïllades', 'S’utilitzen quan les càrregues de l’edifici es concentren en punts concrets, generalment pilars aïllats. Cada pilar descansa sobre una sabata independent que reparteix el pes al terreny.', null, 'b26d4eaa930553b11d46affa1979e43df32a3a2e9c1a533fa9c009a76acb5b4f', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'b26d4eaa930553b11d46affa1979e43df32a3a2e9c1a533fa9c009a76acb5b4f')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Les sabatilles aïllades.', true), ('B', 'Les sabates corregudes.', false), ('C', 'Els murs de contenció.', false), ('D', 'Les bigues de lligam.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual de construcció, quina funció tenen els encepats i les bigues de lligam?', 'Uneixen sabates o pilots i milloren la rigidesa global de la fonamentació; transmetre a capes profundes és funció dels pilots i retenir terres, dels murs de contenció.', 'bomb_t15_construccio', (select id from public.topics where slug = 'bomb-t15-construccio'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.GRAL.006-Tema-15.-Manual-Op.-basic-construccio.pdf'), 'MAN.GRAL.006, § 4.1.4 Encepats i bigues de lligam', 'Sistema utilitzat per unir diverses sabates o pilots entre sí, millorant la rigidesa global de la fonamentació. Les bigues de lligam ajuden a compensar moviments del terreny i esforços horitzontals.', null, '3f6a14411d45c50b3c25edfb7ae6f5f1b7afb2eca7e782ce6ebf985365b58868', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '3f6a14411d45c50b3c25edfb7ae6f5f1b7afb2eca7e782ce6ebf985365b58868')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Transmetre les càrregues a capes profundes del subsòl.', false), ('B', 'Formar els sostres i paviments de cada planta.', false), ('C', 'Retenir terres i sostenir soterranis.', false), ('D', 'Unir diverses sabates o pilots i ajudar a compensar moviments del terreny i esforços horitzontals.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual de construcció, quin risc poden presentar les pilastres en una intervenció?', 'Les pilastres són petits reforços verticals, habituals en edificació antiga i reformes, que no sempre formen part de l''estructura original.', 'bomb_t15_construccio', (select id from public.topics where slug = 'bomb-t15-construccio'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.GRAL.006-Tema-15.-Manual-Op.-basic-construccio.pdf'), 'MAN.GRAL.006, § 4.2.4 Pilastres', 'No sempre formen part del sistema estructural original. […] Poden estar degradades o desenganxades del mur. […] Falsejar la seva funció pot donar una falsa sensació de seguretat.', null, '79c0cf7c608a1b6502bd8097e13aacf40a2923206c5fdde871d48c16bd7ab466', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '79c0cf7c608a1b6502bd8097e13aacf40a2923206c5fdde871d48c16bd7ab466')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Són sempre l''element principal del sistema estructural original.', false), ('B', 'Concentren tota la càrrega dels forjats com un pilar de formigó armat.', false), ('C', 'Poden estar degradades o desenganxades del mur i donar una falsa sensació de seguretat.', true), ('D', 'No es troben mai en edificació antiga ni en reformes.', false)) as v(label, body, ok)
)
