with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual de construcció, a quin esforç treballen bàsicament la major part de les bigues, les jàsseres i les mènsules (balcons)?', 'Les bigues, jàsseres i mènsules treballen bàsicament a flexió; la compressió apareix a pilars, parets de càrrega i fonaments, i la torsió en pals o elements asimètrics.', 'bomb_t15_construccio', (select id from public.topics where slug = 'bomb-t15-construccio'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.GRAL.006-Tema-15.-Manual-Op.-basic-construccio.pdf'), 'MAN.GRAL.006, § 2.4.3 Flexió', 'La major part de les bigues, jàsseres i mènsules (balcons) treballen bàsicament a flexió.', null, '86bb60d462837fe60d34584a0112f379370e1085b42f907da4033543aff6365d', false
