with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'En un incendi en un edifici de finals del segle XIX amb forjats de bigues d''acer i revoltons ceràmics, quin risc destaca el manual de construcció?', 'Els forjats metàl·lics (bigues d''acer amb revoltons ceràmics), habituals als segles XIX i XX, es dilaten amb la calor i poden provocar despreniments de sostres.', 'bomb_t15_construccio', (select id from public.topics where slug = 'bomb-t15-construccio'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.GRAL.006-Tema-15.-Manual-Op.-basic-construccio.pdf'), 'MAN.GRAL.006, § 4.3.1 Forjats de metall', 'Forjats de metall (bigues d’acer amb revoltons ceràmics): habituals en edificis del segle XIX i XX. El metall es dilata amb la calor i pot provocar despreniments de sostres.', null, '3b2bd7ce58bf413707fdf7bedeb7c3436ace4e99927fbeb5e7de083086616478', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '3b2bd7ce58bf413707fdf7bedeb7c3436ace4e99927fbeb5e7de083086616478')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
