with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'En un bloc d''habitatges dels anys 80 construït amb el sistema de pilars i forjats, quina funció tenen les façanes i els envans segons el manual de construcció?', 'En el sistema porticat l''esquelet resistent el formen pilars i jàsseres; façanes i envans no tenen funció estructural, a diferència del sistema tradicional de murs de càrrega.', 'bomb_t15_construccio', (select id from public.topics where slug = 'bomb-t15-construccio'), 3, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.GRAL.006-Tema-15.-Manual-Op.-basic-construccio.pdf'), 'MAN.GRAL.006, § 5.5.2 Sistema de pilars i forjats', 'aquí l’esquelet resistent està format per pilars i jàsseres, mentre que els tancaments (façanes i envans) no tenen funció estructural.', null, 'f121aff2b42aea2a23ad6f64b2a8af1a16d23c2701d2da44f094dcaf1a2a72f9', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'f121aff2b42aea2a23ad6f64b2a8af1a16d23c2701d2da44f094dcaf1a2a72f9')
  returning id
), o as (
