with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'En un edifici antic de murs de càrrega on, en una reforma, s''ha obert una gran obertura en un mur, què cal tenir present segons el manual de construcció?', 'En el sistema tradicional els murs són portants; tallar-los compromet l''estabilitat, i les estructures de fusta encara n''augmenten la vulnerabilitat en incendi.', 'bomb_t15_construccio', (select id from public.topics where slug = 'bomb-t15-construccio'), 3, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.GRAL.006-Tema-15.-Manual-Op.-basic-construccio.pdf'), 'MAN.GRAL.006, § 5.4.1 i 5.5.1 Sistema tradicional', 'qualsevol obertura o tall en un mur de càrrega afecta directament l’estabilitat global. […] aquest sistema no tolera bé l’eliminació o degradació de cap element portador.', null, '88e8661c85f8ba473915c791e4df8c6f53c670c449d0acfb161995dfc064e6a3', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '88e8661c85f8ba473915c791e4df8c6f53c670c449d0acfb161995dfc064e6a3')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Que qualsevol obertura o tall en un mur de càrrega afecta directament l''estabilitat global, perquè el sistema no tolera bé l''eliminació d''elements portadors.', true), ('B', 'Que no afecta l''estabilitat, perquè les càrregues les porten els pilars.', false), ('C', 'Que només afecta el confort tèrmic, perquè els murs són tancaments.', false), ('D', 'Que el risc desapareix si els forjats són de bigues de fusta.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual de construcció, quin és el risc principal dels pòrtics d''elements prefabricats de formigó?', 'Els prefabricats de formigó són robustos i resisteixen bé el foc, però el pes elevat fa molt greu la fallada d''un recolzament o unió; la pèrdua ràpida de resistència és pròpia dels pòrtics metàl·lics.', 'bomb_t15_construccio', (select id from public.topics where slug = 'bomb-t15-construccio'), 3, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.GRAL.006-Tema-15.-Manual-Op.-basic-construccio.pdf'), 'MAN.GRAL.006, § 5.4.2 Pòrtics prefabricats de formigó', 'Pòrtics d’elements prefabricats de formigó: molt robustos i duradors. Ofereixen bona resistència al foc, però el pes elevat pot generar col·lapses molt greus si falla algun punt crític com els recolzaments o les unions.', null, '74e579d6b22a76fad33b94dcebc5f4a0091acab88d80ed7b6a5bf9e37148bd30', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '74e579d6b22a76fad33b94dcebc5f4a0091acab88d80ed7b6a5bf9e37148bd30')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'L''acer hi perd resistència amb molta rapidesa i provoca col·lapses sobtats.', false), ('B', 'Són molt lleugers i el vent els pot desplaçar fàcilment.', false), ('C', 'Tenen una resistència al foc molt baixa i cremen ràpidament.', false), ('D', 'Tot i la bona resistència al foc, el seu pes elevat pot generar col·lapses molt greus si fallen els recolzaments o les unions.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual de construcció, sobre els elements no estructurals, indica la resposta INCORRECTA:', 'Encara que no tinguin funció resistent, poden caure o desprendre''s i suposar un perill per als intervinents i les víctimes; per això l''afirmació és falsa.', 'bomb_t15_construccio', (select id from public.topics where slug = 'bomb-t15-construccio'), 3, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.GRAL.006-Tema-15.-Manual-Op.-basic-construccio.pdf'), 'MAN.GRAL.006, § 4.4 Elements no estructurals', 'Els elements no estructurals poden caure, desprendre’s o col·lapsar parcialment sense afectar l’estructura principal, però tot i així poden suposar un perill per als intervinents i les víctimes. A més, en alguns casos, poden ocultar patologies estructurals o dificultar la seva detecció. […] Divisions interiors: com envans i falsos sostres', null, '7aed50bd5e1d404407a87c680992b578c9525e9d49cb0409c952aa4af7cf3f34', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '7aed50bd5e1d404407a87c680992b578c9525e9d49cb0409c952aa4af7cf3f34')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Poden caure o desprendre''s sense afectar l''estructura principal.', false), ('B', 'Com que no sostenen càrregues, no suposen cap perill per als intervinents.', true), ('C', 'En alguns casos poden ocultar patologies estructurals o dificultar-ne la detecció.', false), ('D', 'Els envans i els falsos sostres en són exemples.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual de construcció, quina característica tenen els pòrtics de fusta?', 'Els pòrtics de fusta, habituals en equipaments esportius o agraris, permeten grans llums amb poc pes; el col·lapse sobtat per pèrdua ràpida de resistència és característic dels metàl·lics.', 'bomb_t15_construccio', (select id from public.topics where slug = 'bomb-t15-construccio'), 3, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.GRAL.006-Tema-15.-Manual-Op.-basic-construccio.pdf'), 'MAN.GRAL.006, § 5.4.2 Pòrtics de fusta', 'Pòrtics de fusta: emprats en equipaments esportius o agraris. Poden ser laminats, permetent grans llums amb un pes reduït. La fusta té un comportament més previsible al foc, però exigeix proteccions adequades.', null, '387c0ed699037df37af9f28204b0beb7ed9ab1e912c5e4ef1a5c907dff9f28c8', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '387c0ed699037df37af9f28204b0beb7ed9ab1e912c5e4ef1a5c907dff9f28c8')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Són els més pesats i el seu col·lapse és sempre el més greu.', false), ('B', 'Perden resistència amb molta rapidesa en incendi i col·lapsen de sobte.', false), ('C', 'Poden ser laminats i permeten grans llums amb pes reduït; la fusta té un comportament més previsible al foc, però exigeix proteccions adequades.', true), ('D', 'No es poden utilitzar per a llums superiors a 8 m.', false)) as v(label, body, ok)
)
