with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual d''intervenció bàsica en assistències tècniques, un cop assegurat un gos, és imprescindible:', 'Un cop assegurat, cal posar morrió; el contacte visual directe i prolongat es percep com una amenaça.', 'bomb_t16_assistencies_tecniques', (select id from public.topics where slug = 'bomb-t16-assistencies-tecniques'), 1, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-16-MAN.ATXX.000.pdf'), 'MAN.ATXX.000, § gossos', 'Un cop assegurat, és imprescindible col·locar un morrió, ja sigui comercial o improvisat.', null, '766deb367482b7377526297023d7bb807d08ab3dfd2221801d419eb76a68ba21', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '766deb367482b7377526297023d7bb807d08ab3dfd2221801d419eb76a68ba21')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Col·locar-li un morrió, comercial o improvisat.', true), ('B', 'Mirar-lo fixament als ulls per dominar-lo.', false), ('C', 'Deixar-lo anar immediatament perquè no s''estressi.', false), ('D', 'Donar-li aigua abans de traslladar-lo.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
