with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual d''assistències tècniques, quina eina cal evitar sempre en la captura d''un gat?', 'Amb gats es recomana embolicar-los amb una tovallola i transportar-los en gàbia; el llaç està desaconsellat pel risc d''asfíxia.', 'bomb_t16_assistencies_tecniques', (select id from public.topics where slug = 'bomb-t16-assistencies-tecniques'), 1, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-16-MAN.ATXX.000.pdf'), 'MAN.ATXX.000, § gats', 'Cal evitar sempre l’ús del llaç de captura, ja que hi ha un alt risc d’asfíxia.', null, 'd77c84736b533b04d3ae7d04258899eb900803bb6a3f0bca4bf313a4bf62d5dd', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'd77c84736b533b04d3ae7d04258899eb900803bb6a3f0bca4bf313a4bf62d5dd')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La tovallola.', false), ('B', 'La gàbia o caixa de transport.', false), ('C', 'El llaç de captura, per l''alt risc d''asfíxia.', true), ('D', 'Els guants de protecció.', false)) as v(label, body, ok)
)
