with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual d''assistències tècniques, quin és el risc més important amb cavalls i bestiar boví?', 'Els èquids poden mossegar, però el risc principal són les coces; cal aproximar-se pel lateral fora de l''angle cec.', 'bomb_t16_assistencies_tecniques', (select id from public.topics where slug = 'bomb-t16-assistencies-tecniques'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-16-MAN.ATXX.000.pdf'), 'MAN.ATXX.000, § èquids i bòvids', 'Els èquids poden mossegar, però el risc més important en tots dos grups són les coces: en el cas dels cavalls, principalment cap enrere, i en el cas dels bovins, també de forma lateral.', null, '65a6e33bbe56c1540bfa126659537fc4dca002635622dbcbcde3f566156537cc', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '65a6e33bbe56c1540bfa126659537fc4dca002635622dbcbcde3f566156537cc')
  returning id
), o as (
