  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Sempre que es detecti un rusc, sigui on sigui.', false), ('B', 'Només quan hi ha risc immediat per a persones o béns amb afectació directa a tercers.', true), ('C', 'Només si l''avís el fa un ajuntament.', false), ('D', 'Només si es tracta de vespa asiàtica.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual d''assistències tècniques, en entorns urbans o interiors es recomanen les motoserres:', 'Les de benzina són per a treballs intensius sense electricitat; les elèctriques o de bateria, per a entorns urbans o interiors.', 'bomb_t16_assistencies_tecniques', (select id from public.topics where slug = 'bomb-t16-assistencies-tecniques'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-16-MAN.ATXX.000.pdf'), 'MAN.ATXX.000, § tipus de motoserra', 'Els models de benzina són més adequats per a treballs intensius i en entorns sense accés a electricitat, mentre que les motoserres elèctriques o de bateria són recomanades per a entorns urbans o interiors gràcies al seu baix nivell de soroll i absència d’emissions.', null, '91d37ad6ada8b6531680bba44d1e77f7bc157297944c5535f026c533660e5534', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '91d37ad6ada8b6531680bba44d1e77f7bc157297944c5535f026c533660e5534')
  returning id
