with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Cal fer caure amb motoserra un arbre de 12 m d''alçada. Segons el manual d''assistències tècniques, quin perímetre de seguretat (zona de risc A) cal delimitar?', 'La zona A és dues vegades i mitja l''alçada de l''arbre: 2,5 × 12 m = 30 m. 24 m seria només el doble i 2 m és el radi de la zona B al voltant de l''operador.', 'bomb_t16_assistencies_tecniques', (select id from public.topics where slug = 'bomb-t16-assistencies-tecniques'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-16-MAN.ATXX.000.pdf'), 'MAN.ATXX.000, § 3.3 Zones de risc (AGO)', 'Zona de risc A: quan hi ha perill de caiguda de l’arbre s’ha de delimitar un perímetre de seguretat equivalent a dues vegades i mitja l’alçada de l’arbre', null, 'c828da57d6e96d68b44726b961973cd872ccc41600a02cad5931404258480e9d', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'c828da57d6e96d68b44726b961973cd872ccc41600a02cad5931404258480e9d')
  returning id
