)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual d''assistències tècniques, en quines condicions es pot desconnectar una alarma antirobatori?', 'És un sistema privat de seguretat amb implicacions legals; només es desconnecta a requeriment de la policia, sota la seva responsabilitat i en la seva presència.', 'bomb_t16_assistencies_tecniques', (select id from public.topics where slug = 'bomb-t16-assistencies-tecniques'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-16-MAN.ATXX.000.pdf'), 'MAN.ATXX.000, § 5.1 Marc legal de les alarmes', 'Per aquest motiu, només es poden desconnectar a requeriment i sota la responsabilitat de la policia competent, i sempre amb la seva presència.', null, '09a2e0824cc68272cc0ec3523e1d43f20b2759ecf11fe9294d1d93c29d274074', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '09a2e0824cc68272cc0ec3523e1d43f20b2759ecf11fe9294d1d93c29d274074')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Quan ho demani qualsevol veí afectat pel soroll.', false), ('B', 'Sempre que el comandament de Bombers ho consideri oportú, sense necessitat de policia.', false), ('C', 'Només a requeriment i sota la responsabilitat de la policia competent, i sempre amb la seva presència.', true), ('D', 'Només amb autorització escrita de l''empresa instal·ladora.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'En un servei per una alarma d''incendi activada, es comprova que no hi ha risc real. Segons el manual d''assistències tècniques, què cal fer?', 'En l''alarma d''incendi sense risc no es manipula el sistema; tallar l''altaveu, anul·lar el fusible o desconnectar la bateria són opcions per a l''antirobatori accidental, a petició de la policia.', 'bomb_t16_assistencies_tecniques', (select id from public.topics where slug = 'bomb-t16-assistencies-tecniques'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-16-MAN.ATXX.000.pdf'), 'MAN.ATXX.000, § 5.1 Intervenció bàsica en alarmes', 'En el cas d’alarma d’incendi, si no hi ha risc real, no es manipula el sistema, sinó que es contacta amb la central d’alarmes o la propietat per tal que ho solucionin.', null, '9b769e36c857e7d91d6f6a39e1f5e0238e30434d87d964c5c9957a4c163b6a6b', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '9b769e36c857e7d91d6f6a39e1f5e0238e30434d87d964c5c9957a4c163b6a6b')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Desconnectar la bateria de la central.', false), ('B', 'Tallar el cable de l''altaveu exterior.', false), ('C', 'Anul·lar el fusible d''alimentació.', false), ('D', 'No manipular el sistema i contactar amb la central d''alarmes o la propietat perquè ho solucionin.', true)) as v(label, body, ok)
)
