  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual d''assistències tècniques, en el tall horitzontal d''una branca o tronc amb un sol punt de recolzament, quin és l''ordre dels talls?', 'Amb un punt de recolzament: primer inferior, després superior. Amb dos punts és a l''inrevés (primer superior, després inferior); la falca és del tall vertical d''un arbre.', 'bomb_t16_assistencies_tecniques', (select id from public.topics where slug = 'bomb-t16-assistencies-tecniques'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-16-MAN.ATXX.000.pdf'), 'MAN.ATXX.000, § 3.4.2 Tall horitzontal', 'Tall horitzontal amb un punt de recolzament En aquest cas, el primer tall serà l’inferior, i el segon el superior.', null, '8b479345e55e556799bc8028302f02190f21dbb8a0e0d0a1b8273d5f17b2b86e', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '8b479345e55e556799bc8028302f02190f21dbb8a0e0d0a1b8273d5f17b2b86e')
  returning id
