with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual d''assistències tècniques, com són els panys sobreposats?', 'Els sobreposats són visibles per dins i tenen un volum evident (caixa metàl·lica); els encastats van integrats dins del perfil de la porta.', 'bomb_t16_assistencies_tecniques', (select id from public.topics where slug = 'bomb-t16-assistencies-tecniques'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-16-MAN.ATXX.000.pdf'), 'MAN.ATXX.000, § 4.3.1 Tipus de panys', 'Panys sobreposats: es col·loquen per la cara interior de la porta, de forma visible, i són especialment freqüents en habitatges antics o com a panys secundaris de reforç.', null, '965ee266dd4ba63665857b96c89d09387338f6be99be9fc708d9c085e247ded7', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '965ee266dd4ba63665857b96c89d09387338f6be99be9fc708d9c085e247ded7')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
