with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la taula orientativa del manual d''assistències tècniques, quines eines es recomanen per obrir una porta blindada?', 'Per a la blindada (reforços metàl·lics puntuals): palanca gran, escamotejadora, ariet. Radiografia, palanca i mall són per a la fullola, i serra o accés alternatiu per a la cuirassada.', 'bomb_t16_assistencies_tecniques', (select id from public.topics where slug = 'bomb-t16-assistencies-tecniques'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-16-MAN.ATXX.000.pdf'), 'MAN.ATXX.000, § 4.4 Selecció d''eines', 'Blindada Palanca gran, escamotejadora, ariet Reforços metàl·lics puntuals. Es recomana buscar punts febles.', null, '53160cc77fc5845ac062ff052e1332a945af0c3b16cf3fee04ef054a068acddd', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '53160cc77fc5845ac062ff052e1332a945af0c3b16cf3fee04ef054a068acddd')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Radiografia, palanca i mall.', false), ('B', 'Serra o talladora, o un accés alternatiu.', false), ('C', 'Palanca gran, escamotejadora o ariet, buscant-ne els punts febles.', true), ('D', 'Només el mall, perquè l''estructura és molt feble.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual d''assistències tècniques, com s''han de subjectar els sauris (llangardaixos)?', 'Cal controlar la cua perquè moltes espècies la poden perdre com a defensa (autotomia); el plec del clatell és per als gats i la closca, per a les tortugues.', 'bomb_t16_assistencies_tecniques', (select id from public.topics where slug = 'bomb-t16-assistencies-tecniques'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-16-MAN.ATXX.000.pdf'), 'MAN.ATXX.000, § 2.4.7 Rèptils', 'Els sauris (llangardaixos) s’han de subjectar per darrere les extremitats anteriors, controlant la cua, ja que moltes espècies poden perdre-la com a mecanisme de defensa (autotomia).', null, '14ec6fb86fe761d52209f61826fa416b60b03391fcda847537709cf2afd0e23f', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '14ec6fb86fe761d52209f61826fa416b60b03391fcda847537709cf2afd0e23f')
