)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual d''assistències tècniques, en la neteja d''un vessament a la calçada amb absorbents, què cal tenir present?', 'L''absorbent reté el líquid però no l''elimina: la barreja s''ha de retirar en sacs o contenidors. El procediment és anàleg per a àcids o pintures, i els grans vessaments són intervencions NRBQ.', 'bomb_t16_assistencies_tecniques', (select id from public.topics where slug = 'bomb-t16-assistencies-tecniques'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-16-MAN.ATXX.000.pdf'), 'MAN.ATXX.000, § 5.3 Neteja de calçada', 'manté el mateix potencial contaminant i ha de ser recollida i gestionada correctament.', null, '89e7c31337619a7e3fbbc2d521b951c909f01b20892036aeac7568a309227f35', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '89e7c31337619a7e3fbbc2d521b951c909f01b20892036aeac7568a309227f35')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Que, un cop absorbit, el producte deixa de ser contaminant i es pot escombrar a l''embornal.', false), ('B', 'Que els absorbents només serveixen per a combustibles i mai per a àcids o pintures.', false), ('C', 'Que la barreja absorbent-contaminant manté el mateix potencial contaminant i s''ha de recollir i gestionar correctament.', true), ('D', 'Que els grans vessaments també es tracten com una neteja de calçada ordinària.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la classificació per urgència del manual d''assistències tècniques, en l''accés a un habitatge on hi ha una persona atrapada amb símptomes mèdics però conscient, quin tipus d''obertura correspon?', 'És un «rescat»: tècnica ràpida amb dany mínim. L''obertura immediata i destructiva és per al salvament urgent (persona inconscient o en risc imminent) i les no destructives, per al «treball» sense risc immediat.', 'bomb_t16_assistencies_tecniques', (select id from public.topics where slug = 'bomb-t16-assistencies-tecniques'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-16-MAN.ATXX.000.pdf'), 'MAN.ATXX.000, § 4.2 Classificació segons la urgència', 'Rescat Persona atrapada o amb símptomes mèdics, però conscient Tècnica ràpida amb dany mínim', null, '11b44bcaab262547e707ef0446365785f1bc341e07b957bc962f9147fe69afa8', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '11b44bcaab262547e707ef0446365785f1bc341e07b957bc962f9147fe69afa8')
  returning id
), o as (
