with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Cal retirar amb motoserra un arbre caigut a prop d''una línia elèctrica. Segons el manual d''assistències tècniques, quan es pot iniciar l''actuació?', 'Prop de línies elèctriques no es pot començar sense confirmar el tall del subministrament; l''EPI, el tipus de motoserra o les zones de risc no substitueixen aquesta condició.', 'bomb_t16_assistencies_tecniques', (select id from public.topics where slug = 'bomb-t16-assistencies-tecniques'), 3, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-16-MAN.ATXX.000.pdf'), 'MAN.ATXX.000, § 3.5 Línies elèctriques', 'En zones amb proximitat a línies elèctriques, l’actuació no es pot iniciar fins que s’hagi confirmat el tall del subministrament. A més, cal respectar estrictament les distàncies mínimes de seguretat de treball en funció del voltatge.', null, '2883c8a9f5a4faf4f63a5072e14dfc180af4dd61e1a9051e8ebd70e220fd33c9', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '2883c8a9f5a4faf4f63a5072e14dfc180af4dd61e1a9051e8ebd70e220fd33c9')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Immediatament, si el bomber porta guants i botes de seguretat.', false), ('B', 'Quan s''hagi confirmat el tall del subministrament, i respectant les distàncies mínimes de seguretat segons el voltatge.', true), ('C', 'Quan es faci servir una motoserra de bateria en lloc d''una de benzina.', false), ('D', 'Un cop delimitada la zona de risc B de 2 m al voltant de l''operador.', false)) as v(label, body, ok)
)
