with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'En un servei amb un animal, segons el manual d''assistències tècniques, quin és el primer pas previ abans d''entrar-hi en contacte?', 'L''ordre és: 1) alternatives sense contacte, 2) controlar l''ambient (apagar sirenes), 3) aproximació progressiva, 4) valorar força i pes, 5) protegir-se. Fer sonar la sirena va contra el control de l''ambient.', 'bomb_t16_assistencies_tecniques', (select id from public.topics where slug = 'bomb-t16-assistencies-tecniques'), 3, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-16-MAN.ATXX.000.pdf'), 'MAN.ATXX.000, § 2.2 Coneixements generals', 'Abans d’entrar en contacte amb l’animal, cal seguir uns passos previs: 1. Explorar alternatives sense contacte directe, com localitzar el propietari, confinar l’animal en un espai segur o demanar suport a serveis especialitzats.', null, '332379891db2d2e364792a75aa4ad89ccb956bf61b70bccb2ae6af559d29382f', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '332379891db2d2e364792a75aa4ad89ccb956bf61b70bccb2ae6af559d29382f')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Valorar la força i el pes de l''animal per preparar la captura.', false), ('B', 'Explorar alternatives sense contacte directe: localitzar el propietari, confinar l''animal en un espai segur o demanar suport especialitzat.', true), ('C', 'Capturar-lo ràpidament amb un llaç abans que s''estressi.', false), ('D', 'Fer sonar la sirena per allunyar-lo de la zona.', false)) as v(label, body, ok)
)
