with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual d''assistències tècniques, com es defineix el pas de cadena d''una motoserra?', 'Les mides de la cadena, marcades a l''espasa, són el pas (distància entre tres reblons dividida per 2), la longitud o nombre de dents i l''amplada de la baula motriu o galga.', 'bomb_t16_assistencies_tecniques', (select id from public.topics where slug = 'bomb-t16-assistencies-tecniques'), 3, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-16-MAN.ATXX.000.pdf'), 'MAN.ATXX.000, § 3.2.1 Cadena de la motoserra', 'Pas de cadena (distància entre tres reblons dividit per 2)', null, 'c1d3c32aa9854f66d6900af3069442070576cac5105f58d2a7077101dbb4b3a2', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'c1d3c32aa9854f66d6900af3069442070576cac5105f58d2a7077101dbb4b3a2')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El nombre de dents de la cadena.', false), ('B', 'L''amplada de la baula motriu (galga).', false), ('C', 'La distància entre tres reblons dividida per 2.', true), ('D', 'La longitud de l''espasa.', false)) as v(label, body, ok)
)
