with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Sobre el desbrancament i el tall horitzontal amb motoserra, segons el manual d''assistències tècniques, indica la resposta INCORRECTA:', 'El manual indica treballar amb una sola motoserra i no retirar les branques fins acabar de tallar (excepte amb persones atrapades).', 'bomb_t16_assistencies_tecniques', (select id from public.topics where slug = 'bomb-t16-assistencies-tecniques'), 3, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-16-MAN.ATXX.000.pdf'), 'MAN.ATXX.000, § 3.4.2 Desbrancament', 'Quan s’està desbrancant convé treballar amb una sola motoserra, i no retirar les branques fins que s’acabi de tallar (excepte casos amb persones atrapades). […] Primer tall, part superior, segon tall, part inferior. […] Cal tenir en compte que el moviment de la branca o tronc no ens pressioni l’eina i quedi inutilitzada.', null, '82fd6c4081cc4648f8c5636c978db5c97bed27ce1f628e798896a079527f023b', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '82fd6c4081cc4648f8c5636c978db5c97bed27ce1f628e798896a079527f023b')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Cal evitar que el moviment de la branca o del tronc pressioni l''eina i la deixi inutilitzada.', false), ('B', 'Amb dos punts de recolzament, el primer tall es fa a la part superior i el segon a la inferior.', false), ('C', 'Excepte si hi ha persones atrapades, les branques no es retiren fins que s''acaba de tallar.', false), ('D', 'Convé treballar amb diverses motoserres alhora i anar retirant les branques a mesura que es tallen.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual d''assistències tècniques, en el tall d''arbrat, a partir de quina alçada cal utilitzar tècniques i equips de protecció contra caigudes?', 'El treball en alçada implica risc de caiguda: sempre s''ha de prioritzar l''autoescala i, a partir de 2 m, protecció contra caigudes. L''escala colissa només és mitjà d''accés, no de treball.', 'bomb_t16_assistencies_tecniques', (select id from public.topics where slug = 'bomb-t16-assistencies-tecniques'), 3, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-16-MAN.ATXX.000.pdf'), 'MAN.ATXX.000, § 3.5 Treball en alçada', 'Sempre s’ha de prioritzar l’ús d’autoescala i, en treballs a partir de 2 metres, utilitzar tècniques i equips de protecció contra caigudes.', null, 'df4238e38d6c3e4d58981ec59ce1e0b711fb10159c31d0e2b7fe4f34670e7b40', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'df4238e38d6c3e4d58981ec59ce1e0b711fb10159c31d0e2b7fe4f34670e7b40')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'A partir de 2 metres, prioritzant sempre l''ús d''autoescala.', true), ('B', 'A partir de 5 metres.', false), ('C', 'A partir de 10 metres.', false), ('D', 'Només quan es treballa des de l''escala colissa.', false)) as v(label, body, ok)
)
