  select 'Segons el manual de comunicacions per ràdio, un missatge breu és el que:', 'Precisa = dades concretes; breu = mínim de paraules; estructurada = pauta coneguda; confirmada = el receptor respon.', 'bomb_t17_comunicacions_radio', (select id from public.topics where slug = 'bomb-t17-comunicacions-radio'), 1, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-17-MAN.COMU.000.pdf'), 'MAN.COMU.000, § característiques del missatge', 'És breu: utilitza el mínim de paraules per transmetre el màxim d’informació útil.', null, 'fc88045cae951ad35b6b830620b21ec9af0d2ffa552e64365f613a19fbd06f75', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'fc88045cae951ad35b6b830620b21ec9af0d2ffa552e64365f613a19fbd06f75')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Segueix una pauta coneguda per l''emissor i el receptor.', false), ('B', 'Utilitza el mínim de paraules per transmetre el màxim d''informació útil.', true), ('C', 'Transmet exactament el que es vol dir amb dades concretes.', false), ('D', 'Rep resposta del receptor.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual de comunicacions per ràdio, per evitar errors de recepció és recomanable substituir «sí» i «no» per:', '«Afirmatiu» i «negatiu» són formes més clares que el simple sí o no.', 'bomb_t17_comunicacions_radio', (select id from public.topics where slug = 'bomb-t17-comunicacions-radio'), 1, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-17-MAN.COMU.000.pdf'), 'MAN.COMU.000, § afirmatiu i negatiu', 'A més, per evitar errors de recepció en afirmacions o negacions, és recomanable substituir el simple “sí” o “no” per les formes més clares i específiques “afirmatiu” i “negatiu”.', null, '6d2f46f5de86604ee324587cafbf044811f72bb9916def9f4fb66210b4d51233', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '6d2f46f5de86604ee324587cafbf044811f72bb9916def9f4fb66210b4d51233')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', '«Afirmatiu» i «negatiu».', true), ('B', '«Rebut» i «tallo».', false), ('C', '«Correcte» i «incorrecte».', false), ('D', '«Canvi» i «fora».', false)) as v(label, body, ok)
)
