  select 'Segons el manual de comunicacions per ràdio, què és la xarxa RESCAT?', 'RESCAT és una xarxa exclusiva, resistent i estable, pensada per a escenaris crítics.', 'bomb_t17_comunicacions_radio', (select id from public.topics where slug = 'bomb-t17-comunicacions-radio'), 1, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-17-MAN.COMU.000.pdf'), 'MAN.COMU.000, § xarxa RESCAT', 'La xarxa Rescat i les emissores La xarxa RESCAT és la infraestructura de comunicacions exclusiva per a serveis d’emergència i seguretat a Catalunya.', null, 'cdb89ffc941fa64f57be6bce20fdd77cb4748349ccc8b9a4576308d6aeb0d76d', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'cdb89ffc941fa64f57be6bce20fdd77cb4748349ccc8b9a4576308d6aeb0d76d')
