  select 'Segons el manual de comunicacions per ràdio, en una trucada de canal en mode xarxa:', 'La trucada de canal és la comunicació habitual entre tots els terminals del canal; parla un i la resta escolten.', 'bomb_t17_comunicacions_radio', (select id from public.topics where slug = 'bomb-t17-comunicacions-radio'), 1, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-17-MAN.COMU.000.pdf'), 'MAN.COMU.000, § trucada de canal', 'Només un transceptor o emissora pot parlar a la vegada i la resta escolten.', null, 'b41352d2044f964608a916e281a613e8f02e12bc59a435e631e8dbe5f2e21098', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'b41352d2044f964608a916e281a613e8f02e12bc59a435e631e8dbe5f2e21098')
