  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual de comunicacions per ràdio, quan s''ha d''utilitzar l''alfabet radiofònic internacional?', 'S''ha de lletrejar amb l''alfabet radiofònic quan hi ha lletres que poden confondre''s.', 'bomb_t17_comunicacions_radio', (select id from public.topics where slug = 'bomb-t17-comunicacions-radio'), 1, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-17-MAN.COMU.000.pdf'), 'MAN.COMU.000, § alfabet radiofònic', 'Utilitzar l’alfabet radiofònic internacional Quan cal transmetre per ràdio noms propis, codis alfanumèrics, matrícules o qualsevol informació que contingui lletres que puguin generar confusió, s’ha de lletrejar utilitzant l’alfabet radiofònic internacional.', null, 'f988f72b9869918543206855e18f5a6f4829dc0e5fcf4bea463fa43e79e4d2a6', false
