  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual de comunicacions per ràdio, quin és el risc més perillós d''una unitat que no ha canviat al canal assignat?', 'La unitat queda aïllada: no rep ordres, no participa en la coordinació i, sobretot, no pot demanar ajuda.', 'bomb_t17_comunicacions_radio', (select id from public.topics where slug = 'bomb-t17-comunicacions-radio'), 3, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-17-MAN.COMU.000.pdf'), 'MAN.COMU.000, § unitat aïllada', 'En aquest punt el risc no és només tècnic, sinó operatiu i de seguretat, ja que una unitat que no ha canviat de canal pot quedar aïllada, sense rebre ordres, sense participar de la coordinació general i el que és més perillós, sense poder demanar suport o ajuda en cas de necessitat.', null, '9604e74a830ac2ea6e85417fd955a2982234d1dccee871eb75619be7557d680b', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '9604e74a830ac2ea6e85417fd955a2982234d1dccee871eb75619be7557d680b')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Que no pugui demanar suport o ajuda en cas de necessitat.', true), ('B', 'Que saturi el canal de xarxa.', false), ('C', 'Que gasti més bateria del terminal.', false), ('D', 'Que interfereixi amb la telefonia mòbil.', false)) as v(label, body, ok)
)
