with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual de comunicacions per ràdio, en una gran emergència, quina és la funció del canal de trànsit?', 'El canal de trànsit agrupa els vehicles que es desplacen cap a la intervenció; la «columna vertebral» és el canal del servei, i hi ha canals de sector i directe per a les altres funcions.', 'bomb_t17_comunicacions_radio', (select id from public.topics where slug = 'bomb-t17-comunicacions-radio'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-17-MAN.COMU.000.pdf'), 'MAN.COMU.000, § 4.3.1 Canal de trànsit', 'Funció: Descongestionar el canal de servei de les comunicacions entre les unitats que estan en camí.', null, '14ef0dff2a618a35a063dde0cbfbf5aecb44e3a26235d6625ab3b8379c75b579', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '14ef0dff2a618a35a063dde0cbfbf5aecb44e3a26235d6625ab3b8379c75b579')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Descongestionar el canal de servei de les comunicacions de les unitats que estan en camí.', true), ('B', 'Ser la «columna vertebral» del comandament operatiu.', false), ('C', 'Gestionar la coordinació interna d''un sector.', false), ('D', 'Permetre comunicacions de proximitat sense repetidors.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual de comunicacions per ràdio, quina limitació té el mode directe dels transceptors?', 'El mode directe no depèn de la xarxa ni de repetidors i és ideal en interiors, però no permet enviar posicions GPS ni SDS.', 'bomb_t17_comunicacions_radio', (select id from public.topics where slug = 'bomb-t17-comunicacions-radio'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-17-MAN.COMU.000.pdf'), 'MAN.COMU.000, § 5.2.2 Mode Directe', 'No depèn de la xarxa ni de repetidors […] Ideal per a comunicacions curtes o en interiors […] No permet enviar posició GPS ni missatges SDS', null, 'b58c8a58b0df92733a3d309045076dd8d7e416080e1d8604b6526c3c7e75b8a5', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'b58c8a58b0df92733a3d309045076dd8d7e416080e1d8604b6526c3c7e75b8a5')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Necessita cobertura de la xarxa RESCAT.', false), ('B', 'Totes les comunicacions passen per les antenes repetidores (TBS).', false), ('C', 'No es pot fer servir en interiors.', false), ('D', 'No permet enviar la posició GPS ni missatges SDS.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual de comunicacions per ràdio, sobre la trucada telefònica en mode xarxa, és correcte afirmar que:', 'Permet parlar amb un telèfon fix o mòbil, però només amb permisos especials, i aïlla el terminal de les comunicacions de canal, com la trucada individual.', 'bomb_t17_comunicacions_radio', (select id from public.topics where slug = 'bomb-t17-comunicacions-radio'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-17-MAN.COMU.000.pdf'), 'MAN.COMU.000, § 5.3.4 Trucada telefònica', 'Només els terminals amb permisos especials poden iniciar-la. […] Nota: Igual que en la trucada individual, durant la trucada telefònica no es reben missatges de canal.', null, 'ed15ec7ec033107d24b146fe26b1243656158e221162a86e78b31000f086599c', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'ed15ec7ec033107d24b146fe26b1243656158e221162a86e78b31000f086599c')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La poden iniciar tots els transceptors portàtils.', false), ('B', 'Es pot fer també en mode directe, sense cobertura.', false), ('C', 'Mentre dura, es continuen rebent els missatges del canal operatiu.', false), ('D', 'Només la poden iniciar els terminals amb permisos especials i, mentre dura, no es reben missatges de canal.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual de comunicacions per ràdio, com s''han de transmetre unes coordenades o uns graus?', 'Els valors numèrics es diuen dígit per dígit o en parelles, i en coordenades o graus cada número per separat; l''alfabet radiofònic és per a lletres.', 'bomb_t17_comunicacions_radio', (select id from public.topics where slug = 'bomb-t17-comunicacions-radio'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-17-MAN.COMU.000.pdf'), 'MAN.COMU.000, § 3.5.1 Números i coordenades', 'Quan es transmeten valors numèrics (com graus, coordenades o números de telèfon) s’han de dir dígit per dígit o en parelles segons el context, fent una pausa entre cada un, per assegurar la comprensió. Es recomana dir cada número per separat si es tracta de coordenades o graus. […] pronunciar dígits separats (“u-cinc-zero” per 150).', null, '0d94d800d82ef694512b7d28ef2df2bb31ed6fd6d9ef69617db81a9abade1897', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '0d94d800d82ef694512b7d28ef2df2bb31ed6fd6d9ef69617db81a9abade1897')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Dient cada número per separat, amb una pausa entre cada un (per exemple, «u-cinc-zero» per 150).', true), ('B', 'Dient el nombre sencer d''una tirada («cent cinquanta»).', false), ('C', 'Sempre per missatge SDS, mai per veu.', false), ('D', 'Lletrejant cada xifra amb l''alfabet radiofònic internacional.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual de comunicacions per ràdio, quin marcador s''utilitza per corregir una informació que s''ha donat abans de forma errònia?', 'RECTIFICO corregeix una informació errònia; REPETEIXI demana repetir, RECEPCIÓ NEGATIVA comunica que no s''ha rebut bé i INTERROGO inicia una pregunta.', 'bomb_t17_comunicacions_radio', (select id from public.topics where slug = 'bomb-t17-comunicacions-radio'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-17-MAN.COMU.000.pdf'), 'MAN.COMU.000, § Annex 1 Marcadors estàndard', 'RECTIFICO Comunica que es corregeix una informació anterior que s’ha donat de forma errònia.', null, '4a01f3dffa75019882103c8798c4643aacf287ff91b1bc2d6e53641386dfb1e6', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '4a01f3dffa75019882103c8798c4643aacf287ff91b1bc2d6e53641386dfb1e6')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'REPETEIXI.', false), ('B', 'RECTIFICO.', true), ('C', 'RECEPCIÓ NEGATIVA.', false), ('D', 'INTERROGO.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual de comunicacions per ràdio, sobre el mode Pont Ràdio, és correcte afirmar que:', 'El pont enllaça un canal directe amb un de xarxa; només retransmet, n''hi pot haver un per canal i zona i no es combina amb el repetidor. Enllaçar terminals en mode directe fora d''abast és la funció del repetidor.', 'bomb_t17_comunicacions_radio', (select id from public.topics where slug = 'bomb-t17-comunicacions-radio'), 3, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-17-MAN.COMU.000.pdf'), 'MAN.COMU.000, § 5.4.1 Pont ràdio', 'El terminal que actua com a pont no pot participar activament en la conversa, només retransmet. […] Només pot haver-hi un sol pont actiu per canal i zona. […] No es pot combinar amb el mode Repetidor.', null, 'e884034a63147572fd9672dc9eae29ad3d68d475af1028850a7832d9cf2600a3', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'e884034a63147572fd9672dc9eae29ad3d68d475af1028850a7832d9cf2600a3')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Es pot combinar amb el mode Repetidor al mateix canal.', false), ('B', 'Hi pot haver diversos ponts actius al mateix canal i zona.', false), ('C', 'El terminal que fa de pont només retransmet i no pot participar activament en la conversa.', true), ('D', 'Serveix per connectar dos terminals en mode directe sense cap enllaç amb la xarxa.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'En un rescat en zona muntanyosa sense cobertura de la xarxa RESCAT, dos equips treballen en mode directe i els seus terminals no es poden comunicar entre ells. Segons el manual de comunicacions per ràdio, quina és la solució indicada?', 'El repetidor amplia l''abast del mode directe entre terminals que no es veuen; sense cobertura no es pot treballar en mode xarxa (trucades individuals o telefòniques), i el repetidor no es pot activar amb un pont ràdio al mateix canal.', 'bomb_t17_comunicacions_radio', (select id from public.topics where slug = 'bomb-t17-comunicacions-radio'), 3, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-17-MAN.COMU.000.pdf'), 'MAN.COMU.000, § 5.4.2 Mode repetidor', 'Exemple: En un rescat en zona muntanyosa, si els terminals de dos equips no es poden comunicar directament, es pot posicionar un terminal en mode repetidor en un punt elevat per fer d’enllaç.', null, '00c3bc21002d2f340046d94bc4e2f547acb3bdb7831234b54db172094094effb', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '00c3bc21002d2f340046d94bc4e2f547acb3bdb7831234b54db172094094effb')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Posicionar un terminal en mode repetidor en un punt elevat perquè faci d''enllaç.', true), ('B', 'Passar a mode xarxa i fer una trucada individual entre els caps d''equip.', false), ('C', 'Fer una trucada telefònica des d''un dels transceptors.', false), ('D', 'Activar alhora un pont ràdio i un repetidor al mateix canal.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Un bomber que treballa en mode directe dins d''una estructura activa la trucada d''emergència. Segons el manual de comunicacions per ràdio, quina limitació té aquesta trucada?', 'És de màxima prioritat dins del canal directe, però, en no passar per la xarxa, no arriba a la sala de control.', 'bomb_t17_comunicacions_radio', (select id from public.topics where slug = 'bomb-t17-comunicacions-radio'), 3, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-17-MAN.COMU.000.pdf'), 'MAN.COMU.000, § 5.3.8 Trucada d''emergència en mode directe', 'Limitació: Aquesta emergència no arriba a la sala de control, ni activa serveis centralitzats.', null, '2ca652ef97a303e8f8939fb95d9fe54c3b651fbea3769d8aac7a433e5c14d312', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '2ca652ef97a303e8f8939fb95d9fe54c3b651fbea3769d8aac7a433e5c14d312')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'No té prioritat sobre les altres comunicacions del canal directe.', false), ('B', 'No arriba a la sala de control ni activa serveis centralitzats.', true), ('C', 'Només la poden escoltar els terminals amb permisos especials.', false), ('D', 'Interromp les comunicacions de tots els canals de l''agrupació.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual de comunicacions per ràdio, sobre les característiques de la xarxa RESCAT, indica la resposta INCORRECTA:', 'RESCAT no es veu afectada per la saturació de les xarxes mòbils; la resta són avantatges que recull el manual.', 'bomb_t17_comunicacions_radio', (select id from public.topics where slug = 'bomb-t17-comunicacions-radio'), 3, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-17-MAN.COMU.000.pdf'), 'MAN.COMU.000, § 5.1 Característiques de la xarxa Rescat', 'No es veu afectada per la saturació de les xarxes mòbils en grans emergències o esdeveniments amb molta població. […] Disposa de sistemes d’alimentació alternatius, fet que permet una continuïtat operativa en cas de tall de subministrament elèctric. […] Permet localitzar terminals i vehicles sobre el territori […] Té una cobertura extensa, superior a la de la telefonia convencional', null, '7397eb88b719be27644df0359695213c1cd16d29ffe7de069fbc629fe6d84e45', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '7397eb88b719be27644df0359695213c1cd16d29ffe7de069fbc629fe6d84e45')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Disposa de sistemes d''alimentació alternatius en cas de tall elèctric.', false), ('B', 'Permet localitzar terminals i vehicles sobre el territori.', false), ('C', 'Té una cobertura superior a la de la telefonia convencional.', false), ('D', 'Es veu afectada per la saturació de les xarxes mòbils en grans emergències.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons les recomanacions operatives del manual de comunicacions per ràdio, per què no s''han de fer trucades individuals o telefòniques durant una maniobra?', 'Mentre dura una trucada individual o telefònica no es reben les comunicacions de canal; per això s''han de limitar a moments de calma, coordinats i autoritzats.', 'bomb_t17_comunicacions_radio', (select id from public.topics where slug = 'bomb-t17-comunicacions-radio'), 3, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-17-MAN.COMU.000.pdf'), 'MAN.COMU.000, § 5.5 Recomanacions operatives', 'Les trucades individuals o telefòniques aïllen el terminal de les comunicacions de grup, deixant el bomber incomunicat respecte al seu entorn operatiu. […] mai no s’han d’emprar quan s’està executant una maniobra o durant una emergència en curs.', null, '3640101579a5586b19914c3c8321c793bb420f1cef0761bea1cf579ac682e2df', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '3640101579a5586b19914c3c8321c793bb420f1cef0761bea1cf579ac682e2df')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Perquè esgoten la bateria del terminal en pocs minuts.', false), ('B', 'Perquè interrompen sempre la trucada d''emergència dels altres terminals.', false), ('C', 'Perquè aïllen el terminal de les comunicacions de grup i deixen el bomber incomunicat del seu entorn operatiu.', true), ('D', 'Perquè només es poden fer en mode directe i tenen poc abast.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
-- Lote bomb-t18-vehicles-intervencio-man18-v1 (40 preguntas)
insert into public.sources (title, url, kind, publisher, published_on) values ('Cos de Bombers de la Generalitat · MAN.EQIP.000 Vehicles d''intervenció en emergències (Guia orientativa d''estudi, convocatòria 81/26)', 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-18-MAN.EQIP.000.pdf', 'web_oficial'::public.source_kind, 'Generalitat de Catalunya · Departament d''Interior i Seguretat Pública (DGPEIS)', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('bomb-t18-vehicles-intervencio', 'Tema 18. Vehicles d''intervenció en emergències') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('bombers-generalitat') and t.slug = 'bomb-t18-vehicles-intervencio' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual de vehicles d''intervenció en emergències, quina capacitat d''aigua té una Bomba Urbana Lleugera (BUL)?', 'BUL: 1.000–1.650 l; BUP i BRP: 3.000–4.000 l; BNP: 7.000–10.000 l.', 'bomb_t18_vehicles_intervencio', (select id from public.topics where slug = 'bomb-t18-vehicles-intervencio'), 1, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-18-MAN.EQIP.000.pdf'), 'MAN.EQIP.000, § BUL', 'Capacitat d’aigua: entre 1.000 i 1.650 litres.', null, '152c9ecfb9845e92771154c669ae7e629bfffdbc149540d8832e3c5674740769', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '152c9ecfb9845e92771154c669ae7e629bfffdbc149540d8832e3c5674740769')
  returning id
