  select 'Segons el manual de vehicles, quina capacitat de càrrega tenen els avions d''extinció?', 'Avions d''extinció: 3.000-6.000 l; helicòpters d''extinció: 500-1.500 l.', 'bomb_t18_vehicles_intervencio', (select id from public.topics where slug = 'bomb-t18-vehicles-intervencio'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-18-MAN.EQIP.000.pdf'), 'MAN.EQIP.000, § 6.1 avions d''extinció', 'Avions d’extinció: − Capacitat de càrrega: entre 3.000 i 6.000 litres.', null, '96a83787778c912f77e7aba50303bbb503b4c8cfcc389fb76dfe4ac7362f76cc', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '96a83787778c912f77e7aba50303bbb503b4c8cfcc389fb76dfe4ac7362f76cc')
