  select 'Segons el manual de vehicles, quina funció tenen les ambulàncies de tipus B?', 'A1 i A2: transport (A2 col·lectiu no urgent); B: suport vital bàsic; C: suport vital avançat; VIR: atenció sense transport.', 'bomb_t18_vehicles_intervencio', (select id from public.topics where slug = 'bomb-t18-vehicles-intervencio'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-18-MAN.EQIP.000.pdf'), 'MAN.EQIP.000, § 5.1 vehicles sanitaris', 'B Suport vital bàsic 2 Tècnics Emergències Sanitàries', null, '6d6bbe66ef118c6c167a022921ea0bc6059bfd8b00618adf6018bdb8a22ed84a', false
