with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'En la revisió diària d''una autobomba, un cop engegat el motor, què indica el manual de vehicles?', 'Amb el vehicle en marxa, sense accelerar en fred, es deixa uns minuts al ralentí; després es comproven els llums d''error i es prova la bomba d''aigua.', 'bomb_t18_vehicles_intervencio', (select id from public.topics where slug = 'bomb-t18-vehicles-intervencio'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-18-MAN.EQIP.000.pdf'), 'MAN.EQIP.000, § 7.2 comprovacions mecàniques', 'Amb el vehicle en marxa, i sempre sense accelerar en fred, es deixen passar uns minuts al ralentí per assegurar la bona posada en funcionament del sistema.', null, '9342170ea9cc1ab7f377529759bf6801a1f0228df699816ed5e5b42735d3cf52', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '9342170ea9cc1ab7f377529759bf6801a1f0228df699816ed5e5b42735d3cf52')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Accelerar a fons uns segons per escalfar el motor ràpidament.', false), ('B', 'No accelerar en fred i deixar uns minuts el motor al ralentí.', true), ('C', 'Apagar-lo immediatament i comprovar només el material.', false), ('D', 'Sortir a circular per provar els frens abans de mirar els llums d''error.', false)) as v(label, body, ok)
)
