  select 'En un servei amb un helicòpter que ha aterrat a prop de l''equip, quina norma de seguretat indica el manual de vehicles?', 'Cal mantenir la zona d''aterratge clara i senyalitzada, no acostar-se sense autorització i fer servir canals específics amb procediments breus i codificats.', 'bomb_t18_vehicles_intervencio', (select id from public.topics where slug = 'bomb-t18-vehicles-intervencio'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-18-MAN.EQIP.000.pdf'), 'MAN.EQIP.000, § 6.3 seguretat amb helicòpters', 'Normes de seguretat: − Mantenir la zona d’aterratge clara i senyalitzada. − No acostar-se a l’helicòpter sense autorització.', null, 'd1d7ef7453f0096aadf4468174491f83bf5859a76670bcc726c378b958070ecf', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'd1d7ef7453f0096aadf4468174491f83bf5859a76670bcc726c378b958070ecf')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'No acostar-se a l''helicòpter sense autorització.', true), ('B', 'Acostar-se ràpidament per ajudar a descarregar el material.', false), ('C', 'Retirar la senyalització de la zona d''aterratge per no confondre el pilot.', false), ('D', 'Comunicar-se amb el pilot amb el canal habitual del parc i llenguatge lliure.', false)) as v(label, body, ok)
)
