  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual de vehicles, per què la conducció d''una autoescala automàtica (AEA) requereix una atenció especial?', 'El centre de gravetat alt incrementa el balanceig en girs i corbes, i el voladís (cistella plegada) obliga a vigilar les maniobres en espais estrets, sobretot marxa enrere.', 'bomb_t18_vehicles_intervencio', (select id from public.topics where slug = 'bomb-t18-vehicles-intervencio'), 3, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-18-MAN.EQIP.000.pdf'), 'MAN.EQIP.000, § 4.2.2 conducció AEA', 'les AEA tenen un centre de gravetat molt alt, fet que incrementa el risc de balanceig en girs i corbes, i una llargada considerable amb un voladís destacat a la part davantera (la cistella plegada) i posterior.', null, 'a67d39afe40b1201b84938c5c3d44b19465f17a5ce308e3e9611cfa524c72a9e', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'a67d39afe40b1201b84938c5c3d44b19465f17a5ce308e3e9611cfa524c72a9e')
  returning id
