  select 'Segons el manual de conducció, en un servei amb indicis de temptativa de suïcidi, què es recomana en la fase final del desplaçament?', 'En casos d''autòlisi es recomana desactivar els senyals prioritaris en la fase final, sempre que sigui segur.', 'bomb_t19_conduccio_mecanica', (select id from public.topics where slug = 'bomb-t19-conduccio-mecanica'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-19-MAN.EQIP.002.pdf'), 'MAN.EQIP.002, § autòlisi', 'En serveis on hi ha indicis o confirmació que la intervenció està relacionada amb una possible conducta d’autòlisi (temptativa de suïcidi), és recomanable que, en la fase final del desplaçament i sempre que no comprometi la seguretat viària, els vehicles desactivin les sirenes i els llums prioritaris.', null, '434837bd7aa44cad84035c842eefa3188f92832c988d74b587ea206a5521e1bd', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '434837bd7aa44cad84035c842eefa3188f92832c988d74b587ea206a5521e1bd')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Augmentar la intensitat de la sirena per alertar la persona.', false), ('B', 'Mantenir els llums i la sirena fins aturar el vehicle.', false), ('C', 'Desactivar les sirenes i els llums prioritaris, si no compromet la seguretat viària.', true), ('D', 'Aparcar el vehicle a la vista de la persona.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual de conducció, quan s''han de bloquejar els diferencials?', 'Bloquejar amb el vehicle encallat pot danyar els mecanismes; en asfalt no s''han de bloquejar mai.', 'bomb_t19_conduccio_mecanica', (select id from public.topics where slug = 'bomb-t19-conduccio-mecanica'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-19-MAN.EQIP.002.pdf'), 'MAN.EQIP.002, § bloquejadors de diferencial', 'El seu ús ha de ser tècnic i planificat: sempre s’han de bloquejar abans d’entrar en una zona complicada i mai quan el vehicle ja està encallat, ja que en aquest cas poden danyar- se els mecanismes.', null, '7e1308790c68c637cf43c2fb9f93efc03b666874f9e9f3a85f26253b379b1855', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '7e1308790c68c637cf43c2fb9f93efc03b666874f9e9f3a85f26253b379b1855')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Abans d''entrar en una zona complicada, i mai quan el vehicle ja està encallat.', true), ('B', 'Quan el vehicle ja està encallat, per sortir-ne.', false), ('C', 'Sempre, també sobre asfalt.', false), ('D', 'Només en baixades prolongades.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
