with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual de conducció, què pot passar si es bloquegen els diferencials en asfalt o en terreny amb bona adherència?', 'Els diferencials bloquejats només són per a baixa adherència.', 'bomb_t19_conduccio_mecanica', (select id from public.topics where slug = 'bomb-t19-conduccio-mecanica'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-19-MAN.EQIP.002.pdf'), 'MAN.EQIP.002, § diferencials en asfalt', 'Recordar que mai no s’han de bloquejar diferencials en asfalt o terreny amb bona adherència, ja que això pot generar desgast prematur, sobreescalfament o fins i tot la ruptura de paliers.', null, '0b17ca0a620d0a9843bd9feacbcfad00f62a495859b5aa9c5fdba7b67bc27697', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '0b17ca0a620d0a9843bd9feacbcfad00f62a495859b5aa9c5fdba7b67bc27697')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Millora de l''estabilitat en corbes.', false), ('B', 'Reducció del consum de combustible.', false), ('C', 'Res: és indiferent el tipus de terreny.', false), ('D', 'Desgast prematur, sobreescalfament o fins i tot ruptura de paliers.', true)) as v(label, body, ok)
)
