  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual de conducció, en quina posició del volant ha de mantenir les mans el conductor d''un vehicle de bombers?', 'La posició «9 i 3» garanteix un control ferm del vehicle i una resposta ràpida davant imprevistos.', 'bomb_t19_conduccio_mecanica', (select id from public.topics where slug = 'bomb-t19-conduccio-mecanica'), 1, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-19-MAN.EQIP.002.pdf'), 'MAN.EQIP.002, § 6.2 posició de conducció', 'El conductor ha de mantenir una postura còmoda i segura, amb les mans situades a les posicions de les “9 i les 3” del volant.', null, '002ad86e1d6c44b34c642923fe14d848df95d6b21a85e0e0815b0f83757de92f', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '002ad86e1d6c44b34c642923fe14d848df95d6b21a85e0e0815b0f83757de92f')
  returning id
), o as (
