  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Un sistema que evita el bloqueig de les rodes en frenades brusques.', false), ('B', 'Un mecanisme que aprofita l''energia de la cadena cinemàtica per moure elements auxiliars del camió, com la bomba d''aigua.', true), ('C', 'L''element que uneix les suspensions de les rodes d''un mateix eix.', false), ('D', 'Un indicador de la potència màxima del motor.', false)) as v(label, body, ok)
)
