  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual de conducció i mecànica, què és l''angle ventral o de panxa?', 'L''angle d''atac és el frontal, el de sortida el posterior i el ventral el que permet superar un turonet o cresta sense tocar amb el xassís.', 'bomb_t19_conduccio_mecanica', (select id from public.topics where slug = 'bomb-t19-conduccio-mecanica'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-19-MAN.EQIP.002.pdf'), 'MAN.EQIP.002, § 5.6 angle ventral', 'Angle ventral o de panxa: és l’angle màxim que permet al vehicle superar un obstacle central (com un turonet o una cresta) sense que la part inferior del xassís toqui el terra.', null, '46252629ba169a4ccb4ca294f3308aedadede5b7bebec4642266ea93b71461bf', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '46252629ba169a4ccb4ca294f3308aedadede5b7bebec4642266ea93b71461bf')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'L''angle màxim entre el terra i la part frontal del vehicle abans que el para-xocs toqui l''obstacle.', false), ('B', 'L''angle equivalent a la part del darrere del vehicle.', false), ('C', 'L''angle màxim que permet superar un obstacle central sense que la part inferior del xassís toqui el terra.', true), ('D', 'L''angle màxim d''inclinació lateral abans de la bolcada.', false)) as v(label, body, ok)
)
