with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual de conducció, indica la conducta INCORRECTA en la circulació en comboi:', 'La disciplina del comboi exigeix no fer avançaments innecessaris, mantenir la línia de visió, facilitar la incorporació a vies ràpides i no bloquejar cruïlles o interseccions.', 'bomb_t19_conduccio_mecanica', (select id from public.topics where slug = 'bomb-t19-conduccio-mecanica'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-19-MAN.EQIP.002.pdf'), 'MAN.EQIP.002, § 2.4 disciplina del comboi', 'Circular en comboi exigeix una disciplina operativa estricta: no fer avançaments innecessaris, mantenir la línia de visió entre vehicles, facilitar la incorporació a vies ràpides i no bloquejar cruïlles o interseccions.', null, '5327940b397b6cdd72ce4ee63b658dd085a85aeff4aa9cac4691fb3c5aea6fcd', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '5327940b397b6cdd72ce4ee63b658dd085a85aeff4aa9cac4691fb3c5aea6fcd')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'No fer avançaments innecessaris.', false), ('B', 'Mantenir la línia de visió entre vehicles.', false), ('C', 'Facilitar la incorporació a vies ràpides.', false), ('D', 'Bloquejar les cruïlles perquè tot el comboi passi sense aturar-se.', true)) as v(label, body, ok)
)
