  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual de conducció i mecànica, com ha d''estar ajustat el reposacaps perquè sigui efectiu?', 'El reposacaps protegeix de la fuetada cervical si el centre queda a l''alçada de les orelles i en posició vertical.', 'bomb_t19_conduccio_mecanica', (select id from public.topics where slug = 'bomb-t19-conduccio-mecanica'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-19-MAN.EQIP.002.pdf'), 'MAN.EQIP.002, § 6.1 reposacaps', 'el centre del reposacaps ha de quedar a l’alçada de les orelles i en posició vertical.', null, 'a430cf723ea78e02aaf7728657a2cf935c7672abd404ccd668cf482779863274', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'a430cf723ea78e02aaf7728657a2cf935c7672abd404ccd668cf482779863274')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Amb el centre a l''alçada de les orelles i en posició vertical.', true), ('B', 'Amb el centre a l''alçada de les espatlles.', false), ('C', 'Tan avall com sigui possible.', false), ('D', 'Inclinat cap enrere, separat del cap.', false)) as v(label, body, ok)
)
