with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual de conducció i mecànica, què fa el sistema eCall?', 'L''eCall, obligatori a Europa des del 2018 i element de seguretat passiva, usa GPS i una targeta SIM per trucar al 112. Les altres opcions són el control de tracció, l''ESP i un avisador de seguretat activa.', 'bomb_t19_conduccio_mecanica', (select id from public.topics where slug = 'bomb-t19-conduccio-mecanica'), 3, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-19-MAN.EQIP.002.pdf'), 'MAN.EQIP.002, § 6.1 eCall', 'Sistema eCall: obligatori a Europa des de 2018, és un sistema automàtic d’avís d’emergència. Mitjançant GPS i una targeta SIM integrada, envia una trucada immediata al servei 112 amb la posició exacta i les dades del vehicle.', null, 'cc9eb8a84a33f1a5b4f84d0d26388c2a6bdfe4597ab57eb23ffcaa7d97a3be98', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'cc9eb8a84a33f1a5b4f84d0d26388c2a6bdfe4597ab57eb23ffcaa7d97a3be98')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Evita que les rodes patinin en acceleracions fortes.', false), ('B', 'Corregeix la trajectòria actuant sobre els frens de rodes concretes.', false), ('C', 'Avisa el conductor del canvi involuntari de carril.', false), ('D', 'Envia automàticament una trucada al 112 amb la posició exacta i les dades del vehicle.', true)) as v(label, body, ok)
)
