with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual de conducció i mecànica, quin avantatge i quin inconvenient tenen els molls pneumàtics?', 'Els molls pneumàtics funcionen amb bosses d''aire comprimit. Els de fulla són els més resistents però menys confortables; els helicoïdals tenen forma d''espiral i no són tan adequats per a càrregues extremes.', 'bomb_t19_conduccio_mecanica', (select id from public.topics where slug = 'bomb-t19-conduccio-mecanica'), 3, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-19-MAN.EQIP.002.pdf'), 'MAN.EQIP.002, § 5.3.2 molls pneumàtics', 'Aquest sistema té l’avantatge que permet ajustar tant l’altura del vehicle com la duresa de la suspensió segons la càrrega i el tipus de terreny. […] Ara bé, són sistemes més complexos i requereixen més manteniment que els molls tradicionals.', null, '31c8941043fa20dc7f58a78142b8e5b769482e5396303d1b9e6b01e181405c9a', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '31c8941043fa20dc7f58a78142b8e5b769482e5396303d1b9e6b01e181405c9a')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Són els més resistents per a càrregues extremes, però transmeten més vibracions a la cabina.', false), ('B', 'Són els més simples i sense manteniment, però no permeten cap ajust.', false), ('C', 'Permeten ajustar l''altura i la duresa de la suspensió, però són més complexos i requereixen més manteniment.', true), ('D', 'Tenen forma d''espiral i són els més adequats per a càrregues extremes.', false)) as v(label, body, ok)
)
