with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual de conducció i mecànica, per què en els vehicles 4×4 opcionals no s''ha d''utilitzar la reductora sobre asfalt o superfícies molt adherents?', 'En el 4×4 permanent la reductora és independent dels bloquejos i no augmenta el risc en terrenys adherents; en l''opcional va lligada a la tracció total.', 'bomb_t19_conduccio_mecanica', (select id from public.topics where slug = 'bomb-t19-conduccio-mecanica'), 3, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-19-MAN.EQIP.002.pdf'), 'MAN.EQIP.002, § 5.4 reductora en 4x4 opcional', 'En canvi, en els 4×4 opcionals, la reductora sol anar vinculada a la tracció total, per això no s’ha d’utilitzar sobre asfalt o superfícies molt adherents, ja que podria causar trencaments o desgast prematur.', null, '68d97e4d13cc4e6c372feb5ae42476d755a85f91af0e31f604e8308e7c20994b', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '68d97e4d13cc4e6c372feb5ae42476d755a85f91af0e31f604e8308e7c20994b')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Perquè desconnecta els frens del vehicle.', false), ('B', 'Perquè sol anar vinculada a la tracció total i podria causar trencaments o desgast prematur.', true), ('C', 'Perquè augmenta la velocitat màxima del vehicle.', false), ('D', 'Perquè només funciona amb el vehicle en marxa enrere.', false)) as v(label, body, ok)
)
