  select 'Segons el manual d''EPI, de quina categoria és el vestit d''intervenció lleuger?', 'El vestit lleuger és de categoria II; el vestit d''intervenció pesant és de categoria III.', 'bomb_t20_epi_intervencio', (select id from public.topics where slug = 'bomb-t20-epi-intervencio'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-20-MAN.SEGU.000.pdf'), 'MAN.SEGU.000, § 2.3.2 vestit lleuger', 'Vestit d’intervenció lleuger: Ús principal: intervencions en incendis forestals, assistències tècniques i rescat en exteriors, on és prioritari el confort i la mobilitat. Disseny: conjunt jaqueta + pantaló teixit ignífug lleuger i transpirable (p.ex. PBI, Nomex...) Característiques: − EPI categoria II.', null, '763e9dc517184065fc2cbc5d297765041ca4fa44e967b7d640e87ab272fcafcd', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '763e9dc517184065fc2cbc5d297765041ca4fa44e967b7d640e87ab272fcafcd')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Categoria I.', false), ('B', 'Categoria II.', true), ('C', 'Categoria III.', false), ('D', 'No té categoria perquè no és un EPI.', false)) as v(label, body, ok)
)
