with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual d''EPI, com s''ha de mantenir el guant d''intervenció pesant?', 'És un guant de cuir de categoria III amb aramida i Kevlar: drap humit, assecat complet i mai a màquina.', 'bomb_t20_epi_intervencio', (select id from public.topics where slug = 'bomb-t20-epi-intervencio'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-20-MAN.SEGU.000.pdf'), 'MAN.SEGU.000, § 2.3.3 guant pesant', 'Manteniment: Neteja regular amb drap humit, assecat complet, no s’ha de rentar a màquina.', null, '72918a5e1453e97576b8aa9f4b8e52760a3a015f1c9f9a29d7ef0fbca23e4784', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '72918a5e1453e97576b8aa9f4b8e52760a3a015f1c9f9a29d7ef0fbca23e4784')
  returning id
), o as (
