  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Rentat a màquina a alta temperatura després de cada servei.', false), ('B', 'Neteja regular amb drap humit i assecat complet, sense rentar-lo a màquina.', true), ('C', 'Assecat directe sobre una font de calor per accelerar-lo.', false), ('D', 'No requereix cap manteniment.', false)) as v(label, body, ok)
)
