with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual d''EPI, en base a quins dos factors s''estableix la permeabilitat dels vestits de protecció química?', 'La permeabilitat depèn de l''estat d''agregació (sòlid, líquid, gas) i de la forma d''aplicació (esquitx, esprai, a pressió).', 'bomb_t20_epi_intervencio', (select id from public.topics where slug = 'bomb-t20-epi-intervencio'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-20-MAN.SEGU.000.pdf'), 'MAN.SEGU.000, § 2.4.4 permeabilitat', 'Aquesta permeabilitat s’estableix en base a 2 factors: 1. Estat d’agregació del producte (sòlid, líquid, gas) 2. Forma en què s’aplica el producte (esquitx, esprai, a pressió)', null, 'fbc219ba5d349d669a5d3d9c5855030f58e6c65c15fabc8f7765e96aa6745cdd', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'fbc219ba5d349d669a5d3d9c5855030f58e6c65c15fabc8f7765e96aa6745cdd')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
