  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual d''EPI, què indica l''avís «bip-bip» de l''ERA als 170 bars?', '170 bars: un «bip-bip» (meitat del temps de treball); 110 bars: doble «bip-bip» (iniciar la sortida); 60 bars: so continu (reserva).', 'bomb_t20_epi_intervencio', (select id from public.topics where slug = 'bomb-t20-epi-intervencio'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-20-MAN.SEGU.000.pdf'), 'MAN.SEGU.000, § 3.2 avís de 170 bars', '170 bars: “Bip-bip” o Arribada a la meitat del temps de treball', null, 'f862c590d64bd44350f1688be69a5ad41f06a663a6288338dbcdf235aac370d3', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'f862c590d64bd44350f1688be69a5ad41f06a663a6288338dbcdf235aac370d3')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Que cal iniciar la sortida de la zona calenta.', false), ('B', 'L''entrada en la reserva d''aire.', false), ('C', 'L''arribada a la meitat del temps de treball.', true), ('D', 'Que l''usuari porta 30 segons immòbil.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el criteri de càlcul del manual d''EPI, quina capacitat total d''aire té una ampolla d''ERA de 6 litres carregada a 300 bars?', 'Capacitat total = pressió de càrrega × capacitat volumètrica = 300 bar × 6 l = 1.800 l. (306 resulta de sumar, 50 de dividir i 18.000 d''un error de zeros.)', 'bomb_t20_epi_intervencio', (select id from public.topics where slug = 'bomb-t20-epi-intervencio'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-20-MAN.SEGU.000.pdf'), 'MAN.SEGU.000, § 3.4.2 càlcul de capacitat', 'La capacitat total de l’ampolla es calcula multiplicant la pressió de càrrega per la capacitat volumètrica.', null, '1190163a2e100e8be20ad801e469f748f6d9707db547f70c2fd14e8cdef4a762', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '1190163a2e100e8be20ad801e469f748f6d9707db547f70c2fd14e8cdef4a762')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', '306 litres.', false), ('B', '50 litres.', false), ('C', '1.800 litres.', true), ('D', '18.000 litres.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Un bomber evacua una víctima d''un espai amb fum dens fent servir la caputxa de rescat connectada al seu ERA. Segons el manual d''EPI, què ha de tenir especialment en compte?', 'Com que l''aire es comparteix, cal planificar amb rigor l''entrada, la col·locació de la caputxa i la sortida immediata.', 'bomb_t20_epi_intervencio', (select id from public.topics where slug = 'bomb-t20-epi-intervencio'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-20-MAN.SEGU.000.pdf'), 'MAN.SEGU.000, § 3.5 caputxa i autonomia', 'és essencial que el bomber que utilitza la caputxa controli la seva pròpia autonomia d’aire, ja que el subministrament es comparteix amb la víctima. Això implica que el temps disponible per a l’evacuació es redueix', null, '1b25ab8299011e6481c30da5ebcf92ff5426418643f4fd10ee8a64c5de635c71', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '1b25ab8299011e6481c30da5ebcf92ff5426418643f4fd10ee8a64c5de635c71')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Que la caputxa té una ampolla pròpia i no afecta la seva autonomia.', false), ('B', 'Que pot desconnectar la seva màscara per donar més aire a la víctima.', false), ('C', 'Que la caputxa permet romandre indefinidament a la zona calenta.', false), ('D', 'Que el subministrament d''aire es comparteix amb la víctima i el temps disponible es redueix.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual d''EPI, on s''ha de fer la gestió a parc dels equips contaminats?', 'La gestió a parc es fa a la zona bruta, respectant la separació de zones netes i brutes per trencar la cadena de contaminants.', 'bomb_t20_epi_intervencio', (select id from public.topics where slug = 'bomb-t20-epi-intervencio'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-20-MAN.SEGU.000.pdf'), 'MAN.SEGU.000, § 4.2.3 gestió a parc', 'Aquesta gestió s’ha de fer en un lloc adequat de la zona bruta del parc o altres instal·lacions que disposin dels mitjans adequats.', null, 'a4980fffa83478108ab99964bb4341bac58d31b72ee4df1319acbd9b5d89af6e', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'a4980fffa83478108ab99964bb4341bac58d31b72ee4df1319acbd9b5d89af6e')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'A la zona neta del parc, al costat dels vestidors.', false), ('B', 'En un lloc adequat de la zona bruta del parc o en altres instal·lacions amb els mitjans adequats.', true), ('C', 'A la cabina del vehicle, durant el retorn.', false), ('D', 'Al domicili de cada bomber.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual d''EPI, un cop s''ha activat l''alarma d''immobilitat («home mort»), què passa si en els 10 segons següents el dispositiu no detecta cap moviment?', 'L''alarma salta als 30 segons d''immobilitat; si en els 10 segons següents no hi ha moviment, queda fixada i cal desactivar-la manualment.', 'bomb_t20_epi_intervencio', (select id from public.topics where slug = 'bomb-t20-epi-intervencio'), 3, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-20-MAN.SEGU.000.pdf'), 'MAN.SEGU.000, § 3.2 home mort fixat', 'Si en els 10” següents el dispositiu de control en 10” no detecta cap moviment per part de l’usuari, l’alarma queda fixada i només es pot desactivar manualment des dels botons del dispositiu de control electrònic.', null, 'f600821e2dea68e7156e53a74a418e5587cf2e3d4cb102700a95e81e35934a39', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'f600821e2dea68e7156e53a74a418e5587cf2e3d4cb102700a95e81e35934a39')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'L''alarma queda fixada i només es pot desactivar manualment des dels botons del dispositiu de control electrònic.', true), ('B', 'L''alarma s''apaga automàticament.', false), ('C', 'L''ERA talla el subministrament d''aire.', false), ('D', 'Es redueix la pressió de l''ampolla fins a la reserva.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual d''EPI, en una ampolla d''ERA de 6 litres a 300 bars, quin volum aproximat d''aire s''ha de considerar reserva que no s''ha d''utilitzar per a la feina operativa?', 'Capacitat total = 300 bar × 6 l = 1.800 l; reserva ≈ 25 % → 0,25 × 1.800 = 450 l. Els 1.350 l són la part restant i els 1.800 l, la capacitat total.', 'bomb_t20_epi_intervencio', (select id from public.topics where slug = 'bomb-t20-epi-intervencio'), 3, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-20-MAN.SEGU.000.pdf'), 'MAN.SEGU.000, § 3.4.2 càlcul de reserva', 'La capacitat total de l’ampolla es calcula multiplicant la pressió de càrrega per la capacitat volumètrica. […] una part d’aquest aire s’ha de considerar reserva (aprox. 25% de la capacitat), que no s’ha d’utilitzar per a la feina operativa', null, '5019d325f56b2baded8892819ea2d54c8b84ef7665f13dc9c7a479bf7af27b8a', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '5019d325f56b2baded8892819ea2d54c8b84ef7665f13dc9c7a479bf7af27b8a')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', '450 litres.', true), ('B', '1.350 litres.', false), ('C', '60 litres.', false), ('D', '1.800 litres.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual d''EPI, indica el factor que NO figura entre els que poden motivar una gestió avançada o especialitzada d''un equip contaminat:', 'Els quatre factors són l''estat de l''equip, la manca de mitjans, les instruccions del fabricant i els riscos de la manipulació durant el manteniment.', 'bomb_t20_epi_intervencio', (select id from public.topics where slug = 'bomb-t20-epi-intervencio'), 3, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-20-MAN.SEGU.000.pdf'), 'MAN.SEGU.000, § 4.2.4 gestió avançada', 'La necessitat de dur a terme una gestió avançada o especialitzada pot estar motivada per qualsevol dels quatre factors següents: − L’estat de l’equip mateix, segons es desprèn de la inspecció bàsica o assistida − La manca de mitjans necessaris − Les instruccions del fabricant − Els riscos que poden tenir origen en la manipulació dels equips durant les accions de manteniment requerides', null, 'd9af29b99450fe6086069dc22ddb30ec4c885b425e787cde658c69685c918e69', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'd9af29b99450fe6086069dc22ddb30ec4c885b425e787cde658c69685c918e69')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'L''estat de l''equip segons la inspecció bàsica o assistida.', false), ('B', 'La categoria professional del bomber que ha utilitzat l''equip.', true), ('C', 'La manca de mitjans necessaris.', false), ('D', 'Les instruccions del fabricant.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual d''EPI, què determina el tipus de gestió de contaminants que necessita un equip després d''una intervenció?', 'No n''hi ha prou amb la brutícia visible: molts contaminants són invisibles, per això també compten els indicadors tècnics.', 'bomb_t20_epi_intervencio', (select id from public.topics where slug = 'bomb-t20-epi-intervencio'), 3, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-20-MAN.SEGU.000.pdf'), 'MAN.SEGU.000, § 4.2.2 gestió in situ', 'El tipus de gestió vindrà determinada no només per l’estat aparent de l’equip (indicadors sensorials), sinó també pel perfil toxicològic i les característiques de l’escenari d’exposició en què s’hagi utilitzat l’equip (indicadors tècnics).', null, '366b0beeb8e9cd42cc0b4a768066977fe247784c6d37d450c0190ed744e42069', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '366b0beeb8e9cd42cc0b4a768066977fe247784c6d37d450c0190ed744e42069')
  returning id
