  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Un accident químic genera un núvol tòxic que s''acosta a un nucli urbà. Segons el manual de gestió d''emergències, quina mesura de protecció consisteix a mantenir la població dins d''un espai tancat i segur?', 'El confinament protegeix d''un risc exterior com un núvol tòxic, un alliberament radiològic o fum dens; l''evacuació implica desplaçar la població.', 'bomb_t21_gestio_emergencies_proteccio_civil', (select id from public.topics where slug = 'bomb-t21-gestio-emergencies-proteccio-civil'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.GRAL.001-Tema-21-Intro.-gestio-emergencies-i-P.Civil.pdf'), 'MAN.GRAL.001, § 5.8.1 confinament', 'Confinament: El confinament consisteix a mantenir la població dins d’un espai tancat i segur, per protegir-se d’un risc exterior, com ara: − Núvol tòxic (accident químic)', null, '3e4dca6dddcd0f9895bec93683e0e16fe1cb39d16efe553b3bbf36352ba40d33', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '3e4dca6dddcd0f9895bec93683e0e16fe1cb39d16efe553b3bbf36352ba40d33')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El confinament.', true), ('B', 'L''evacuació preventiva.', false), ('C', 'L''evacuació urgent.', false), ('D', 'El trasllat a un punt d''acollida.', false)) as v(label, body, ok)
)
