  select q.id, v.label, v.body, v.ok from q, (values ('A', 'En tres nivells.', false), ('B', 'En cinc nivells.', true), ('C', 'En quatre nivells.', false), ('D', 'En sis nivells.', false)) as v(label, body, ok)
)
