  select 'Segons el manual del Sistema de Comandament, a què van atribuir els estudis els danys dels incendis de Califòrnia que van donar lloc a l''ICS?', 'Els estudis van concloure que els danys no es devien a la manca de recursos ni al fracàs de la tàctica, sinó a una gestió i coordinació inadequades.', 'bomb_t22_sistema_comandament', (select id from public.topics where slug = 'bomb-t22-sistema-comandament'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-22-MAN.COMD.001.pdf'), 'MAN.COMD.001, § 1 causes de l''ICS', 'El personal assignat per determinar les causes d''aquests fets va concloure que no es podia atribuir aquests danys a la manca de recursos o al fracàs de la tàctica. Sorprenentment, els estudis van trobar que els fets es devien a una gestió i una coordinació inadequada.', null, '263420df8e37ddaab5c9f9ac0b31ae80ab8406ad7fb01bac50427a361edfdcca', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '263420df8e37ddaab5c9f9ac0b31ae80ab8406ad7fb01bac50427a361edfdcca')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'A una gestió i una coordinació inadequada.', true), ('B', 'A la manca de recursos.', false), ('C', 'Al fracàs de la tàctica.', false), ('D', 'A la manca de formació en conducció.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual del Sistema de Comandament, quan s''estableix un comandament integrat, des d''on gestionen la resposta els comandaments de les diferents agències?', 'En el comandament integrat les agències treballen en equip sota el comandament responsable i comparteixen un Pla d''Acció des del CCA.', 'bomb_t22_sistema_comandament', (select id from public.topics where slug = 'bomb-t22-sistema-comandament'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-22-MAN.COMD.001.pdf'), 'MAN.COMD.001, § 4.1.2 comandament integrat', 'Quan s’estableix un comandament integrat, els comandaments de les diferents agències gestionen la resposta des d’un únic lloc de comandament, el Centre de Comandament Avançat.', null, 'aa1f19d3bdee5ac2424952b8d9dc24cbba981d98c3d0479cf1e7895cfdba8af6', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'aa1f19d3bdee5ac2424952b8d9dc24cbba981d98c3d0479cf1e7895cfdba8af6')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Cadascun des de la seva sala de control, sense lloc comú.', false), ('B', 'Des del Centre de Comandament Unificat, amb un alt comandament.', false), ('C', 'Des del parc de bombers més proper.', false), ('D', 'Des d''un únic lloc de comandament, el Centre de Comandament Avançat.', true)) as v(label, body, ok)
)
