with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual del Sistema de Comandament, en quin cas es pot instaurar el comandament unificat?', 'En el comandament unificat les agències comparteixen l''autoritat i s''envia un alt comandament al Centre de Comandament Unificat.', 'bomb_t22_sistema_comandament', (select id from public.topics where slug = 'bomb-t22-sistema-comandament'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-22-MAN.COMD.001.pdf'), 'MAN.COMD.001, § 4.1.3 comandament unificat', 'En el casos de grans emergències amb afectació important de territoris limítrofs en què sigui necessari compartir la responsabilitat i la presa de decisions estratègiques entre diferents agències, es pot instaurar el comandament unificat.', null, '10bfb9817ec3be4633b1960be5eff65a0ea7a6b7293ae90c66fcb28f5dfdb23d', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '10bfb9817ec3be4633b1960be5eff65a0ea7a6b7293ae90c66fcb28f5dfdb23d')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'En qualsevol incident quotidià de poca complexitat.', false), ('B', 'Només quan intervé una sola agència.', false), ('C', 'Quan el cap d''intervenció vol delegar totes les seves funcions.', false), ('D', 'En grans emergències amb afectació important de territoris limítrofs en què cal compartir la responsabilitat i les decisions estratègiques entre agències.', true)) as v(label, body, ok)
)
