with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual del Sistema de Comandament, què estableix el concepte «+1/-1»?', 'El concepte +1/-1 resulta dels principis de cadena i línia de comandament i aclareix les relacions de subordinació i comunicació.', 'bomb_t22_sistema_comandament', (select id from public.topics where slug = 'bomb-t22-sistema-comandament'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-22-MAN.COMD.001.pdf'), 'MAN.COMD.001, § 4.2 concepte +1/-1', 'Cada comandament ha de controlar les actuacions del personal sota la seva directa supervisió, a qui dona ordres. • Cada unitat ha de tenir un únic superior jeràrquic definit, a qui reporta.', null, '5d52d4a865e413fd8a1d8e79f04468bc62897874d1b9c07e4af0fef713c56749', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '5d52d4a865e413fd8a1d8e79f04468bc62897874d1b9c07e4af0fef713c56749')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Que cada unitat pot tenir dos superiors jeràrquics.', false), ('B', 'Que el tram de control ha de ser sempre d''una sola línia.', false), ('C', 'Que cada comandament controla el personal sota la seva directa supervisió i que cada unitat té un únic superior jeràrquic definit.', true), ('D', 'Que cada sector ha de tenir un comandament més i una unitat menys.', false)) as v(label, body, ok)
)
