with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual del Sistema de Comandament, quines àrees engloba l''àrea de Suport de l''organigrama SISCOM dels Bombers de la Generalitat?', 'Suport assumeix l''anàlisi i el suport tècnic o logístic i engloba planificació i logística.', 'bomb_t22_sistema_comandament', (select id from public.topics where slug = 'bomb-t22-sistema-comandament'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-22-MAN.COMD.001.pdf'), 'MAN.COMD.001, § 5.1 suport', 'És el responsable d’assumir l''anàlisi i el suport tècnic o logístic en la intervenció, formant part del dispositiu d''assessorament i suport al comandament en els àmbits de coordinació i operatiu, i es desplega mitjançant les especialitats i el suport logístic. Engloba la planificació i la logística.', null, '42c4c2169a172a795384b1c46eac85a599257970698bf0edc92211e4b64c312e', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '42c4c2169a172a795384b1c46eac85a599257970698bf0edc92211e4b64c312e')
  returning id
