with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual de prevenció d''incendis bàsica, les mesures de protecció activa són les encaminades a:', 'L''activa necessita interacció dels ocupants o dels equips; la passiva ja la proporciona l''edifici.', 'bomb_t23_prevencio_incendis', (select id from public.topics where slug = 'bomb-t23-prevencio-incendis'), 1, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SP.000-Tema-23.-Prevencio-basica-incendis.pdf'), 'MAN.SP.000, § protecció activa', 'Mesures de protecció activa: són mesures de seguretat encaminades a detectar l’incendi, transmetre l’alarma als ocupants de l’edifici i extingir l’incendi o limitar-ne la seva propagació.', null, 'a7445b0147144acfd70757cf5f6a4938c2ca3bd2260f6e0638f39d3a722f0500', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'a7445b0147144acfd70757cf5f6a4938c2ca3bd2260f6e0638f39d3a722f0500')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Detectar l''incendi, transmetre l''alarma i extingir-lo o limitar-ne la propagació.', true), ('B', 'Limitar la propagació gràcies al disseny i als materials de l''edifici.', false), ('C', 'Garantir la resistència estructural sense intervenció humana.', false), ('D', 'Regular la llicència d''obres.', false)) as v(label, body, ok)
)
