with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual de prevenció d''incendis, quina llei catalana regula la prevenció i seguretat en matèria d''incendis en establiments, activitats, infraestructures i edificis?', 'La Llei 3/2010 també crea un règim sancionador específic.', 'bomb_t23_prevencio_incendis', (select id from public.topics where slug = 'bomb-t23-prevencio-incendis'), 1, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SP.000-Tema-23.-Prevencio-basica-incendis.pdf'), 'MAN.SP.000, § Llei 3/2010', 'La Llei 3/2010, de Prevenció i seguretat en matèria d’incendis en establiments, activitats, infraestructures i edificis determina quins seran els actes, procediments i òrgans administratius amb competències en cadascuna de les parts del procés de sol·licitud de llicència.', null, 'e9493d6db13811e6ed48719e738f388345c81b51de36d2dd2eedc38e1e786fdf', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'e9493d6db13811e6ed48719e738f388345c81b51de36d2dd2eedc38e1e786fdf')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
