with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual de prevenció d''incendis, en la classificació de resistència al foc, què indica la lletra R?', 'R = capacitat portant; E = integritat; I = aïllament tèrmic.', 'bomb_t23_prevencio_incendis', (select id from public.topics where slug = 'bomb-t23-prevencio-incendis'), 1, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SP.000-Tema-23.-Prevencio-basica-incendis.pdf'), 'MAN.SP.000, § resistència al foc', 'Resistència al foc Es defineix la resistència al foc d''un element constructiu com la capacitat d’aquest per mantenir durant un període de temps determinat la funció portant (R) que se li exigeixi, així com la integritat (E) i/o l’aïllament tèrmic (I) segons els termes especificats a l’assaig normalitzat corresponent.', null, '5e53abdb4370a557ad7ac4c3b1d1e1db60f3db475e6eec088cc8e554eb942ea0', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '5e53abdb4370a557ad7ac4c3b1d1e1db60f3db475e6eec088cc8e554eb942ea0')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La integritat.', false), ('B', 'L''aïllament tèrmic.', false), ('C', 'La funció portant.', true), ('D', 'La reacció al foc.', false)) as v(label, body, ok)
)
