with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual de prevenció d''incendis, quines han de ser les vies de penetració prioritàries per als bombers?', 'Les vies protegides coincideixen amb les vies d''evacuació més segures i garanteixen un alt grau de seguretat.', 'bomb_t23_prevencio_incendis', (select id from public.topics where slug = 'bomb-t23-prevencio-incendis'), 1, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SP.000-Tema-23.-Prevencio-basica-incendis.pdf'), 'MAN.SP.000, § vies de penetració protegides', 'Les vies de penetració protegides han de ser les vies de penetració prioritàries per als bombers i són aquelles que garanteixen un alt grau de seguretat.', null, '70bec65a729c457cbfd90f31ae0c555ad8edeb82f1fed645e820fb457e8b52fa', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '70bec65a729c457cbfd90f31ae0c555ad8edeb82f1fed645e820fb457e8b52fa')
  returning id
), o as (
