  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Les finestres de la façana posterior.', false), ('B', 'Els ascensors.', false), ('C', 'Les cobertes.', false), ('D', 'Les vies de penetració protegides.', true)) as v(label, body, ok)
)
