with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual de prevenció d''incendis, què és un mur tallafocs?', 'El mur tallafocs limita la propagació entre edificacions o sectors veïns, sobretot per coberta.', 'bomb_t23_prevencio_incendis', (select id from public.topics where slug = 'bomb-t23-prevencio-incendis'), 1, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SP.000-Tema-23.-Prevencio-basica-incendis.pdf'), 'MAN.SP.000, § mur tallafocs', 'Imatge extreta de CTE DB SI Un altre element que permet limitar el risc de propagació entre edificacions o sectors veïns, especialment a nivell de coberta, és el mur tallafocs, entenent aquest com una prolongació de la paret mitgera per sobre de la coberta.', null, 'b6354ddcbc8d4e82a9730db493650d7871785f3105d71e950652626b6ad9b2dd', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'b6354ddcbc8d4e82a9730db493650d7871785f3105d71e950652626b6ad9b2dd')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Una porta resistent al foc amb tancament automàtic.', false), ('B', 'Una prolongació de la paret mitgera per sobre de la coberta.', true), ('C', 'Un sistema de ventilació de fums.', false), ('D', 'Una franja de vegetació desbrossada.', false)) as v(label, body, ok)
)
