with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual de prevenció d''incendis, què es considera façana accessible?', 'Les obertures d''accés són portals i finestres amb dimensions i separació regulades.', 'bomb_t23_prevencio_incendis', (select id from public.topics where slug = 'bomb-t23-prevencio-incendis'), 1, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SP.000-Tema-23.-Prevencio-basica-incendis.pdf'), 'MAN.SP.000, § façana accessible', 'Es considera façana accessible d’un edifici aquella que disposi d’obertures per permetre l’accés dels bombers des de l’exterior a cada planta o forjat ocupat.', null, 'e1aaebadd7aa7fa98d976c7cd38dbc21f9f49b84bac6157ed3585754884ca47f', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'e1aaebadd7aa7fa98d976c7cd38dbc21f9f49b84bac6157ed3585754884ca47f')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La que disposa d''obertures per permetre l''accés dels bombers des de l''exterior a cada planta o forjat ocupat.', true), ('B', 'Qualsevol façana sense balcons.', false), ('C', 'La façana orientada al nord.', false), ('D', 'La façana amb escala d''incendis exterior obligatòria.', false)) as v(label, body, ok)
)
