with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual de prevenció d''incendis, quina característica tenen les mesures de protecció passiva?', 'Limitar la propagació, protegir l''estructura i facilitar l''evacuació i l''accés dels bombers.', 'bomb_t23_prevencio_incendis', (select id from public.topics where slug = 'bomb-t23-prevencio-incendis'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SP.000-Tema-23.-Prevencio-basica-incendis.pdf'), 'MAN.SP.000, § protecció passiva', 'Actuen de forma passiva a l’edifici, és a dir, són mesures de seguretat que l’edifici ja ofereix per sí mateix gràcies al seu disseny i als materials emprats en la seva construcció, i en general no precisen necessàriament de la interacció dels ocupants o dels equips intervinents per funcionar.', null, '5dd7dc3f2735ab37e7819c3889e11d724f8b9000de54f50ba65b7cd8296f4ba3', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '5dd7dc3f2735ab37e7819c3889e11d724f8b9000de54f50ba65b7cd8296f4ba3')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Necessiten sempre l''actuació dels ocupants.', false), ('B', 'Només inclouen extintors i boques d''incendi.', false), ('C', 'Només serveixen per detectar l''incendi.', false), ('D', 'Les ofereix l''edifici per si mateix pel seu disseny i materials i, en general, no requereixen interacció.', true)) as v(label, body, ok)
)
