select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual de prevenció d''incendis, el criteri d''integritat (E) és la capacitat d''un element de:', 'E = integritat davant flames i gasos calents; I = aïllament tèrmic.', 'bomb_t23_prevencio_incendis', (select id from public.topics where slug = 'bomb-t23-prevencio-incendis'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SP.000-Tema-23.-Prevencio-basica-incendis.pdf'), 'MAN.SP.000, § integritat', 'Integritat (E): un element constructiu exposat al foc en un dels seus costats es defineix amb el concepte d’integritat (E) quan té la capacitat de prevenir el pas de les flames i de gasos calents o l’aparició de flames a la cara no exposada durant un temps establert en un assaig normalitzat de resistència al foc.', null, 'd6c1a146cd3d78b8bc861ae8c838b71220cf94709c7fa1632324fcbd973d3b7b', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'd6c1a146cd3d78b8bc861ae8c838b71220cf94709c7fa1632324fcbd973d3b7b')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Impedir el pas de la calor durant un temps en minuts.', false), ('B', 'Prevenir el pas de flames i gasos calents o l''aparició de flames a la cara no exposada.', true), ('C', 'Mantenir la funció portant.', false), ('D', 'No desprendre gotes inflamades.', false)) as v(label, body, ok)
)
