  select 'Segons el manual de prevenció d''incendis, la reacció al foc d''un material és:', 'La reacció al foc és propietat del material; la resistència al foc ho és dels elements constructius.', 'bomb_t23_prevencio_incendis', (select id from public.topics where slug = 'bomb-t23-prevencio-incendis'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SP.000-Tema-23.-Prevencio-basica-incendis.pdf'), 'MAN.SP.000, § reacció al foc', 'Reacció al foc La reacció al foc d’un material és la resposta que té aquest material mesurada segons la contribució que realitza al desenvolupament del foc mitjançant la seva pròpia combustió, sota condicions específiques d’assaig.', null, '723ecf361613a16639034a91773b7f4c5c1c8dbee9e3d90cade320f9892971f3', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '723ecf361613a16639034a91773b7f4c5c1c8dbee9e3d90cade320f9892971f3')
  returning id
), o as (
