with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual de prevenció d''incendis bàsica, en una instal·lació de ruixadors de canonada seca, què fa actuar la vàlvula de control quan s''obre un ruixador?', 'Després de la vàlvula de control les canonades són plenes d''aire a pressió; quan un ruixador s''obre, la pressió baixa, la vàlvula actua i la xarxa s''omple d''aigua.', 'bomb_t23_prevencio_incendis', (select id from public.topics where slug = 'bomb-t23-prevencio-incendis'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SP.000-Tema-23.-Prevencio-basica-incendis.pdf'), 'MAN.SP.000, § 4.2.6 Ruixadors de canonada seca', 'De canonada seca: les canonades situades després de la vàlvula de control es troben buides d’aigua però plenes d’aire a pressió. Quan un ruixador s’obre, la pressió d’aire disminueix i fa actuar la vàlvula de control, produint-se l’ompliment de la xarxa d’aigua i la sortida de l’aigua pels ruixadors.', null, '6d3680162dfcdf40ba93299bb1c65f0e120986a342ef9923e8ff68ee590855e8', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '6d3680162dfcdf40ba93299bb1c65f0e120986a342ef9923e8ff68ee590855e8')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Un augment de la pressió de l''aigua de la xarxa.', false), ('B', 'El senyal de dues zones de detecció creuades.', false), ('C', 'L''accionament manual d''un polsador.', false), ('D', 'La disminució de la pressió de l''aire que omple les canonades.', true)) as v(label, body, ok)
)
