  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual de prevenció d''incendis bàsica, per a què serveix el retard temporal abans del dispar d''un sistema d''extinció per agents gasosos?', 'La central necessita senyal de les dues zones de detecció i, normalment després d''un retard, dispara el gas; l''atmosfera pot esdevenir asfixiant.', 'bomb_t23_prevencio_incendis', (select id from public.topics where slug = 'bomb-t23-prevencio-incendis'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SP.000-Tema-23.-Prevencio-basica-incendis.pdf'), 'MAN.SP.000, § 4.2.6 Agents gasosos', 'La central de detecció precisa rebre senyal d’ambdues zones simultàniament per tal de disparar el gas extintor, normalment després d’un retard temporal que serveix per advertir al personal present a la zona per tal que abandoni el recinte.', null, 'acce42a452b3859b851b85ac4740426530de600cc747cfeb95f3a27c2bdbec9e', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'acce42a452b3859b851b85ac4740426530de600cc747cfeb95f3a27c2bdbec9e')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
