with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual de prevenció d''incendis bàsica, com es classifica actualment un incendi en un quadre elèctric en tensió?', 'L''electricitat no crema, sinó els materials dels equips; la classe L correspon a bateries d''ió liti sense liti metàl·lic.', 'bomb_t23_prevencio_incendis', (select id from public.topics where slug = 'bomb-t23-prevencio-incendis'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SP.000-Tema-23.-Prevencio-basica-incendis.pdf'), 'MAN.SP.000, § 7 Classes de foc', 'Actualment, però, no es consideren una classe de foc específica, atès que l’electricitat no crema, sinó que cremen els materials que formen part dels equips o instal·lacions. […] La classe del foc serà A, B, C, D o F segons la naturalesa dels materials implicats.', null, '67abf0b662a539121d7d7e06ceba116b76699f6446420c5c429e62c225b94938', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '67abf0b662a539121d7d7e06ceba116b76699f6446420c5c429e62c225b94938')
  returning id
