  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual d''intervenció bàsica en incendis estructurals, com es delimita la zona calenta en un incendi d''habitatge o edifici convencional?', 'El doble de l''alçada de la façana s''aplica a les naus industrials; en habitatges, 15 m al voltant de l''entrada i de la projecció a façana.', 'bomb_t24_incendis_estructurals', (select id from public.topics where slug = 'bomb-t24-incendis-estructurals'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-24-MAN.INES.000.pdf'), 'MAN.INES.000, § 5.2.2 Zona calenta', 'En habitatges o edificis convencionals: radi de 15 m al voltant de l’entrada i projecció de l’incendi a la façana.', null, '4dfa5ddae426aba1e6694bdfa453659a6073228b7cc7a7c2bbb5efe413f12009', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '4dfa5ddae426aba1e6694bdfa453659a6073228b7cc7a7c2bbb5efe413f12009')
