)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'En un incendi estructural, abans de posar en marxa un ventilador de pressió positiva (VPP), què cal tenir clarament identificat segons el manual?', 'La VPP mai no s''ha d''aplicar sense un punt de sortida de fums establert, ni dirigida directament al focus.', 'bomb_t24_incendis_estructurals', (select id from public.topics where slug = 'bomb-t24-incendis-estructurals'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-24-MAN.INES.000.pdf'), 'MAN.INES.000, § 4.4.3 Ventilació VPP', 'Mai no s’ha d’aplicar si no s’ha identificat clarament el punt de sortida del fum.', null, 'aac5b9678d7fa5bdf6043dd7031992288809ad6820f3e8b677703282d5790ba4', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'aac5b9678d7fa5bdf6043dd7031992288809ad6820f3e8b677703282d5790ba4')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El punt de sortida del fum.', true), ('B', 'El nombre de plantes sota rasant.', false), ('C', 'La ubicació del quadre elèctric general.', false), ('D', 'La direcció del vent en alçada.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
