with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual d''intervenció bàsica en incendis estructurals, sobre la ventilació per pressió negativa (VPN), indica la resposta INCORRECTA:', 'El manual diu el contrari: la VPN fa una bona extracció amb gasos més pesants que l''aire.', 'bomb_t24_incendis_estructurals', (select id from public.topics where slug = 'bomb-t24-incendis-estructurals'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-24-MAN.INES.000.pdf'), 'MAN.INES.000, § 4.4.4 Ventilació per pressió negativa', 'No presenta cap risc de dispersió dels fums a locals no afectats per l’incendi. − És simple i ràpida d''implementar si aprofitem les instal·lacions ja muntades. − Ofereix pocs riscos induïts. − Bona extracció amb gasos més pesants que l’aire. − Es pot utilitzar en soterranis.', null, 'a7288c32c9eab9769e1d4c8189c4804098cde0bacd9057848135836653860e2d', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'a7288c32c9eab9769e1d4c8189c4804098cde0bacd9057848135836653860e2d')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'No presenta risc de dispersió dels fums a locals no afectats.', false), ('B', 'És simple i ràpida d''implementar si s''aprofiten les instal·lacions ja muntades.', false), ('C', 'Es pot utilitzar en soterranis.', false), ('D', 'Només ofereix bona extracció amb gasos més lleugers que l''aire.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
