with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'En la tècnica d''entrada segura en un recinte incendiat, què es fa en la fase d''obertura parcial, segons el manual?', 'L''obertura parcial deixa sortir part del fum i el pols d''aigua refreda la capa superior i permet comprovar com es comporta el fum.', 'bomb_t24_incendis_estructurals', (select id from public.topics where slug = 'bomb-t24-incendis-estructurals'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-24-MAN.INES.000.pdf'), 'MAN.INES.000, § 5.7.2 Fases de l''entrada segura', 'S’obre la porta només uns centímetres per permetre la sortida parcial del fum. o Es realitza una polvorització curta cap al sostre amb raig d’atac difós o polvoritzat per refredar la capa superior de gasos calents.', null, '4f5a889902a2479d7d16022596bce00f435df3cf7230b3a273aae590c824952e', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '4f5a889902a2479d7d16022596bce00f435df3cf7230b3a273aae590c824952e')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Obrir la porta del tot i entrar ràpidament amb raig tens.', false), ('B', 'Trencar una finestra per ventilar abans d''obrir.', false), ('C', 'Obrir la porta només uns centímetres i fer una polvorització curta cap al sostre per refredar la capa de gasos.', true), ('D', 'Aplicar aigua directament al terra del recinte durant un minut.', false)) as v(label, body, ok)
)
