with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'En un incendi estructural, el binomi troba una víctima a prop del focus. Què cal prioritzar, segons el manual?', 'Només si és imprescindible per a l''autoprotecció dels intervinents es fa un atac inicial al foc abans de l''evacuació.', 'bomb_t24_incendis_estructurals', (select id from public.topics where slug = 'bomb-t24-incendis-estructurals'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-24-MAN.INES.000.pdf'), 'MAN.INES.000, § 5.7.3 Consideracions específiques', 'L’aplicació d’aigua sobre el focus genera vapor que pot causar cremades greus a les persones atrapades. Per aquest motiu, sempre s’ha de prioritzar la recerca i l’extracció immediata de les víctimes quan es trobin a prop de l’incendi', null, 'd9f703f3e35f79671ef093ffe569d9538c1e3610c39cf14578e239c19871b99a', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'd9f703f3e35f79671ef093ffe569d9538c1e3610c39cf14578e239c19871b99a')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Atacar primer el focus amb raig tens per reduir la temperatura.', false), ('B', 'La recerca i extracció immediata de la víctima, perquè el vapor de l''atac pot causar-li cremades greus.', true), ('C', 'Ventilar el recinte amb VPP abans de moure la víctima.', false), ('D', 'Tancar la porta i esperar el relleu.', false)) as v(label, body, ok)
)
