with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual d''intervenció bàsica en incendis estructurals, per què s''anomenen «incendis envoltants» els que afecten edificis amb façanes ventilades?', 'Les façanes ventilades faciliten una propagació molt ràpida per l''exterior, que després entra a l''edifici.', 'bomb_t24_incendis_estructurals', (select id from public.topics where slug = 'bomb-t24-incendis-estructurals'), 3, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-24-MAN.INES.000.pdf'), 'MAN.INES.000, § 3.4.1 Propagació per flames', 'Edificis amb façanes ventilades poden facilitar una propagació molt ràpida. A més, l''incendi propaga de l''exterior cap a l''interior, per aquest motiu, son anomenats incendis envoltants.', null, 'b17b59f7577033b8275c33812bf67f5dd91dc8808e27007ed9ed66acfb526d18', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'b17b59f7577033b8275c33812bf67f5dd91dc8808e27007ed9ed66acfb526d18')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Perquè l''incendi propaga de l''exterior cap a l''interior.', true), ('B', 'Perquè el fum envolta l''escala per efecte xemeneia.', false), ('C', 'Perquè el foc baixa per degoteig de plàstics.', false), ('D', 'Perquè el vent en alçada els sobrealimenta.', false)) as v(label, body, ok)
)
