  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual d''incendis forestals, quin efecte genera la formació d''un pirocúmul?', 'Com més alçada té el pirocúmul, més velocitat dona al front.', 'bomb_t25_incendis_forestals', (select id from public.topics where slug = 'bomb-t25-incendis-forestals'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-25-MAN.INVE.000.pdf'), 'MAN.INVE.000, § indraft', 'Així, la formació del pirocúmul genera vents d’aspiració cap a ell (indraft), que acceleren el front de l’incendi de forma proporcional a l’alçada del pirocúmul (quan més alçada més velocitat).', null, 'cc47c07e99bfe2cc202974d960ad884996f9271d3103cd4f8f12881702eae6b8', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'cc47c07e99bfe2cc202974d960ad884996f9271d3103cd4f8f12881702eae6b8')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Una pluja que extingeix l''incendi.', false), ('B', 'Vents d''aspiració cap a ell (indraft) que acceleren el front de l''incendi.', true), ('C', 'La desaparició del vent general.', false), ('D', 'Una disminució de la intensitat del foc.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
