  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual d''incendis forestals, què indica probablement una columna de fum fortament inclinada?', 'La inclinació és l''angle de la columna respecte a la vertical; si és molt inclinada, el vent domina.', 'bomb_t25_incendis_forestals', (select id from public.topics where slug = 'bomb-t25-incendis-forestals'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-25-MAN.INVE.000.pdf'), 'MAN.INVE.000, § inclinació de la columna', 'Exemple: si veiem una columna fortament inclinada és probable que es tracti d’un foc de vent.', null, 'ef826afd060e48cec51dfa0fc1093fc0aca95cec4809ea0b892ac5557a864fa5', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'ef826afd060e48cec51dfa0fc1093fc0aca95cec4809ea0b892ac5557a864fa5')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Un foc convectiu.', false), ('B', 'Un foc de subsòl.', false), ('C', 'Un foc de vent.', true), ('D', 'Un foc en fase d''extinció.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual d''incendis forestals, com es propaguen els focs de capçades respecte als de superfície?', 'Els focs de capçades sovint deriven dels de superfície i són un dels escenaris més perillosos.', 'bomb_t25_incendis_forestals', (select id from public.topics where slug = 'bomb-t25-incendis-forestals'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-25-MAN.INVE.000.pdf'), 'MAN.INVE.000, § focs de capçades', 'Focs de capçades Els focs de capçades són incendis que avancen consumint la part superior dels arbres i es propaguen amb molta més rapidesa que els focs de superfície, dels quals sovint en deriven.', null, 'd2e75f5b8e4a77684db4c0622db84f4572937f6dcf07fe209dfa7e961cf128a1', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'd2e75f5b8e4a77684db4c0622db84f4572937f6dcf07fe209dfa7e961cf128a1')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Amb molta més rapidesa, consumint la part superior dels arbres.', true), ('B', 'Més lentament, perquè les capçades són humides.', false), ('C', 'A la mateixa velocitat.', false), ('D', 'Només per sota terra.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual d''incendis forestals, el perímetre de l''incendi és:', 'La definició del perímetre estableix l''àrea de treball i la magnitud de l''incendi.', 'bomb_t25_incendis_forestals', (select id from public.topics where slug = 'bomb-t25-incendis-forestals'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-25-MAN.INVE.000.pdf'), 'MAN.INVE.000, § perímetre', 'Perímetre de l’incendi És la línia tancada que engloba totes les zones afectades pel foc, incloent el cap, els flancs, la cua i qualsevol focus secundari que s’hagi incorporat.', null, '71f650e17d6a41f78525438251a7651a50c9035e3c97f14f57840ad3311735d8', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '71f650e17d6a41f78525438251a7651a50c9035e3c97f14f57840ad3311735d8')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La línia imaginària entre el punt d''inici i el cap.', false), ('B', 'La línia tancada que engloba totes les zones afectades, inclosos cap, flancs, cua i focus incorporats.', true), ('C', 'La part més activa del front.', false), ('D', 'La distància recorreguda per les brases.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons la definició del manual d''incendis forestals, quan es considera gran incendi forestal (GIF), entre altres supòsits?', 'El GIF supera de forma sostinguda la capacitat d''extinció, pot afectar greument la població o crema més de 500 ha.', 'bomb_t25_incendis_forestals', (select id from public.topics where slug = 'bomb-t25-incendis-forestals'), 3, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-25-MAN.INVE.000.pdf'), 'MAN.INVE.000, § GIF', 'Gran incendi forestal (GIF): incendi que manté de forma sostinguda una velocitat, intensitat lineal i longitud de flama que supera la capacitat dels sistemes d''extinció, que pot afectar de forma important la població o que afecta més de 500 ha.', null, '5d7e8bc04eaff6cee3ce0ac8dfe84ccf780634219b6fd4912d1fb4c67057c2a9', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '5d7e8bc04eaff6cee3ce0ac8dfe84ccf780634219b6fd4912d1fb4c67057c2a9')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Quan afecta més de 10 ha.', false), ('B', 'Quan dura més de 24 hores.', false), ('C', 'Quan hi intervenen mitjans aeris.', false), ('D', 'Quan afecta més de 500 ha o supera de manera sostinguda la capacitat dels sistemes d''extinció.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
