with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el CPS, quan es produeix un canvi «a pitjor» (pels bombers) en l''alineació de forces?', 'El canvi a millor és el contrari: menys pendent, més ombra o protecció del vent.', 'bomb_t25_incendis_forestals', (select id from public.topics where slug = 'bomb-t25-incendis-forestals'), 3, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-25-MAN.INVE.000.pdf'), 'MAN.INVE.000, § canvi a pitjor', 'Canvi a pitjor (pels bombers): el foc entra en una zona amb més exposició solar, pendent positiva o vent frontal → risc de salt, capell o flameig sobtat.', null, 'c1862da259a9f03bbe51c81ae774e2ebed38045c3cbc69a394518d0817e054e5', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'c1862da259a9f03bbe51c81ae774e2ebed38045c3cbc69a394518d0817e054e5')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Quan el foc entra en una zona amb menys pendent i més ombrívola.', false), ('B', 'Quan el vent deixa de bufar.', false), ('C', 'Quan el foc entra en una zona amb més exposició solar, pendent positiva o vent frontal.', true), ('D', 'Quan el foc arriba a la cua.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
