  select 'Segons el CPS, quan suma +1 el factor orientació?', 'Orientació calenta +1; foc pujant pendent +1; vent a favor del front +1.', 'bomb_t25_incendis_forestals', (select id from public.topics where slug = 'bomb-t25-incendis-forestals'), 3, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-25-MAN.INVE.000.pdf'), 'MAN.INVE.000, § orientació calenta', '→ Quan l’orientació és “calenta” (solell, especialment al migdia), +1.', null, '44718939924b6e3348edfda10015c6eaac21ee1e2df8d0b1cad38189ca9d55b7', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '44718939924b6e3348edfda10015c6eaac21ee1e2df8d0b1cad38189ca9d55b7')
