  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual d''intervenció bàsica en incendis forestals, què és un conat d''incendi?', 'Per sobre d''una hectàrea es parla d''incendi forestal, i de GIF si supera la capacitat d''extinció, afecta greument la població o passa de 500 ha.', 'bomb_t25_incendis_forestals', (select id from public.topics where slug = 'bomb-t25-incendis-forestals'), 1, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-25-MAN.INVE.000.pdf'), 'MAN.INVE.000, § 2.5 Classificació per afectació', 'Conat d’incendi: Incendi de vegetació que no supera una hectàrea d’extensió.', null, '1bbf8d2c3e6ebd910b171fa76a92ac43169a0b834d69067dc3e5533e6343f2c6', false
