  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Les herbes, matolls i fullaraca sobre el sòl.', false), ('B', 'La part superior dels arbres.', false), ('C', 'Només els cultius de cereal sec.', false), ('D', 'La matèria orgànica situada sota la superfície del sòl: arrels, humus i restes vegetals acumulades.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
