with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual d''intervenció bàsica en incendis forestals, quin és l''objectiu de l''etapa de remat?', 'Frenar la propagació és l''etapa d''atac i la vigilància amb patrulles és la rereguarda; una rematada deficient és la causa més habitual de represes.', 'bomb_t25_incendis_forestals', (select id from public.topics where slug = 'bomb-t25-incendis-forestals'), 1, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-25-MAN.INVE.000.pdf'), 'MAN.INVE.000, § 4.4.2 Etapa de remat', 'Un cop el foc ja està controlat comença l’etapa de rematada, que té com a objectiu eliminar tots els focus calents i restes actives dins del perímetre per assegurar que l’incendi no es reactivi.', null, '71e71d129761250771a385d525d083cb94ce093bc7db19a10df3b6811a81fc82', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '71e71d129761250771a385d525d083cb94ce093bc7db19a10df3b6811a81fc82')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Frenar la propagació activa del foc i aconseguir punts d''ancoratge.', false), ('B', 'Eliminar tots els focus calents i restes actives dins del perímetre perquè l''incendi no es reactivi.', true), ('C', 'Vigilar el perímetre amb patrulles mòbils fins que es doni per extingit.', false), ('D', 'Encendre contrafocs per competir pel combustible.', false)) as v(label, body, ok)
)
