with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual d''intervenció bàsica en incendis forestals, què caracteritza l''atac paral·lel o indirecte?', 'L''atac directe treballa sobre el front de flames; l''indirecte, per exemple, amb línies de defensa, foc tècnic o maquinària.', 'bomb_t25_incendis_forestals', (select id from public.topics where slug = 'bomb-t25-incendis-forestals'), 1, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-25-MAN.INVE.000.pdf'), 'MAN.INVE.000, § 4 Maniobres d''extinció', 'Atac paral·lel o indirecte, quan s’actua sobre el combustible (la vegetació no cremada) per frenar l’avanç del foc.', null, '1ff27aa2c9119125d6c7722d0b68d506164d0f2ddd4886eb769ef1ef12c38961', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '1ff27aa2c9119125d6c7722d0b68d506164d0f2ddd4886eb769ef1ef12c38961')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'S''actua sobre el combustible no cremat per frenar l''avanç del foc.', true), ('B', 'Es treballa directament sobre el front de flames amb aigua.', false), ('C', 'Només s''utilitzen motxilles d''aigua i batefocs sobre les flames.', false), ('D', 'Consisteix a apagar la cua amb mitjans aeris.', false)) as v(label, body, ok)
)
