with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual d''intervenció bàsica en incendis forestals, quina generació d''incendis es caracteritza per l''aparició de la problemàtica de la interfase urbana-forestal?', 'La primera respon a la continuïtat del combustible, la segona a la velocitat de propagació i la sisena a incendis extremadament intensos i poc previsibles.', 'bomb_t25_incendis_forestals', (select id from public.topics where slug = 'bomb-t25-incendis-forestals'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-25-MAN.INVE.000.pdf'), 'MAN.INVE.000, § 1.4 Generacions d''incendis', 'Quarta generació (2000-2010): Sorgeix la problemàtica de la interfase urbana-forestal. Els incendis amenacen directament habitatges i infraestructures.', null, 'a6801990ebe2847986957f23543fffbe7874c4d962ef50330562438ae62a9a69', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'a6801990ebe2847986957f23543fffbe7874c4d962ef50330562438ae62a9a69')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La primera generació (anys 1950 a 1970).', false), ('B', 'La segona generació (1970-1980).', false), ('C', 'La quarta generació (2000-2010).', true), ('D', 'La sisena generació (a partir de 2016).', false)) as v(label, body, ok)
)
