with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual d''intervenció bàsica en incendis forestals, quan es va crear el GRAF (Grup de Recolzament d''Actuacions Forestals)?', 'El 1982 es crea el Cos, el 1986 neixen les ADF i el 2006 es regula l''ús del foc com a eina de gestió.', 'bomb_t25_incendis_forestals', (select id from public.topics where slug = 'bomb-t25-incendis-forestals'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-25-MAN.INVE.000.pdf'), 'MAN.INVE.000, § 1.5 El GRAF', 'El Grup de Recolzament d''Actuacions Forestals (GRAF) és una unitat d’especialistes en incendis forestals creada l’1 de març del 1999 per la Direcció General de Prevenció, Extinció d’Incendis i Salvaments, arran de la necessitat de reforçar la resposta operativa als grans incendis forestals que s’havien anat produint al país, especialment després del gran incendi de la Catalunya Central del 1998.', null, '548ae01d93e69d258c71275f4ec336cde35b685233b0d8cdccce294b8a6ac71d', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '548ae01d93e69d258c71275f4ec336cde35b685233b0d8cdccce294b8a6ac71d')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El 1982, amb la institucionalització del Cos de Bombers.', false), ('B', 'El 1986, després de cremar-se més de 65.000 ha.', false), ('C', 'El 2006, amb la regulació de l''ús del foc tècnic.', false), ('D', 'L''1 de març de 1999, arran sobretot del gran incendi de la Catalunya Central del 1998.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual d''intervenció bàsica en incendis forestals, què és l''antorxeig?', 'El foc de capçades passiu crema superfície i capçades alhora; l''actiu, el més perillós, es propaga per les capçades de manera sostinguda.', 'bomb_t25_incendis_forestals', (select id from public.topics where slug = 'bomb-t25-incendis-forestals'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-25-MAN.INVE.000.pdf'), 'MAN.INVE.000, § 2.4.3 Focs de capçades', 'Antorxeig: És aquell en què el foc arriba esporàdicament a les capçades, però sense propagar-se de forma contínua entre arbres.', null, '7c11a95e22ce0854c388e2a59c4c6821634d7a4e2c64868ac5418ec515c95c35', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '7c11a95e22ce0854c388e2a59c4c6821634d7a4e2c64868ac5418ec515c95c35')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Quan el foc es propaga de forma sostinguda per les capçades, independentment del foc de superfície.', false), ('B', 'Quan el combustible superficial i les capçades cremen alhora.', false), ('C', 'Quan el foc crema arrels i humus sota el sòl.', false), ('D', 'Quan el foc arriba esporàdicament a les capçades, sense propagar-se de forma contínua entre arbres.', true)) as v(label, body, ok)
)
