with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual d''intervenció bàsica en incendis forestals, sobre els retardants i els escumògens, indica la resposta INCORRECTA:', 'El manual diu que els escumògens tenen un efecte de curta durada; la persistència és pròpia dels retardants.', 'bomb_t25_incendis_forestals', (select id from public.topics where slug = 'bomb-t25-incendis-forestals'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-25-MAN.INVE.000.pdf'), 'MAN.INVE.000, § 4.2.3 Retardants i escumes', 'Els retardants són productes químics (principalment fosfats amònics) que, afegits a l’aigua, en potencien les propietats extintores i mantenen part de la seva eficàcia fins i tot després de l’evaporació. […] Els escumògens, en canvi, tenen un efecte de curta durada: barrejats amb aigua, generen una escuma que envolta el combustible, l’aïlla de l’oxigen i afavoreix l’absorció d’humitat.', null, '99efa67a6b62713eaeb7ced8ae1340472e647dd661caea3909727db533c1d75b', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '99efa67a6b62713eaeb7ced8ae1340472e647dd661caea3909727db533c1d75b')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Els escumògens tenen un efecte de llarga durada, superior al dels retardants.', true), ('B', 'Els retardants són principalment fosfats amònics afegits a l''aigua.', false), ('C', 'Els retardants mantenen part de la seva eficàcia fins i tot després de l''evaporació.', false), ('D', 'L''escuma envolta el combustible i l''aïlla de l''oxigen.', false)) as v(label, body, ok)
)
