  select 'Segons el manual d''intervenció bàsica en incendis forestals, què pot indicar una columna de fum partida?', 'La columna vertical indica poc vent; la difusa, foc feble; la blanca, combustió de matèria verda o humida.', 'bomb_t25_incendis_forestals', (select id from public.topics where slug = 'bomb-t25-incendis-forestals'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-25-MAN.INVE.000.pdf'), 'MAN.INVE.000, § 3.2.1 Columna de fum', 'Una columna partida, pot indicar vents canviants o la presència d’inestabilitat atmosfèrica (com pot ser una tempesta propera).', null, 'b4fce642000eafcd881fb116da3bc77ce161824f9db03f6f1bebc9e28e7b1a06', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'b4fce642000eafcd881fb116da3bc77ce161824f9db03f6f1bebc9e28e7b1a06')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Que l''efecte del vent és escàs.', false), ('B', 'Que el foc és feble.', false), ('C', 'Combustió de matèries verdes o humides.', false), ('D', 'Vents canviants o inestabilitat atmosfèrica, com una tempesta propera.', true)) as v(label, body, ok)
)
