with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Per fer l''anàlisi d''un incendi forestal, s''estima que la zona cremada és aproximadament un rectangle de 800 m × 50 m. Quina superfície cal anotar, segons l''equivalència del manual?', '800 m × 50 m = 40.000 m²; 40.000 / 10.000 = 4 ha.', 'bomb_t25_incendis_forestals', (select id from public.topics where slug = 'bomb-t25-incendis-forestals'), 3, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-25-MAN.INVE.000.pdf'), 'MAN.INVE.000, § Fitxa d''anàlisi (superfície)', 'Equivalència: 1 hectàrea (ha) = 10.000 m 2', null, '51932a125bd504550025a54ba7e8f3289a1ed2baaaf0f59252b60f7d365fff88', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '51932a125bd504550025a54ba7e8f3289a1ed2baaaf0f59252b60f7d365fff88')
  returning id
), o as (
