with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual d''intervenció bàsica en incendis forestals, quina maniobra de foc tècnic consisteix a encendre un nou front perquè avanci contra l''incendi principal i competeixin pel mateix combustible?', 'La crema d''eixamplament elimina el combustible entre un ancoratge i el front; la definició de perímetre en simplifica el traçat; l''obertura de caixa es fa amb eines, no amb foc.', 'bomb_t25_incendis_forestals', (select id from public.topics where slug = 'bomb-t25-incendis-forestals'), 3, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-25-MAN.INVE.000.pdf'), 'MAN.INVE.000, § 4.2.2 Foc tècnic', 'Contrafoc: És una maniobra de foc tècnic que consisteix a encendre un nou front de foc perquè avanci contra l’incendi principal, de manera que tots dos competeixin pel mateix combustible i redueixin la intensitat del foc original.', null, '42f072102b3084cab7dcac73cfe3a7e561248b9807a75c99a3f8794b11456970', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '42f072102b3084cab7dcac73cfe3a7e561248b9807a75c99a3f8794b11456970')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La crema d''eixamplament.', false), ('B', 'El contrafoc.', true), ('C', 'La maniobra de definició de perímetre.', false), ('D', 'L''obertura de caixa.', false)) as v(label, body, ok)
)
