with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual d''intervenció bàsica en incendis forestals, com ha evolucionat el significat de la lletra A del protocol LACES després de diversos accidents?', 'S''hi vol remarcar la necessitat d''una observació i comunicació constants.', 'bomb_t25_incendis_forestals', (select id from public.topics where slug = 'bomb-t25-incendis-forestals'), 3, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-25-MAN.INVE.000.pdf'), 'MAN.INVE.000, § 5.3 Consciència de situació', 'No és casualitat que, després de diversos accidents, la lletra A del LACES hagi evolucionat d’“Ancoratge” a “Ancoratge i Awareness” (consciència de situació), posant en relleu la necessitat d’una observació i comunicació constants.', null, '3a2b22089f6140649534b2fc5c7abdd9d03546fee1487aed356ec950ed4f9d76', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '3a2b22089f6140649534b2fc5c7abdd9d03546fee1487aed356ec950ed4f9d76')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'D''«Ancoratge» a «Ancoratge i Awareness» (consciència de situació).', true), ('B', 'D''«Aire» a «Aeronaus».', false), ('C', 'D''«Alerta» a «Autoprotecció».', false), ('D', 'D''«Ancoratge» a «Atac directe».', false)) as v(label, body, ok)
)
