with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual d''intervenció bàsica en incendis forestals, quina conseqüència va tenir l''estiu de 1986, en què es van cremar més de 65.000 ha a Catalunya?', 'El programa Foc Verd es crea el 1994, el GRAF el 1999 i la regulació de l''ús del foc tècnic és del 2006.', 'bomb_t25_incendis_forestals', (select id from public.topics where slug = 'bomb-t25-incendis-forestals'), 3, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-25-MAN.INVE.000.pdf'), 'MAN.INVE.000, § 1.1 Evolució històrica', '1986: Es cremen més de 65.000 ha – naixement de les ADF Un estiu catastròfic revela la necessitat de millora en els recursos i coordinació en l’àmbit forestal. Aquesta crisi dona lloc a la creació de les Agrupacions de Defensa Forestal (ADF)', null, '6a04b542341d42d52c57dad1ffdc9278789d2660d8b9b811b58d8c740ca84eb7', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '6a04b542341d42d52c57dad1ffdc9278789d2660d8b9b811b58d8c740ca84eb7')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La creació del programa Foc Verd.', false), ('B', 'La creació del GRAF.', false), ('C', 'La creació de les Agrupacions de Defensa Forestal (ADF).', true), ('D', 'La legalització de les cremes prescrites.', false)) as v(label, body, ok)
)
