with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual d''intervenció bàsica en incendis forestals, com es comporta el foc a prop d''una tempesta que encara s''està formant?', 'Els corrents descendents que projecten vents cap a fora corresponen al moment en què la tempesta comença a descarregar.', 'bomb_t25_incendis_forestals', (select id from public.topics where slug = 'bomb-t25-incendis-forestals'), 3, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-25-MAN.INVE.000.pdf'), 'MAN.INVE.000, § 3.1.4 Tempesta propera', 'Quan la tempesta encara s’està formant, els vents tendeixen a entrar cap al nucli tempestuós, de manera que el foc pot ser “atret” cap a la tempesta.', null, '5c57ad4c66b066e6f33db8c47b4684493441052e124e650fc08c52a52db83232', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '5c57ad4c66b066e6f33db8c47b4684493441052e124e650fc08c52a52db83232')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Els corrents descendents projecten els vents cap a fora en múltiples direccions.', false), ('B', 'El vent desapareix i la columna es fa vertical.', false), ('C', 'La pluja extingeix el front en pocs minuts.', false), ('D', 'Els vents tendeixen a entrar cap al nucli tempestuós i el foc pot ser «atret» cap a la tempesta.', true)) as v(label, body, ok)
)
