  select 'Segons el manual d''incendis varis, quin risc comporta el foc en somort al fons d''un contenidor?', 'Cal remoure bé el contingut i refredar-lo.', 'bomb_t26_incendis_diversos', (select id from public.topics where slug = 'bomb-t26-incendis-diversos'), 3, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.INXX.000-Tema-26-Prevencio-incendis-varis.pdf'), 'MAN.INXX.000, § foc en somort', 'Foc en somort: la combustió lenta al fons del contenidor pot mantenir brases actives fins i tot després de l’extinció aparent, amb risc de reignició hores més tard si no es remou bé el contingut i es refreda adequadament.', null, 'c97be1696c094b489169dc86121b6a16d7679e15507cdd4b97ce0032390cb188', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'c97be1696c094b489169dc86121b6a16d7679e15507cdd4b97ce0032390cb188')
  returning id
), o as (
