  select 'Segons el manual d''intervenció bàsica en riscos NRBQ, per què no es poden fer servir els vestits antiesquitxos en atmosferes amb gasos tòxics concentrats?', 'Són equips de tipus 3 o 4 que eviten la penetració de líquids; tampoc no tenen protecció tèrmica.', 'bomb_t27_riscos_nrbq', (select id from public.topics where slug = 'bomb-t27-riscos-nrbq'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.RRTT.000-Tema-27.-Intervencio-NRBQ.pdf'), 'MAN.RRTT.000, § 5.5.1 Vestits antiesquitxos', 'Són equips de protecció química de tipus 3 o 4 segons la norma EN 465. No són estancs al gas ni pressuritzats, per això no es poden fer servir en atmosferes amb gasos tòxics concentrats.', null, '61e56c3726289358ab8f76de71f8fdf9c8e3cae552b45f3276bc405a25c15e05', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '61e56c3726289358ab8f76de71f8fdf9c8e3cae552b45f3276bc405a25c15e05')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Perquè són de tipus 1 ET i s''han de reservar.', false), ('B', 'Perquè tenen massa protecció tèrmica.', false), ('C', 'Perquè només protegeixen de la radiació.', false), ('D', 'Perquè no són estancs al gas ni pressuritzats.', true)) as v(label, body, ok)
)
