  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual d''intervenció bàsica en riscos NRBQ, quin tipus de vestit estanc a gasos s''utilitza específicament per als equips d''emergència?', 'Els tipus 1a, 1b i 1c (EN 943-1) són per a treballadors de la indústria química, no per als equips de bombers; els tipus 3 i 4 són antiesquitxos.', 'bomb_t27_riscos_nrbq', (select id from public.topics where slug = 'bomb-t27-riscos-nrbq'), 3, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.RRTT.000-Tema-27.-Intervencio-NRBQ.pdf'), 'MAN.RRTT.000, § 5.5.2 Vestits NRBQ estancs a gasos', 'Per als equips d’emergència s’utilitzen específicament els vestits de Tipus 1 (ET), segons la norma europea EN 943-2.', null, '82c5677d9b55ce0695312fca2fc3d469de5c2e9f279e9af2ba91e2cfb68c62d6', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '82c5677d9b55ce0695312fca2fc3d469de5c2e9f279e9af2ba91e2cfb68c62d6')
  returning id
