  select 'Segons el manual d''intervenció bàsica en assistència sanitària, quin és l''objectiu principal de l''assistència sanitària en emergències?', 'Es tracta d''atenció immediata d''urgència amb risc vital o potencial compromís funcional.', 'bomb_t28_assistencia_sanitaria', (select id from public.topics where slug = 'bomb-t28-assistencia-sanitaria'), 1, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SANI.000-Tema-28.-Assistencia-sanitaria.pdf'), 'MAN.SANI.000, § objectiu', 'L’objectiu principal és preservar la vida, estabilitzar les funcions vitals i facilitar la transferència segura del pacient fins a l’atenció definitiva.', null, '5ea6f5c40dc6935fcd16740984658aaae615b32edd0fe423da1f4924934fad32', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '5ea6f5c40dc6935fcd16740984658aaae615b32edd0fe423da1f4924934fad32')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Diagnosticar definitivament la malaltia del pacient.', false), ('B', 'Preservar la vida, estabilitzar les funcions vitals i facilitar la transferència segura fins a l''atenció definitiva.', true), ('C', 'Substituir l''atenció hospitalària.', false), ('D', 'Traslladar sempre el pacient pels propis mitjans.', false)) as v(label, body, ok)
)
