  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual d''assistència sanitària, amb quina profunditat i freqüència s''han de fer les compressions toràciques en la RCP d''un adult?', 'Les compressions es fan al centre del tòrax, a la meitat inferior de l''estèrnum, amb 5-6 cm de profunditat i 100-120 per minut, permetent la reexpansió completa.', 'bomb_t28_assistencia_sanitaria', (select id from public.topics where slug = 'bomb-t28-assistencia-sanitaria'), 1, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SANI.000-Tema-28.-Assistencia-sanitaria.pdf'), 'MAN.SANI.000, § 4.5 RCP', 'Consisteix en compressions toràciques rítmiques al centre del tòrax, meitat inferior de l’estèrnum, amb una profunditat de 5-6 cm i una freqüència de 100-120 compressions per minut.', null, '6ced8356eff9ba8207318937f5017ca0a0c4b06c0a1a11b0a525a530725a0e61', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '6ced8356eff9ba8207318937f5017ca0a0c4b06c0a1a11b0a525a530725a0e61')
  returning id
