  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual d''assistència sanitària, si es disposa de material, quina relació de compressions i ventilacions s''ha d''alternar en la RCP d''un adult?', 'La seqüència és 30:2; si no es poden fer ventilacions, es mantenen compressions toràciques contínues.', 'bomb_t28_assistencia_sanitaria', (select id from public.topics where slug = 'bomb-t28-assistencia-sanitaria'), 1, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SANI.000-Tema-28.-Assistencia-sanitaria.pdf'), 'MAN.SANI.000, § 4.5 RCP 30:2', 'Si es disposa de material, s’ha d’alternar 30 compressions amb 2 ventilacions. Quan no sigui possible fer ventilacions, s’han de mantenir compressions toràciques contínues.', null, 'c3888d4c2bcced3558737c1a6b2eefbdd7c5f3e48735096acc33e335e6bb29b8', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'c3888d4c2bcced3558737c1a6b2eefbdd7c5f3e48735096acc33e335e6bb29b8')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', '15 compressions i 2 ventilacions.', false), ('B', '5 compressions i 1 ventilació.', false), ('C', '30 compressions i 5 ventilacions.', false), ('D', '30 compressions i 2 ventilacions.', true)) as v(label, body, ok)
)
