with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual d''assistència sanitària, com s''ha d''aplicar un torniquet davant una hemorràgia d''extremitat que posa en perill la vida i no es controla amb pressió directa?', 'El torniquet es posa tan aviat com sigui possible, a uns 5 cm de la ferida; si cal, per sobre de l''articulació, i sempre s''anota l''hora.', 'bomb_t28_assistencia_sanitaria', (select id from public.topics where slug = 'bomb-t28-assistencia-sanitaria'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SANI.000-Tema-28.-Assistencia-sanitaria.pdf'), 'MAN.SANI.000, § 4.1 torniquet', 'El torniquet ha d’aplicar-se el més a prop possible (5cm) de la ferida, mai sobre una articulació (si cal es farà per sobre de l’articulació) i cal registrar l’hora d’aplicació.', null, 'bce6758cde0683ab13e4595e451c3968dcce5746c22b2c7983ae82f8de54f6f5', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'bce6758cde0683ab13e4595e451c3968dcce5746c22b2c7983ae82f8de54f6f5')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Tan lluny com sigui possible de la ferida, a l''arrel de l''extremitat, sense necessitat d''anotar l''hora.', false), ('B', 'Directament sobre l''articulació més propera per tenir un punt ferm.', false), ('C', 'El més a prop possible de la ferida (5 cm), mai sobre una articulació, i registrant l''hora d''aplicació.', true), ('D', 'Només després d''haver elevat l''extremitat i comprimit l''artèria proximal durant 10 minuts.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
