  select 'Una persona adulta conscient s''ennuega i no pot estossegar o ho fa de manera molt dèbil. Segons el manual d''assistència sanitària, què cal fer primer?', 'Si l''obstrucció és parcial i pot estossegar, s''encoratja a fer-ho; si no pot, 5 cops interescapulars i després 5 compressions abdominals, alternant-los.', 'bomb_t28_assistencia_sanitaria', (select id from public.topics where slug = 'bomb-t28-assistencia-sanitaria'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SANI.000-Tema-28.-Assistencia-sanitaria.pdf'), 'MAN.SANI.000, § 4.3 OVACE', 'Si la persona no pot estossegar o ho fa de manera molt dèbil. Donar 5 cops interescapulars amb el taló de la mà entre les espatlles', null, 'c91fcfdba5abe7ae440a2fce099e9050b09894a1935e29ad72d423427e9476db', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'c91fcfdba5abe7ae440a2fce099e9050b09894a1935e29ad72d423427e9476db')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Donar 5 cops interescapulars amb el taló de la mà entre les espatlles.', true), ('B', 'Encoratjar-la a seguir estossegant sense fer cap altra maniobra.', false), ('C', 'Iniciar immediatament la RCP 30:2.', false), ('D', 'Fer escombrades a cegues amb el dit dins la boca.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual d''assistència sanitària, quina maniobra de desobstrucció de la via aèria es fa en un lactant (menor d''un any)?', 'En lactants no es fan compressions abdominals.', 'bomb_t28_assistencia_sanitaria', (select id from public.topics where slug = 'bomb-t28-assistencia-sanitaria'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SANI.000-Tema-28.-Assistencia-sanitaria.pdf'), 'MAN.SANI.000, § 4.3 OVACE en lactants', 'En lactants (menors d’un any) es combinen 5 copets interescapulars i 5 compressions toràciques, no es fan compressions abdominals.', null, '5f89aad12fa8622f2d23ff3e898ca6dd486690b66b9559e80523233170e110aa', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '5f89aad12fa8622f2d23ff3e898ca6dd486690b66b9559e80523233170e110aa')
