  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Qualsevol incident amb més de dues víctimes.', false), ('B', 'Una catàstrofe que afecta una regió sencera.', false), ('C', 'Una situació d''emergència que desborda la capacitat assistencial local.', true), ('D', 'Un accident de trànsit amb un sol vehicle.', false)) as v(label, body, ok)
)
