  select 'Segons el manual d''IMV, quin és l''objectiu del triatge?', 'Es determina qui necessita atenció immediata, qui pot esperar i qui no té possibilitat real de supervivència.', 'bomb_t29_multiples_victimes', (select id from public.topics where slug = 'bomb-t29-multiples-victimes'), 1, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-29-MAN.SANI.001.pdf'), 'MAN.SANI.001, § objectiu del triatge', 'L’objectiu del triatge és obtenir el màxim benefici possible per al major nombre de persones, establint qui ha de rebre atenció immediata, qui pot esperar, i qui, malauradament, no té cap possibilitat real de supervivència.', null, '24a635a728a04213fc9317757bdfffcb0b6d4e548654589201c677a8a0a75c25', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '24a635a728a04213fc9317757bdfffcb0b6d4e548654589201c677a8a0a75c25')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Obtenir el màxim benefici possible per al major nombre de persones.', true), ('B', 'Atendre primer les víctimes que criden més.', false), ('C', 'Atendre les víctimes per ordre d''arribada.', false), ('D', 'Evacuar primer els lleus.', false)) as v(label, body, ok)
)
