  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'En un IMV per un atemptat amb explosiu, segons el manual d''IMV, quan poden accedir els Bombers al primer cercle de seguretat?', 'Amb sospita d''il·lícit penal, el comandament operatiu recau en el cos policial, que controla la causa del risc i busca explosius secundaris.', 'bomb_t29_multiples_victimes', (select id from public.topics where slug = 'bomb-t29-multiples-victimes'), 3, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-29-MAN.SANI.001.pdf'), 'MAN.SANI.001, § 4.2.1 il·lícit penal', 'Els Bombers només poden accedir a el primer cercle de seguretat quan la policia l’autoritza, i en les condicions de seguretat establertes.', null, '56867dd4344af0c3b342fa5aee0c1dff06f895b19579ded52e9697d003985906', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '56867dd4344af0c3b342fa5aee0c1dff06f895b19579ded52e9697d003985906')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Immediatament, perquè el rescat de víctimes té prioritat sobre la seguretat.', false), ('B', 'Quan ho decideix el cap de la dotació dels Bombers després de valorar l''escenari.', false), ('C', 'Quan la policia ho autoritza i en les condicions de seguretat establertes.', true), ('D', 'Només quan ho autoritza el SEM des de l''Àrea sanitària.', false)) as v(label, body, ok)
)
