with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual d''intervenció bàsica en estructures col·lapsades, què és un col·lapse estructural?', 'L''element deixa de complir la funció portadora.', 'bomb_t30_estructures_collapsades', (select id from public.topics where slug = 'bomb-t30-estructures-collapsades'), 1, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-30-MAN.SVES.000.pdf'), 'MAN.SVES.000, § col·lapse estructural', 'Valoració del col·lapse estructural Un col·lapse estructural és la fallida sobtada o progressiva d’una construcció quan algun dels seus elements estructurals –com ara forjats, murs, pilars o cobertes– supera el seu límit resistent o elàstic, deixant de complir la seva funció portadora.', null, '50a118cd4fb359d6b140acf50b6effafbe43f3f89f386124f4ba53debaba1952', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '50a118cd4fb359d6b140acf50b6effafbe43f3f89f386124f4ba53debaba1952')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Qualsevol esquerda visible en una façana.', false), ('B', 'La fallida sobtada o progressiva d''una construcció quan algun element supera el seu límit resistent o elàstic.', true), ('C', 'La demolició controlada d''un edifici.', false), ('D', 'La caiguda d''un element no estructural sense afectació.', false)) as v(label, body, ok)
)
