  select 'Segons el manual d''estructures col·lapsades, quina condició ha de complir l''equip SOS mentre està assignat?', 'L''equip SOS ha d''estar equipat, amb accés ràpid a eines de rescat i coneixement de les rutes d''evacuació, preparat per si algun membre queda atrapat.', 'bomb_t30_estructures_collapsades', (select id from public.topics where slug = 'bomb-t30-estructures-collapsades'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-30-MAN.SVES.000.pdf'), 'MAN.SVES.000, § 6.1 equip SOS', 'Aquest equip ha d’estar degudament equipat, amb accés ràpid a eines de rescat i coneixement de les rutes d’evacuació, i no ha de tenir cap altra funció operativa mentre estigui assignat com a equip de suport d’emergència.', null, '258284ec356abe1e9964c0bafcce72daa6315dd10b1b3ee16896fa3539f42e8f', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '258284ec356abe1e9964c0bafcce72daa6315dd10b1b3ee16896fa3539f42e8f')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Ha de col·laborar en el desenrunament quan no hi hagi incidents.', false), ('B', 'Ha de fer també de guaita de l''estructura.', false), ('C', 'No ha de tenir cap altra funció operativa.', true), ('D', 'Ha d''estar situat a la zona freda sense material de rescat.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual d''estructures col·lapsades, què significa l''Ancoratge en el protocol LACES?', 'Aquest punt serveix de referència per a la traçabilitat de l''equip.', 'bomb_t30_estructures_collapsades', (select id from public.topics where slug = 'bomb-t30-estructures-collapsades'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-30-MAN.SVES.000.pdf'), 'MAN.SVES.000, § 6.4 LACES (Ancoratge)', 'Ancoratge: Establir un punt d’entrada controlat i identificable. Aquest punt serveix de referència per a la traçabilitat de l’equip i per assegurar que tothom que entra a la zona perillosa està registrat i en contacte amb el dispositiu de comandament.', null, '9fb65d2e552b504406adae3d27f32cd6c21bdc78e9f1982da3c0a83a121c2c9b', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '9fb65d2e552b504406adae3d27f32cd6c21bdc78e9f1982da3c0a83a121c2c9b')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Fixar amb cordes l''estructura col·lapsada.', false), ('B', 'Assegurar els intervinents amb arnès a un punt fix.', false), ('C', 'Establir un punt d''entrada controlat i identificable on es registra qui entra a la zona perillosa.', true), ('D', 'Ancorar els vehicles amb falques en carrers amb pendent.', false)) as v(label, body, ok)
)
