  select 'Segons el manual d''estructures col·lapsades, en quantes categories estan classificats els equips certificats sota l''INSARAG?', 'La classificació es fa segons la capacitat operativa.', 'bomb_t30_estructures_collapsades', (select id from public.topics where slug = 'bomb-t30-estructures-collapsades'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-30-MAN.SVES.000.pdf'), 'MAN.SVES.000, § 1.2 categories INSARAG', 'Estan classificats en tres categories (lleugers, mitjans i pesats) segons la seva capacitat operativa.', null, 'e5784e48ff3cb56c827a3e4f3b78bcf0c4e17b113b49464e1afbf33dedfcdcf2', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'e5784e48ff3cb56c827a3e4f3b78bcf0c4e17b113b49464e1afbf33dedfcdcf2')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'En dues: nacionals i internacionals.', false), ('B', 'En tres: lleugers, mitjans i pesats.', true), ('C', 'En quatre: bàsics, intermedis, avançats i experts.', false), ('D', 'En cinc, segons el nombre de gossos de recerca.', false)) as v(label, body, ok)
)
