with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual d''estructures col·lapsades, quins patrons sistemàtics es poden seguir en la recerca física?', 'La recerca física es basa en la vista i l''oïda dels bombers i no requereix equipament especialitzat.', 'bomb_t30_estructures_collapsades', (select id from public.topics where slug = 'bomb-t30-estructures-collapsades'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-30-MAN.SVES.000.pdf'), 'MAN.SVES.000, § 3.1 patrons de recerca física', 'Aquesta recerca pot dur-se a terme seguint patrons sistemàtics com l’avanç en línia, els cercles concèntrics o el patró en habitacions múltiples, segons la configuració de l’espai i l’abast del col·lapse.', null, '980717d1444d48e4896a28a86b3ff489bea746064d7127d1cb869551459a7829', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '980717d1444d48e4896a28a86b3ff489bea746064d7127d1cb869551459a7829')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El venteig i el rastreig.', false), ('B', 'Els geòfons i les càmeres.', false), ('C', 'El marcatge amb V i X.', false), ('D', 'L''avanç en línia, els cercles concèntrics o el patró en habitacions múltiples.', true)) as v(label, body, ok)
)
