with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Cal apuntalar un forjat que suporta una càrrega estimada de 5.000 kg. Segons els criteris bàsics d''apuntalament dels Bombers de la Generalitat, quin és el nombre mínim de puntals que cal col·locar?', 'Cada puntal té una resistència màxima de 1.000 kg: 5.000 kg / 1.000 kg per puntal = 5 puntals com a mínim (sense superar 1 m entre puntals).', 'bomb_t30_estructures_collapsades', (select id from public.topics where slug = 'bomb-t30-estructures-collapsades'), 3, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-30-MAN.SVES.000.pdf'), 'MAN.SVES.000, § 4 resistència del puntal', 'Es considera que un puntal té una resistència màxima de 1.000 kg.', null, 'ef240a30230a2ceee05b15dc7888abe14005d934527b63fda0ba97e28f7df398', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'ef240a30230a2ceee05b15dc7888abe14005d934527b63fda0ba97e28f7df398')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', '5 puntals.', true), ('B', '2 puntals.', false), ('C', '10 puntals.', false), ('D', '50 puntals.', false)) as v(label, body, ok)
)
