with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual d''estructures col·lapsades, què indica el senyal acústic d''1 toc llarg seguit d''1 toc curt?', 'El so pot provenir d''un xiulet, una sirena o un martell metàl·lic; tots els intervinents han de conèixer els senyals.', 'bomb_t30_estructures_collapsades', (select id from public.topics where slug = 'bomb-t30-estructures-collapsades'), 3, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-30-MAN.SVES.000.pdf'), 'MAN.SVES.000, § 6.5 senyals acústics (represa)', '1 toc llarg + 1 toc curt: Reprenem les operacions, situació estabilitzada.', null, '4eab97237fb28acde4b3ffe2e1fb495593b2486f000aa33b1821ce03f4e12552', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '4eab97237fb28acde4b3ffe2e1fb495593b2486f000aa33b1821ce03f4e12552')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Que es reprenen les operacions perquè la situació està estabilitzada.', true), ('B', 'Que cal evacuar immediatament la zona.', false), ('C', 'Que s''han d''aturar totes les operacions mantenint posicions.', false), ('D', 'Que un intervinent demana socors.', false)) as v(label, body, ok)
)
