with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons els criteris bàsics d''apuntalament dels Bombers de la Generalitat, indica la resposta INCORRECTA:', 'El manual diu expressament que no s''ha d''intentar restituir la posició de l''element danyat.', 'bomb_t30_estructures_collapsades', (select id from public.topics where slug = 'bomb-t30-estructures-collapsades'), 3, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-30-MAN.SVES.000.pdf'), 'MAN.SVES.000, § 4 criteris d''apuntalament', 'Cal evitar les vibracions i els puntals s’han d’entrar en càrrega de manera uniforme. […] No intentar restituir la posició de l’element danyat. […] Mantenir una via d’escapament neta d’obstacles. […] Dins la zona afectada s’hi estarà el temps i personal imprescindible.', null, '4caf36a2538d7cb102b00ed86688498b93332dad80913263b716b23582d59dc1', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '4caf36a2538d7cb102b00ed86688498b93332dad80913263b716b23582d59dc1')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Els puntals s''han d''entrar en càrrega de manera uniforme, evitant les vibracions.', false), ('B', 'Cal mantenir una via d''escapament neta d''obstacles.', false), ('C', 'Cal intentar restituir la posició original de l''element danyat.', true), ('D', 'Dins la zona afectada s''hi ha d''estar el temps i el personal imprescindible.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
