with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual d''estructures col·lapsades, quina certificació va començar el GREC l''any 2025?', 'El GREC es va constituir el 2021 com a subàmbit de la guàrdia de suport, format per bombers amb titulacions tècniques.', 'bomb_t30_estructures_collapsades', (select id from public.topics where slug = 'bomb-t30-estructures-collapsades'), 3, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-30-MAN.SVES.000.pdf'), 'MAN.SVES.000, § 1.3.1 certificació STRAC del GREC', 'L’any 2025, el GREC ha començat la seva certificació com a equip STRAC per formar part dels recursos que poden ser activats pel Mecanisme Europeu de Protecció Civil en emergències internacionals.', null, '2430e8ccd1fe94c9b2784a0086d5129b3b2ec2e230ed9f709c7ac1b062652cbf', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '2430e8ccd1fe94c9b2784a0086d5129b3b2ec2e230ed9f709c7ac1b062652cbf')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La d''equip USAR pesat de l''INSARAG.', false), ('B', 'La d''equip STRAC, per poder ser activat pel Mecanisme Europeu de Protecció Civil.', true), ('C', 'La de centre OSOCC de Nacions Unides.', false), ('D', 'La d''unitat canina de recerca en runa.', false)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
select q.id, b.id from q, public.exam_bodies b where b.slug in ('bombers-generalitat');
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual d''estructures col·lapsades, quina afirmació sobre les zones de Seguretat (refugi) del protocol LACES és correcta?', 'Poden ser espais reforçats amb apuntalaments previs, racons protegits per murs estructurals intactes o vehicles blindats; el punt d''entrada controlat és l''Ancoratge.', 'bomb_t30_estructures_collapsades', (select id from public.topics where slug = 'bomb-t30-estructures-collapsades'), 3, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-30-MAN.SVES.000.pdf'), 'MAN.SVES.000, § 6.4 LACES (refugi)', 'No substitueix l’evacuació, però permet guanyar temps […] Aquestes zones, tot i estar dins la zona calenta, han de ser considerades relativament estables, protegides d’un possible col·lapse secundari, i accessibles en pocs segons.', null, '981fbaf896cea0fac48f844502bf945d70593f4c7b87bb1bdeab18b782ee22a1', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '981fbaf896cea0fac48f844502bf945d70593f4c7b87bb1bdeab18b782ee22a1')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Se situen sempre a la zona freda, al costat del centre de comandament.', false), ('B', 'Substitueixen les rutes d''escapament quan aquestes són llargues.', false), ('C', 'Són els punts d''entrada controlats on es registra el personal.', false), ('D', 'Són dins la zona calenta, relativament estables i accessibles en pocs segons, però no substitueixen l''evacuació.', true)) as v(label, body, ok)
)
