  select 'Segons el manual de salvaments al medi natural, quin és l''objectiu del salvament?', 'Sovint requereix alta especialització per les condicions extremes.', 'bomb_t31_medi_natural_terrestre', (select id from public.topics where slug = 'bomb-t31-medi-natural-terrestre'), 1, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-31-MAN.SVMN.000.pdf'), 'MAN.SVMN.000, § objectiu', 'L’objectiu és garantir la localització, atenció, estabilització i evacuació de les persones afectades, minimitzant el risc per a tots els intervinents.', null, 'a4d6e42240efe46a127230e0d90cee03e72f8d762fe0674695c196747751f79c', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'a4d6e42240efe46a127230e0d90cee03e72f8d762fe0674695c196747751f79c')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
