  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual d''accidents de mobilitat, qui és l''únic que pot garantir que no circulin altres trens per la línia d''un accident ferroviari?', 'Cal confirmació oficial del tall de circulació i de la desconnexió de la tracció elèctrica.', 'bomb_t32_accidents_mobilitat_viaria', (select id from public.topics where slug = 'bomb-t32-accidents-mobilitat-viaria'), 1, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-32-MAN.SVVH.000.pdf'), 'MAN.SVVH.000, § centre de control ferroviari', 'Comunicació amb el centre de control ferroviari Un aspecte fonamental abans de començar qualsevol intervenció a la via és la coordinació amb el centre de control ferroviari, que és l’únic que pot garantir que no hi circulin altres trens per aquella línia.', null, '30ad1a70656bbe1d7948c2e937909295da07647c5cb91a91b960794990b558ef', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '30ad1a70656bbe1d7948c2e937909295da07647c5cb91a91b960794990b558ef')
  returning id
), o as (
