  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual d''accidents de mobilitat, quin va ser l''any amb més accidentalitat de la dècada, amb més de 24.000 accidents amb víctimes?', 'El 2023 va tancar amb 23.591 accidents.', 'bomb_t32_accidents_mobilitat_viaria', (select id from public.topics where slug = 'bomb-t32-accidents-mobilitat-viaria'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-32-MAN.SVVH.000.pdf'), 'MAN.SVVH.000, § accidents 2019', 'L’any amb més accidentalitat va ser el 2019, superant els 24.000 accidents amb víctimes, mentre que el 2023 va tancar amb 23.591 accidents, una xifra lleugerament superior a la mitjana de la dècada.', null, '0c3e45772f8a0166652744b2e7b646fc564862ba47bb4be88fdda7c83bf8c583', false
