  select 'Segons el manual d''accidents de mobilitat viària, com es comporta un vidre temperat en trencar-se i on s''utilitza habitualment?', 'El vidre laminat és el que manté els fragments adherits i va als parabrises; el policarbonat és el termoplàstic difícil de trencar.', 'bomb_t32_accidents_mobilitat_viaria', (select id from public.topics where slug = 'bomb-t32-accidents-mobilitat-viaria'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-32-MAN.SVVH.000.pdf'), 'MAN.SVVH.000, § 2.1.1 vidres temperats', 'Vidres temperats: Tractats tèrmicament o químicament per augmentar la seva resistència, però en trencar-se es fragmenten en múltiples trossos petits. Es fan servir en finestretes i llunes posteriors.', null, 'f9181a5371ca63926065e07ccdcb8f5343158cdb97a85232771c1ad6ca875593', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'f9181a5371ca63926065e07ccdcb8f5343158cdb97a85232771c1ad6ca875593')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Es fragmenta en múltiples trossos petits; s''utilitza en finestretes i llunes posteriors.', true), ('B', 'Els fragments queden adherits a una làmina; s''utilitza en parabrises.', false), ('C', 'No es trenca, ja que és un termoplàstic; s''utilitza en sostres panoràmics.', false), ('D', 'Es fragmenta en grans làmines tallants; s''utilitza en parabrises.', false)) as v(label, body, ok)
)
