with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Després d''una col·lisió frontal d''alta energia, el conductor té les extremitats inferiors atrapades (atrapament físic tipus 2). Segons el manual d''accidents de mobilitat viària, quina maniobra d''excarceració és la indicada?', 'El desplaçament de volant separa el volant del tors, però no és útil si les extremitats inferiors estan atrapades.', 'bomb_t32_accidents_mobilitat_viaria', (select id from public.topics where slug = 'bomb-t32-accidents-mobilitat-viaria'), 3, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-32-MAN.SVVH.000.pdf'), 'MAN.SVVH.000, § 4.3 a) i b) volant i davantal', 'Descripció: Aquesta maniobra permet separar el volant i la columna de direcció del tors de la víctima, però no és útil en casos d’atrapament de les extremitats inferiors. […] Objectiu: Ampliar l’espai de l’habitacle en casos d’atrapament físic tipus 2 de les extremitats inferiors en víctimes situades als seients davanters del vehicle, especialment en col·lisions frontals d’alta energia.', null, '99b0d82a5c5f5515df09d85012d7c1fb70d6f2dda29f593ff21328299c8bbe0a', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '99b0d82a5c5f5515df09d85012d7c1fb70d6f2dda29f593ff21328299c8bbe0a')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El desplaçament de volant i columna de direcció.', false), ('B', 'El desplaçament de muntant B.', false), ('C', 'El desplaçament de davantal.', true), ('D', 'El desplaçament de sostre.', false)) as v(label, body, ok)
)
