with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Un turisme xoca a 100 km/h en lloc de fer-ho a 50 km/h. Aplicant la fórmula de l''energia cinètica del manual d''accidents de mobilitat viària, quantes vegades més energia porta al xoc?', 'Ec = ½·m·v²; si la velocitat es duplica, l''energia es multiplica per 2² = 4 (100/50 = 2; 2² = 4).', 'bomb_t32_accidents_mobilitat_viaria', (select id from public.topics where slug = 'bomb-t32-accidents-mobilitat-viaria'), 3, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-32-MAN.SVVH.000.pdf'), 'MAN.SVVH.000, § 3.2.6 a) energia cinètica', 'Analitzem la fórmula de l’energia cinètica: Ec = ½ m x V2', null, 'bea665e9f914dad88fed75aec63d26ad6df212e334ed0c7567fd77238381423e', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'bea665e9f914dad88fed75aec63d26ad6df212e334ed0c7567fd77238381423e')
  returning id
), o as (
