insert into public.topics (slug, title) values ('bomb-t33-rescat-urba', 'Tema 33. Intervenció bàsica en rescat urbà') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('bombers-generalitat') and t.slug = 'bomb-t33-rescat-urba' on conflict do nothing;
with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual d''intervenció bàsica en rescat urbà, el rescat urbà és tota actuació destinada a:', 'Inclou edificacions, espais confinats i elements d''infraestructura urbana.', 'bomb_t33_rescat_urba', (select id from public.topics where slug = 'bomb-t33-rescat-urba'), 1, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-33-MAN.SVXX.000.pdf'), 'MAN.SVXX.000, § rescat urbà', 'El rescat urbà és tota actuació destinada a localitzar, accedir, estabilitzar i evacuar persones que es troben atrapades o en situació de dificultat física o funcional dins d’un entorn construït (edificacions, espais confinats, elements d’infraestructura urbana, etc.), i que no poden resoldre la seva situació sense assistència externa.', null, 'e06a62af923a76ca2d460002b491a1914b7c421cfc4077d14734d6fd784cfd13', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'e06a62af923a76ca2d460002b491a1914b7c421cfc4077d14734d6fd784cfd13')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Extingir incendis en edificis.', false), ('B', 'Rescatar persones a la muntanya.', false), ('C', 'Retirar vehicles de la via pública.', false), ('D', 'Localitzar, accedir, estabilitzar i evacuar persones atrapades o en dificultat dins d''un entorn construït.', true)) as v(label, body, ok)
)
insert into public.question_exam_bodies (question_id, exam_body_id)
