with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Segons el manual de rescat urbà, quin accés s''ha de buscar sempre?', 'Cal valorar constantment el risc-benefici per als actuants i la víctima.', 'bomb_t33_rescat_urba', (select id from public.topics where slug = 'bomb-t33-rescat-urba'), 1, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-33-MAN.SVXX.000.pdf'), 'MAN.SVXX.000, § accés', 'En qualsevol dels casos, s’ha de buscar sempre l’accés més fàcil, segur i ràpid, evitant accions innecessàriament destructives i valorant constantment el risc-benefici per als actuants i la víctima.', null, '828b774de45d68bf808cf41cd2e0061c2790f788a7f16c4ec4987c4471292cbc', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '828b774de45d68bf808cf41cd2e0061c2790f788a7f16c4ec4987c4471292cbc')
  returning id
