  select q.id, v.label, v.body, v.ok from q, (values ('A', 'El més espectacular.', false), ('B', 'El més fàcil, segur i ràpid, evitant accions innecessàriament destructives.', true), ('C', 'Sempre per la coberta.', false), ('D', 'Sempre forçant la porta principal.', false)) as v(label, body, ok)
)
