  select 'Segons el manual de rescat urbà, com es caracteritzen les intervencions en alçada?', 'Hi ha risc de caiguda per a les víctimes i els bombers.', 'bomb_t33_rescat_urba', (select id from public.topics where slug = 'bomb-t33-rescat-urba'), 1, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-33-MAN.SVXX.000.pdf'), 'MAN.SVXX.000, § intervencions en alçada', 'Intervencions en alçada Les intervencions en alçada són una de les tipologies més freqüents i potencialment perilloses dins el rescat urbà.', null, '7d4b09109c596ea94e3e29e130bd74a3cd02f8d36bd412210292899ce9cc87a3', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '7d4b09109c596ea94e3e29e130bd74a3cd02f8d36bd412210292899ce9cc87a3')
