  select 'Segons el manual de rescat urbà, què permet l''ascens per corda fixa?', 'Requereix que la corda ja estigui instal·lada.', 'bomb_t33_rescat_urba', (select id from public.topics where slug = 'bomb-t33-rescat-urba'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-33-MAN.SVXX.000.pdf'), 'MAN.SVXX.000, § corda fixa', 'L’ascens per corda fixa és una tècnica que permet pujar de forma controlada i segura mitjançant una corda prèviament instal·lada.', null, '2c30ffb102b8535775caa57d03e20fc390fa592899c8613b41eafb33745b70ea', false
