  select 'Segons el manual de rescat urbà, què són els ascensors inclinats (funiculars)?', 'Són una variant dels electromecànics d''adherència, instal·lats a l''exterior.', 'bomb_t33_rescat_urba', (select id from public.topics where slug = 'bomb-t33-rescat-urba'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-33-MAN.SVXX.000.pdf'), 'MAN.SVXX.000, § 3.1 ascensors inclinats', 'Ascensors electromecànics d’adherència o Ascensors verticals o Ascensors inclinats (funiculars): són ascensors de gran capacitat instal·lats a l’exterior, amb la singularitat que, tant cabina com contrapès, es desplacen en un pla inclinat, no vertical.', null, 'cf3316fa01b098e047e7bc82ef6f9fafc032b35e9c998ddbea2dfe8c503f2549', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = 'cf3316fa01b098e047e7bc82ef6f9fafc032b35e9c998ddbea2dfe8c503f2549')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Ascensors electromecànics d''adherència de gran capacitat en què cabina i contrapès es desplacen en un pla inclinat.', true), ('B', 'Ascensors hidràulics amb el pistó inclinat sota la cabina.', false), ('C', 'Ascensors sense cambra de màquines instal·lats a l''interior dels edificis.', false), ('D', 'Ascensors electromecànics sense contrapès en què només la cabina es desplaça en pla inclinat.', false)) as v(label, body, ok)
)
