with q as (
  insert into public.questions (stem, explanation, category, topic_id, difficulty, locale, ai_generated, source_id, source_ref, source_excerpt, review_note, content_hash, is_test)
  select 'Una persona ha quedat atrapada en un ascensor hidràulic aturat entre dues plantes per un tall elèctric. Segons el manual de rescat urbà, com s''ha de moure la cabina?', 'Abans cal comprovar que està fora de servei i tallar la tensió; els hidràulics no permeten elevar la cabina sense la bomba en funcionament.', 'bomb_t33_rescat_urba', (select id from public.topics where slug = 'bomb-t33-rescat-urba'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-33-MAN.SVXX.000.pdf'), 'MAN.SVXX.000, § 3.2.2 rescat en ascensor hidràulic', 'Descripció: Consisteix a localitzar el motor hidràulic, comprovar que l’ascensor està fora de servei, tallar la tensió elèctrica des del quadre de comandament, activar la vàlvula de descàrrega manual, per tal que la cabina descendeixi lentament i de manera controlada fins a la planta inferior.', null, '1a8686cc2a308d45f6ba4a0c976e58034adc643b21190339561a56a51bf0ab76', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '1a8686cc2a308d45f6ba4a0c976e58034adc643b21190339561a56a51bf0ab76')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Girant el volant de la cambra de màquines per pujar-la a la planta superior.', false), ('B', 'Activant la vàlvula de descàrrega manual perquè la cabina baixi lentament fins a la planta inferior.', true), ('C', 'Desbloquejant el fre motor i elevant-la amb la bomba sense tensió.', false), ('D', 'Usant el desbloqueig automàtic de l''armari de control electrònic.', false)) as v(label, body, ok)
)
