  select 'Segons el manual de rescat urbà, on se situa habitualment el motor d''un ascensor sense cambra de màquines?', 'El motor és d''adherència, habitualment gearless; el quadre de maniobra pot estar a la planta superior o en una intermèdia.', 'bomb_t33_rescat_urba', (select id from public.topics where slug = 'bomb-t33-rescat-urba'), 2, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/DOCUMENTACIO-ESTUDI/Tema-33-MAN.SVXX.000.pdf'), 'MAN.SVXX.000, § 3.1.3 ascensors sense cambra de màquines', 'El seu funcionament es basa en un motor d’adherència, habitualment de tipus gearless, situat dins del mateix forat de l’ascensor, generalment a la part superior del recorregut.', null, '95619f1159c67c934e9b4166258f24419c4c7845640e41aef621233248f018d1', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '95619f1159c67c934e9b4166258f24419c4c7845640e41aef621233248f018d1')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'En una cambra de màquines a la coberta de l''edifici.', false), ('B', 'En un armari tècnic a la planta baixa, juntament amb una bomba hidràulica.', false), ('C', 'Dins del mateix forat de l''ascensor, generalment a la part superior del recorregut.', true), ('D', 'Sota la cabina, al fossat.', false)) as v(label, body, ok)
)
