  select 'Segons el manual d''inundacions, què estableix la pauta «Un dins / un fora»?', 'Aquest segon bomber ha de tenir equip complet i línia de recuperació preparada.', 'bomb_t34_inundacions', (select id from public.topics where slug = 'bomb-t34-inundacions'), 1, 'ca', true, (select id from public.sources where url = 'https://interior.gencat.cat/web/.content/home/030_arees_dactuacio/bombers/acces_al_cos_de_bombers/convocatories/convocatories_de_bombers/ACCES-81_26/ACTUALITZACIO-GUIA-ESTUDI/MAN.SVMN.001-Tema-34.-Intervencio-en-inundacions.pdf'), 'MAN.SVMN.001, § 5.1 un dins / un fora', '«Un dins / un fora» […] Sempre que un bomber entri al medi aquàtic, n’hi ha d’haver un altre a l’exterior preparat per intervenir en cas d’incidència.', null, '65034bd7fd06ff42bed7147159cd804eb37b2b2f34369287a7c41d44857c9304', false
  where not exists (select 1 from public.questions where locale = 'ca' and content_hash = '65034bd7fd06ff42bed7147159cd804eb37b2b2f34369287a7c41d44857c9304')
  returning id
), o as (
  insert into public.question_options (question_id, label, body, is_correct)
  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Que només pot entrar a l''aigua un bomber per servei.', false), ('B', 'Que el bomber ha d''entrar i sortir de l''aigua alternativament cada minut.', false), ('C', 'Que la víctima s''ha de treure de l''aigua d''una en una.', false), ('D', 'Que sempre que un bomber entri al medi aquàtic n''hi ha d''haver un altre a l''exterior preparat per intervenir.', true)) as v(label, body, ok)
)
